local gl = (type(GetLocale) == 'function') and GetLocale() or 'zhCN'
if gl ~= 'zhTW' then return end

local _, ns = ...

ns.EnsureClassGuide = function()
if ns.ClassGuide then return ns.ClassGuide end
ns.ClassGuide = {
    meta = {
        patch = "1.60.1",
        level = 30,
        updated = "2026/10/05",
    },

    specs = {
        WARRIOR = {
            arms = {
                updated = "2026/09/23",
                sections = {
                    { key = "changes", flow = {
                        { t = "p", v = "武器戰士在 PvE 和 PvP 方面都獲得了一些廣受歡迎的變化。它並未被徹底重做，而是對一些不太實用的技能進行了增強，使它們也得以派上用場。|s11573|現在已成為武器戰的更核心組成部分，它會隨攻擊強度提升而增強，並且現在可以造成傷害。|s1289682|，割裂現在有一定幾率激活|s11585|，持續 6 秒。|s1310222|並祈求造成昏迷效果了。|s1715|無法翻譯" },
                        { t = "tb", v = { { "|s1310222|", "一個強制下馬的實用技能。對所有目標造成 40% 武器傷害，對巨人、龍類以及騎乘坐騎的目標額外造成 80% 武器傷害。該技能為武器戰專屬，可在武器天賦樹深處解鎖。" }, { "|s402927|", "勝利衝鋒是《魔獸世界：無限》中新增的技能。所有戰士專精都可使用，施放時回覆 10% 最大生命值。在你擊殺一個非微不足道的敵人後，可以施放勝利衝鋒。" }, { "|s1290261|", "傳統的斧類專精，劍類專精，長柄武器專精，以及錘類專精現已合併為單一天賦，並加入了法杖！錘類和法杖現在無視護甲，而此前錘類有一定幾率擊暈目標。這一改動讓你在升級過程中可以更自由地切換武器類型。" }, { "|s1289682|", "血之狂熱是一項新天賦，旨在讓|s11573|更成為武器輸出循環中的核心技能。血之狂熱使割裂有一定幾率激活|s11585|，持續6秒。激活幾率隨投入的點數增加而提升血之狂熱." }, { "|s12862|", "《無限》版本中新增的另一個天賦是強化猛擊。該天賦每投入一點可使|s1464|的施法時間縮短，更重要的是使你的猛擊施放時不再中斷近戰攻擊節奏！" } } },
                        { t = "tb", v = { { "|s1464|", "猛擊現在擁有15秒冷卻時間。" }, { "|s11573|", "割裂獲得了加強，現在能更好地隨攻擊強度提升而成長，並且隨着《無限》版本中對週期性傷害的改動，它現在也能造成暴擊。" }, { "|s11580|", "雷霆一擊的降低攻擊速度效果從10%提升至20%。" }, { "|s12834|", "深重傷口現在也可以造成暴擊。" }, { "|s11550|", "戰鬥怒吼的持續時間從2分鐘延長至3分鐘。" }, { "|s1160|", "挫志怒吼的持續時間從30秒延長至45秒。" }, { "|s20230|", "反擊的冷卻時間從30分鐘縮短至15分鐘。同時不再與以下技能共享冷卻時間：|s871|或|s1719|." }, { "|s871|", "盾牆的冷卻時間從30分鐘縮短至15分鐘，但減傷效果從75%下調至60%。同時不再與以下技能共享冷卻時間：|s20230|或|s1719|." } } },
                    } },
                    { key = "viability", flow = {
                        { t = "p", v = "《魔獸世界：無限》的目標是確保每個職業和天賦專精都具備可用性。武器天賦此前主要以 PvP 為核心，因此進行了調整，使其在 PvE 和 PvP 中都更具可用性。例如|s1290261|的調整使錘類和法杖類武器無視護甲。護甲穿透是 PvE 中極為重要的屬性，因為它能提升怒氣獲取速度。" },
                    } },
                    { key = "sw", flow = {
                        { t = "good", v = { "機動性- 憑藉衝鋒和攔截，在戰場上擁有出色的機動性。", "爆發群體傷害- 配合橫掃攻擊和順劈斬積攢怒氣時，能打出強力的爆發群體傷害。", "控制- 可通過強化斷筋輕鬆限制敵人。" } },
                        { t = "bad", v = { "怒氣依賴- 攻擊未命中或被招架時，容易陷入怒氣匱乏。", "持續群體傷害- 由於怒氣獲取有限，難以維持長時間的群體傷害。", "自我治療- 相比其他專精，被動續航能力有限。" } },
                    } },
                    { key = "beginner", flow = {
                        { t = "p", v = "在《魔獸世界：無限》中，武器戰士現在是新玩家的絕佳選擇。此前，武器專精一直被視為對新玩家很不友好的專精，原因在於該專精缺乏怒氣生成，且過度依賴平砍計時器。當你剛接觸魔獸世界時，平砍計時器的概念可能很難理解，尤其是在沒有插件的情況下無法準確追蹤，而你還有一大堆其他事情要關注。在《無限》中，現在有了內置的平砍計時器，這對新玩家來說至關重要。除此之外，新加入的天賦|s12862|消除了重置平砍計時器|s1464|帶來的懲罰性影響。" },
                    } },
                    { key = "systems", flow = {
                        { t = "p", v = "在《魔獸世界：無限》中，戰士有一個基礎系統：姿態。作為武器戰士，你會頻繁切換姿態；這被稱為姿態舞.姿態舞指的是當你能夠施放需要某個姿態的法術時，快速切換到該姿態，然後迅速切回原來的姿態。例如，從|s2458|切換到|s2457|以便在|s11585|可用時立即施放，然後立刻切回|s2458|." },
                        { t = "p", v = "你也可以為了獲得某個姿態的效果而切換姿態。例如，如果你需要在副本里坦克一個怪物，你可以選擇|s71|來減少受到的敵人傷害。" },
                    } },
                    { key = "races", flow = {
                        { t = "p", v = "戰士的獨特之處在於，遊戲中每個種族都可以選擇戰士。這讓你在選擇種族時有很大的自由度，取決於你的偏好或你想要的種族特長。" },
                        { t = "races", v = { { race = "人類", side = "alliance", mark = "tick" }, { race = "矮人", side = "alliance", mark = "tick" }, { race = "暗夜精靈", side = "alliance", mark = "tick" }, { race = "侏儒", side = "alliance", mark = "tick" }, { race = "獸人", side = "horde", mark = "tick" }, { race = "亡靈", side = "horde", mark = "tick" }, { race = "牛頭人", side = "horde", mark = "tick" }, { race = "巨魔", side = "horde", mark = "tick" } } },
                        { t = "p", v = "無限服新增的職業-種族組合" },
                        { t = "p", v = "在選擇種族時沒有絕對的差選項。雖然有些種族會比其他種族更強，但這些差距非常微小。對聯盟來說，根據你是更傾向於 PVE 還是 PVP，種族選擇會更有講究；而部落方面，最佳選擇相對比較直接。" },
                        { t = "p", v = "新種族" },
                        { t = "p", v = "天裔戰士是隨《魔獸世界：無限》一同推出的新種族，聯盟和部落均可選擇。可惜的是，天裔的種族特長更側重於改善升級體驗，對於追求最強終局表現的玩家來說會稍顯遜色。天裔可以使用|s1259416|，讓他們能夠從高處跳下、在空中快速移動，並在空中改變方向。天裔還可以在主題區域使用|s1259686|，在元素匯聚點附近使用可獲得持續 15 分鐘的 10% 移動速度加成；否則只能持續 30 秒。天裔擁有兩項傷害類種族特長|s1259707|和|s1259710|。他們還擁有一個名為的自療種族特長|s1259705|." },
                        { t = "h4", v = "聯盟" },
                        { t = "p", v = "夜精靈戰士 儘管聯盟種族的優劣較為主觀，但夜精靈似乎是《無限》中聯盟武器戰最佳的 PVE 種族。|s1259799|非常強力，在15秒內提升暴擊10%。由於武器天賦的重新調整，暴擊的收益更高了，|s11573|和|s12834|現在可以造成暴擊。此外，暴擊屬性與飾品組合在一起非常強力。除此之外，夜精靈還可以使用|s20580|，|s20582|，以及|s20585|." },
                        { t = "p", v = "侏儒戰士 侏儒戰士是聯盟的另一個絕佳選擇，在 PvE 和 PvP 中都是更為全面的選擇。侏儒可以使用|s1259812|，激活後使你接下來施放的3個法術造成的傷害提高，同時怒火值降低10%。其種族特長|s1259802|現在還加入了怒氣值，提高了武器戰的最大怒氣上限。此外，他們的種族特長|s20589|現在還能免疫移動受限類效果。侏儒還可以使用|s20593|." },
                        { t = "p", v = "人類戰士人類也是聯盟戰士的強力種族選擇，但在《魔獸世界：無限》中更偏向 PvP 導向。人類現在擁有著名的種族特長|s1259718|，立即解除所有昏迷效果。人類還非常擅長對付潛行目標，依靠|s20600|人類不僅在 PvP 方面表現出色，因為他們可以|s20597|，在裝備劍類武器時暴擊提高2%。他們還可以使用|s20598|，這是一個很實用的種族特長。" },
                        { t = "p", v = "矮人戰士 矮人戰士是戰士職業的穩健之選。他們的|s1259719|使他們的錘類武器暴擊幾率提高1%，並且他們的|s1259721|對野獸造成的傷害提高5%。他們還可以使用|s20594|，立即移除流血、中毒和疾病效果並免疫這些效果，同時使受到的所有物理傷害降低10%，持續8秒。此外，矮人還可以使用|s2481|." },
                        { t = "h4", v = "部落" },
                        { t = "p", v = "獸人戰士 獸人通常是部落的最佳選擇。它提供|s20572|，這在PVE和PVP中都非常出色。它還有|s20574|，使斧類武器的暴擊幾率提高1%。除此之外，它還有|s20573|，使昏迷持續時間縮短20%，以及|s1299026|，使你對詛咒和災禍免疫，並使受到的魔法傷害降低15%，持續8秒。" },
                        { t = "p", v = "巨魔戰士 巨魔是部落戰士的第二佳選擇。它可以使用|s20554|，使你的近戰攻擊速度提高10%，持續10秒。它還有另一個進攻性種族特長，通過|s20557|使對野獸類型敵人造成的傷害提高5%。巨魔還有2個治療性種族特長。它們是|s20555|和|s1260270|." },
                        { t = "p", v = "牛頭人戰士 牛頭人戰士的傷害輸出較低，但更注重生存能力和群體控制。牛頭人還可以使用|s20549|，眩暈8碼範圍內的5個敵人0.5秒。其種族特長|s20550|提供5%最大生命值和1%的額外命中加成。除此之外，牛頭人現在還可以使用|s12566|，在40級之前練級時非常好用，以及|s20552|，可以賺取一些額外的金幣。" },
                        { t = "p", v = "亡靈戰士 亡靈可以說是戰士較差的選擇之一，對PvE或PvP都沒有實際增益。|s7744|還不錯，但戰士已經有了名為|s18499|的恐懼免疫技能。亡靈還可以使用|s20577|和|s5227|，練級時很實用。他們還有一個新天賦|s1260189|" },
                        { t = "p", v = "無限服中武器戰士的專業" },
                        { t = "p", v = "每種專業都有各自的利弊，不存在糟糕的專業搭配。你可以選擇兩項採集專業來賺取更多金幣，或選擇兩項製造專業。無論選擇哪種，只要符合你的目標即可。以下列出的專業是我推薦給大多數戰士的，因為在我看來，它們在練級和後期的終局玩法中都能提供最佳的路線。" },
                        { t = "p", v = "工程學對於武器戰而言在經典舊世版本中，工程學通常是終局PvE和PvP的最佳專業選擇，這一點在無限版中並未改變。在終局內容裏，工程學憑藉各種小道具和炸彈能帶來巨大的實用性和傷害加成。不過我不建議在升級過程中選擇它，因為它的營火增益效果價值有限，而且炸彈若經常使用成本也不低。升級時我更傾向於選擇下面提到的另外兩個專業，待滿級後再放棄其中一個轉而學習工程學。" },
                        { t = "p", v = "採礦對於武器戰而言採礦在無限版中有了幾項關鍵改動。最大的改動是地圖上礦點的數量。以前，你的等級提升速度往往快於採礦技能的提升，這迫使你不得不返回舊區域練採礦技能，才能在新升級區域採集礦點。在無限版中，這個問題基本得到了解決。礦點數量大幅增加，以至於我經常直接跳過一些礦點，技能依然跟得上進度。不過如果你仍然遇到這個問題，熔煉的新改動也能解決它。現在你可以從1一直熔煉到300點技能，所以即便你跳過了礦點，也可以通過熔煉來提升技能，而不必返回舊區域花時間採礦。" },
                        { t = "p", v = "升級時選擇採礦的另一個重要原因是它的營火增益效果。它是戰士可用的最佳營火增益之一，前提是你不是與聖騎士組隊升級，因為該增益無法與聖騎士的疊加。|s19838|." },
                        { t = "p", v = "鍛造對於武器戰而言在無限版中，無論是為了終局內容還是升級過程，鍛造都是戰士的絕佳選擇。鍛造新增了多種配方，讓你在升級過程中就能打造更精良的裝備。資料片上線時，鍛造也會很容易練，因為你可以將武器等製品以高於成本的價格出售。鍛造搭配採礦是升級期間的穩健組合，你可以在採集礦石熔煉後，回到主城利用熔煉所得來製作裝備升級。" },
                        { t = "p", v = "鍛造的營火增益同樣是戰士可用增益中的佼佼者，前提是你不是與薩滿祭司組隊升級，因為該增益無法與薩滿祭司的疊加。|s25361|." },
                    } },
                },
            },
            fury = {
                updated = "2026/09/21",
                sections = {
                    { key = "changes", flow = {
                        { t = "p", v = "狂怒戰士在《魔獸世界：無限》中經歷了多項重大改動，既有直接的也有間接的。其中最重要的是怒氣生成的改動；《魔獸世界：無限》中的怒氣現在已被標準化，與當年《大災變》所做的改動類似。這意味着攻擊會根據公式在固定範圍內生成固定數量的怒氣；怒氣不再與直接自動攻擊造成的傷害掛鉤，暴擊也不會產生額外怒氣。因此，我們的怒氣生成不隨裝備而提升，增加怒氣獲取的唯一方式就是受到更多傷害。這會導致我們的怒氣生成相比其他版本的經典狂怒戰士大幅降低，進而減少我們可以使用的技能數量。我們現在必須更加謹慎地管理怒氣，無法再像以前那樣頻繁地使用技能。" },
                        { t = "p", v = "此外，敵人的護甲無法再被削減到之前的程度，|s9907|並且|s11717|不再與它們的護甲削減效果疊加。這進一步大幅降低了我們的傷害，尤其因為我們完全依賴物理傷害，並不具備任何基礎的神力傷害技能。" },
                        { t = "tb", v = { { "|s1310315|", "一項源自《燃燒的遠征》的新天賦，讓我們的旋風斬能夠同時命中主副手武器，使我們的副手也能參與群體傷害輸出，同時讓我們可以選擇的副手武器種類更加豐富。" }, { "|s402927|", "另一項來自《燃燒的遠征》的技能，在20級時可習得，會在擊殺觸發時激活，允許施放該技能，造成中等傷害並根據生命百分比回覆少量生命值。" }, { "|s1310185|", "一項新的基礎冷卻能力，讓你在切換姿態時保留少量怒氣。" } } },
                        { t = "tb", v = { { "|s23881|", "該技能的傷害加成被大幅下調，從攻擊強度的45%降至40%，但獲得了一個隨等級增加的小幅且幾乎可以忽略不計的固定傷害加成。" }, { "|s12317|", "狂暴現在會在受到任何直接傷害時觸發，而不再僅限於受到暴擊時。" }, { "|s23584|", "現在為副手提供10%的命中率加成，作為移除\\\"下次攻擊未命中懲罰\\\"漏洞的補償。" } } },
                    } },
                    { key = "viability", flow = {
                        { t = "p", v = "乍看之下，狂怒戰士似乎與基礎經典版中的對應天賦相當相似——它保持着相同的輸出循環，使用類似的天賦構築，技能套裝的變化或新增也非常少。然而，深入觀察後會發現，在副本及團隊副本的末期內容中，狂怒戰士的處境相當艱難。" },
                        { t = "p", v = "世界增益的移除對狂怒戰士是一個巨大打擊，它曾是遊戲中成長性最強的天賦之一。此外，怒氣標準化嚴重限制了我們的爆發技能使用頻率，而首領護甲的提高進一步削減了我們的傷害。如今隊伍配置比以往任何時候都更加重要——關鍵的團隊增益如|s10614|並且|s17007|其重要性比以往更高，由於其他屬性的缺失，它們的相對威力被大幅提升，因此務必將其加入輸出循環。" },
                        { t = "p", v = "我們的技能也有一些顯著改動——|s23881|遭到了削弱，儘管它本就因我們可獲得的攻擊強度較低而處於疲軟狀態。強化戰鬥怒吼天賦也已被移除，這降低了我們的團隊增益能力。或許最值得注意的是，我們標誌性的輸出爆發技能，|s1719|的冷卻時間沒有發生任何改動，依然為30分鐘，而類似的冷卻技能例如|s417141|擁有3分鐘的冷卻時間。" },
                    } },
                    { key = "sw", flow = {
                        { t = "p", v = "在戰士強勢的領域，即低目標順劈場合，戰士表現出色，無可匹敵。但在長時間的單體戰鬥中，尤其是幾乎沒有承受傷害時，表現會較差。" },
                        { t = "good", v = { "強化順劈斬- 對低血量目標有強大的群體傷害能力，技能如|s20569|並且|s1680|.", "強力爆發- 強力的爆發技能，例如|s12328|讓我們在關鍵時刻打出爆發傷害。", "生存能力強- 高基礎生命值加上穿戴板甲的能力，讓狂怒戰士能夠硬抗傷害。" } },
                        { t = "bad", v = { "依賴裝備- 需要大量裝備才能達到特定屬性上限", "主要爆發技能冷卻時間長-|s1719|的冷卻時間為30分鐘。" } },
                    } },
                    { key = "beginner", flow = {
                        { t = "p", v = "狂怒專精表面上相對簡單——即便要打出高水平表現，其輸出循環也不算特別複雜，而且身板夠硬，犯錯也能存活。不過，它對怒氣管理的要求有時頗為複雜，而且出了名的算不上最強的練級專精。在單人內容中可能會比較喫力，有他人支援時表現最佳，同時也適合參與團隊內容。" },
                    } },
                    { key = "races", flow = {
                        { t = "p", v = "乍看之下，戰士的可選種族競爭相當激烈，獸人顯著領跑，但巨魔、暗夜精靈和亡靈緊隨其後。不過，隨着未來的數值調整，這一格局可能會發生變化。新種族天裔雙方陣營均可選擇戰士。" },
                        { t = "races", v = { { race = "人類", side = "alliance", mark = "tick" }, { race = "矮人", side = "alliance", mark = "tick" }, { race = "暗夜精靈", side = "alliance", mark = "tick" }, { race = "侏儒", side = "alliance", mark = "tick" }, { race = "獸人", side = "horde", mark = "tick" }, { race = "亡靈", side = "horde", mark = "tick" }, { race = "牛頭人", side = "horde", mark = "tick" }, { race = "巨魔", side = "horde", mark = "tick" } } },
                        { t = "p", v = "無限服新增的職業-種族組合" },
                        { t = "h4", v = "聯盟" },
                        { t = "p", v = "對聯盟的狂怒戰士來說，暗夜精靈似乎是首選，其種族特長提供強力的主動暴擊提升和額外移動速度。侏儒看起來也是個穩妥的選擇，其新種族特長可以與我們的爆發技能搭配，打出高額的傷害爆發，還附帶一些脫離控制的實用功能。人類和天裔或許各有小衆用途，但似乎弱於其他選項。矮人則看起來完全不佔優勢。" },
                        { t = "h4", v = "部落" },
                        { t = "p", v = "獸人似乎是狂怒戰士整體最強的種族，擁有兩種強大的傷害增益種族特長，還有昏迷時間縮短和強力的魔法防禦。巨魔和亡靈同樣相當強力，他們都擁有強力的種族特長，可能不如獸人那樣全面，但能在其他方面有所補足。天裔在以急速為核心價值的首領戰中可能會有用武之地，取決於急速的價值。牛頭人的命中加成相對較弱，其昏迷技能在PvP中可能有用武之地。" },
                    } },
                    { key = "prof", flow = {
                        { t = "p", v = "初步發現表明，工程學將再次成為狂怒戰士最強的專業——其提供的強力道具和爆炸物能增強狂怒戰士的優勢與機動性，尤其是在單刷內容中。鍊金術似乎也是個強力選擇，其合劑與藥劑的持續時間和效果增強可能帶來可觀的屬性提升。" },
                    } },
                },
            },
            prot = {
                updated = "2026/10/03",
                sections = {
                    { key = "changes", flow = {
                        { t = "p", v = "防護戰士一直是經典舊世裏首選的坦克，因為他們擁有最完整的工具箱。也就是說，進入《魔獸世界：無限》後，防護戰士是改動最小的坦克。話雖如此，防護戰士這次的更新也足夠多，足以改變我們玩這個專精的思路。" },
                        { t = "p", v = "經典舊世坦克的一個問題在於：當輸出玩家隨裝備成長時，坦克未必以同樣的速度成長，坦克與輸出之間的仇恨鴻溝會隨時間越拉越大。結果就是，團本環境裏的戰士坦克大多選擇玩一種輸出型坦克，人稱狂暴坦（Fury-prot）——畢竟承受的傷害低，而仇恨需求又高。" },
                        { t = "p", v = "《魔獸世界：無限》為解決這個問題做了不少努力：在防護天賦樹裏直接加入了仇恨係數（例如|s12792|），並給|s11601|這類技能追加了額外的攻擊強度加成。我們還預計傷害構成與戰鬥時長會與以往不同，因此劍盾流派很可能迴歸——即便創意_builds依然有發揮空間。" },
                        { t = "p", v = "在《無限》裏，防護戰士只通過|s402927|獲得一個新技能，但它似曾相識。話雖如此，幾乎整個防護天賦樹都被重做了，我們的工具箱比以前寬了不少。" },
                        { t = "tb", v = { { "|s402927|", "立即攻擊目標，造成 (1 + 攻擊強度 * 15 / 100) 點傷害，併為你恢復最大生命值的10%。只能在擊殺非普通敵人後的20秒內使用。這讓戰士在練級路上獲得了急需的續航。" }, { "|s1310317|", "你的衝鋒技能現在可以在防禦姿態下使用。" }, { "|s16538|", "裝備盾牌時，你所造成的所有傷害提高10%。" }, { "|s23602|", "裝備盾牌時，你每閃避或招架一次就產生5點怒氣。" }, { "|s29787|", "使你的進攻類技能的怒氣消耗降低3點。" } } },
                        { t = "p", v = "防護 Warrior 的改動雖然多，但有一點值得單獨一提：|s11581|現在可以在|s71|下使用，冷卻也從4秒延長到6秒。再加上大量新增的怒氣生成天賦，以及受到傷害（包括吸收效果）就能回怒的機制，防護戰士終於有了同時拉住 1-2 個以上目標的能力，而不必在怪物之間瘋狂切換目標。防禦姿態下可用的雷霆一擊（因此享受姿態的仇恨加成），加上不會怒氣枯竭的|s20569|額外施放機會，戰士在地下城和團本里的體驗應該會舒服不少。" },
                        { t = "tb", v = { { "|s11581|", "需要戰鬥姿態。用雷霆震擊附近的敵人，使他們的攻擊間隔延長10%，持續30秒，並對其造成103點傷害。最多影響4個目標。", "需要戰鬥姿態、防禦姿態。用雷霆震擊附近的敵人，使他們的攻擊間隔延長20%，持續30秒，並對其造成傷害。最多影響4個目標。" }, { "|s2565|", "使你的格擋幾率提高75%，持續5秒，但只能格擋1次攻擊。", "使你的格擋幾率提高75%，持續7秒，且可以格擋2次攻擊。" }, { "|s871|", "使你受到的近戰、遠程攻擊和法術傷害降低75%，持續10秒。30分鐘冷卻。", "使你受到的所有傷害降低60%，持續12秒。15分鐘冷卻，且可通過天賦進一步縮短。" }, { "|s1310185|", "天賦：改變姿態時最多保留25點怒氣。", "基礎技能：改變姿態時最多保留10點怒氣。" }, { "|s12298|", "使你用盾牌格擋攻擊的幾率提高5%，並在格擋發生時有100%的幾率產生1點怒氣。", "使你用盾牌格擋攻擊的幾率提高5%，並在你格擋時有100%的幾率產生5點怒氣。" }, { "|s12297|", "使你的防禦技能提高10點。", "使你的防禦技能提高20點。" }, { "|s12301|", "使你的血性狂怒技能即時產生的怒氣提高2點。", "使你的血性狂怒技能產生的所有怒氣提高50%。" }, { "|s12797|", "使你的復仇技能有15%的幾率擊暈目標3秒。", "使你的復仇技能造成的傷害提高60%。" }, { "|s12792|", "在防禦姿態下，使你的攻擊產生的威脅值提高15%。", "在防禦姿態下，使你產生的所有威脅值提高30%，並使你的攻擊強度提高10%。" } } },
                    } },
                    { key = "beginner", flow = {
                        { t = "p", v = "防護戰士本身並不是特別難上手的專精，但在學習拉怪、尤其是多目標仇恨管理時，可能還是會遇到一些痛點。" },
                        { t = "p", v = "《魔獸世界：無限》讓戰士坦克變得更寬容了：即使不玩姿態舞（在不同姿態之間來回切換以使用|s71|下無法使用的技能），你也能發揮這個專精的大部分價值。姿態舞是你隨着對職業理解的加深應該去掌握的系統，但由於|s11581|和|s11578|（天賦支援）都可以在防禦姿態下使用，不玩姿態舞你依然能當一個稱職的坦克。" },
                        { t = "p", v = "一個基本的經驗法則：除非怒氣嚴重溢出，否則不要用|s78|。在練級過程中隨着怒氣生成天賦增多，這點會越來越不重要——一般來說，用|s11597|和|s25288|這類技能能打出更高的傷害和仇恨。|s78|的另一個問題在於它綁定你的近戰揮擊：不僅使用要花怒氣，還讓你失去這一次揮擊本該產生的怒氣。" },
                    } },
                    { key = "systems", flow = {
                        { t = "ul", v = { { text = "|s2457|- 產生的威脅值降低20%。\n該姿態下的關鍵技能：|s20230|、|s11585|、|s20662|，以及|s100|（除非有天賦支援）。" }, { text = "|s2458|- 爆擊幾率提高3%，受到的所有傷害提高10%。\n該姿態下的關鍵技能：|s1719|、|s1680|、|s20252|，以及|s20662|。" }, { text = "|s71|- 受到的傷害降低10%，造成的傷害降低10%，產生的所有威脅值提高30%。這是防護戰士坦克的基準姿態。\n該姿態下的關鍵技能：|s871|、|s2565|，以及|s676|。" } } },
                        { t = "p", v = "戰士用怒氣作為資源系統。怒氣來自：用普通近戰揮擊造成傷害、承受傷害、|s11578|和|s2687|這類技能，以及通過天賦|s12298|和|s1310316|在格擋、閃避或招架攻擊時產生。在《魔獸世界：無限》裏，怒氣會根據你打的內容不同而成為相當大的制約，所以一個合格的戰士，關鍵就在於你如何分配這些怒氣。" },
                        { t = "p", v = "此外，戰士有3種姿態：|s2457|、|s2458|和|s71|。這些姿態各自帶有專屬效果，但部分技能只能在特定姿態下使用。" },
                        { t = "p", v = "設定好在不同姿態之間來回切換以釋放特定技能的宏，對你玩好防護戰士至關重要。|s1310185|成為基礎被動讓這件事變容易了一些，武器系天賦裏的|s12295|還提供了額外的怒氣保留。" },
                    } },
                    { key = "races", flow = {
                        { t = "p", v = "戰士需要好好琢磨選什麼種族——因為遊戲裏的所有種族都能當戰士。由於最近的種族平衡調整，哪個種族的整體收益最高還不好說。更準確地說，每個種族都有自己的細分定位，即便在同一個細分裏（比如高端團本），不同種族也會因首領類型不同而互有勝負。總之，《魔獸世界：無限》裏沒有經典舊世那種一枝獨秀的選擇，所以只要你不追求極限優化，選一個你喜歡的審美和幻想設定的種族就好。" },
                        { t = "races", v = { { race = "人類", side = "alliance", mark = "tick" }, { race = "矮人", side = "alliance", mark = "tick" }, { race = "暗夜精靈", side = "alliance", mark = "tick" }, { race = "侏儒", side = "alliance", mark = "tick" }, { race = "獸人", side = "horde", mark = "tick" }, { race = "亡靈", side = "horde", mark = "tick" }, { race = "牛頭人", side = "horde", mark = "tick" }, { race = "巨魔", side = "horde", mark = "tick" } } },
                        { t = "p", v = "《無限》新增的職業-種族組合" },
                        { t = "h4", v = "聯盟" },
                        { t = "p", v = "人類戰士" },
                        { t = "p", v = "在最初的《魔獸世界》裏，人類是事實上的最優種族，因為他們擁有價值極高的武器專精加成。在《魔獸世界：無限》中，種族加成經過重做，|s20597|現在改為使所有攻擊和法術的爆擊幾率提高2%。由於滾動型持續傷害與目標身上的減益不再有數量上限，|s23255|如今成了可用的天賦，人類因此變成一個非常有趣的選擇。" },
                        { t = "p", v = "|s1259718|也加入了遊戲，每3分鐘可以解除一次昏迷效果。這在PvP裏的價值顯而易見，在PvE中同樣大有用處。" },
                        { t = "p", v = "假設你最好的武器裏劍類隨手可得，人類很可能就是你的最佳選擇。" },
                        { t = "p", v = "矮人戰士" },
                        { t = "p", v = "矮人同樣能通過種族特長獲得大量實用功能：|s1259719|提供1%爆擊幾率加成，雖然只有人類版本的一半強度。" },
                        { t = "p", v = "為了彌補強度差，矮人擁有|s20594|——由於流血效果無法被驅散，它的特定使用場景相當強力。" },
                        { t = "p", v = "此外，|s1259721|對野獸的傷害提高5%。世界上野獸類敵人的數量出乎意料地多，這讓它成為練級神器。團本環境裏野獸通常不多，但《魔獸世界：無限》後續還會有新團本，這個種族特長的完整價值還無法評估。" },
                        { t = "p", v = "總而言之，矮人是一個很棒的備選，在特定場景下甚至可能優於人類。" },
                        { t = "p", v = "侏儒戰士" },
                        { t = "p", v = "侏儒在《無限》裏其實變得有趣起來，但主要是作為PvP選項。作為新增內容，侏儒獲得了|s1259817|，使你的下3次攻擊提高10%，與|s12328|這類技能配合極佳。此外，|s20589|被改為不僅能解除移動限制效果，還會在使用後讓你免疫這些效果3秒，與|s1044|的機制類似。" },
                        { t = "p", v = "在PvE環境裏，侏儒不會是我的第一或第二選擇。" },
                        { t = "p", v = "暗夜精靈戰士" },
                        { t = "p", v = "暗夜精靈憑藉重做後的種族特長在《無限》裏強得出人意料。你現在擁有一個和侏儒一樣的3分鐘冷卻技能，但效果是通過|s1259799|獲得15秒的10%爆擊增益。它與|s12328|這類技能配合得不錯，但往防護深處加點時協同有限。你的主攻冷卻技能|s1719|本身就把爆擊率拉到100%，所以這兩個技能絕不應該同時開。" },
                        { t = "p", v = "|s20582|現在除了1%閃避還帶來2%移動速度，這可不是小數目；而且能用上|s20585|對團隊氛圍也很友好——畢竟你死後跑屍的時間越短，你罵治療的時間就越少。" },
                        { t = "h4", v = "部落" },
                        { t = "p", v = "獸人戰士" },
                        { t = "p", v = "對防護戰士來說，獸人在攻防兩端看起來都特別強。|s20574|只要你裝備斧類武器就提供1%的固定爆擊提升，雖然我們還得看看畢業武器裏有幾把是斧子，但可以假定它有不小的價值。" },
                        { t = "p", v = "|s20572|現在改為2分鐘冷卻、15秒內提高10%攻擊強度。我們沒有任何能與它對齊的冷卻技能，但它依然是一個強力爆發。值得一提的是，部分技能不喫攻擊強度加成，比如按格擋值成長的|s23925|。" },
                        { t = "p", v = "|s1299026|已成為一個小型法傷防禦冷卻技能，現在還能解除詛咒與災厄效果。|s20573|帶來的20%昏迷時長縮減，在經典式環境裏同樣不容小覷。" },
                        { t = "p", v = "獸人看起來是戰士最全面的備選種族。" },
                        { t = "p", v = "牛頭人戰士" },
                        { t = "p", v = "|s20550|經過重做，為防護戰士提供了極強的功能性——因為我們非常看重生命值和命中。雖然還沒見到滿級階段的配裝風格，但可以放心假設：這1%命中總能給你帶來大量價值，無論是湊近戰命中上限，還是給|s355|提供額外的命中幾率。" },
                        { t = "p", v = "|s20549|也能派上用場，尤其是在練級和刷地下城時；但要注意面對多個怪物時的施法推後——施法過程中你無法格擋、閃避或招架。" },
                        { t = "p", v = "|s1259918|經過重做，改為提高移動速度（尤其是在脫戰狀態下），最高可疊加到30%。這在野外練級時好用到離譜，尤其是在 40 級之前——經典式練級體驗裏有大把的路要趕。" },
                        { t = "p", v = "對防護戰士來說這是一個非常強的選擇，特別適合偏好防禦型打法的玩家。" },
                        { t = "p", v = "巨魔戰士" },
                        { t = "p", v = "巨魔保留了原有的種族特長，新增了|s1260270|：6秒內回覆50%生命值，戰鬥內外均可使用。任何移動、動作或受到傷害都會打斷該效果，但它依然有相當不錯的實用性，尤其是在PvP中對陣非持續傷害職業時——你可以在施放|s5246|之後回血。在PvE中也有用，但在團本環境裏價值較低。" },
                        { t = "p", v = "此外，|s20557|對野獸的傷害提高5%。世界上野獸類敵人的數量出乎意料地多，這讓它成為練級神器。團本環境裏野獸通常不多，但《魔獸世界：無限》後續還會有新團本，這個種族特長的完整價值還無法評估。" },
                        { t = "p", v = "由於怒氣的標準化，|s20554|同樣不容小覷，它提供的價值可能超出我們的預期。" },
                        { t = "p", v = "亡靈戰士" },
                        { t = "p", v = "亡靈種族獲得了一些看起來對戰士很有價值的新種族技能。攻擊敵人時，|s1260189|有5%的幾率抽取目標，最多為你回覆自身最大生命值的5%。目前來看它的內置冷卻似乎只有1秒，觸發會相當頻繁。不過，具體哪些技能能觸發該效果、低傷害技能能抽到多少血，仍不明確。" },
                        { t = "p", v = "此外，亡靈還有|s7744|，在PvP和PvE裏都有強力使用場景。|s20577|對戰士來說也非常受歡迎，練級期間尤其如此。" },
                        { t = "h4", v = "聯盟與部落通用" },
                        { t = "p", v = "天裔戰士" },
                        { t = "p", v = "新種族天裔對防護戰士來說相當平淡：|s1259707|只提供場景性的功能。世界裏的元素生物出現頻率不算高，但根據後續更新的新內容類型，我們也許會在新團本里見到更多。" },
                        { t = "p", v = "|s1259416|可以當作緩落類技能使用，在開放世界裏（尤其是想從高處跳下來的時候）相當實用。" },
                        { t = "p", v = "|s1259710|的價值還有待觀察，但急速歷來對防護戰士的收益都很低。" },
                    } },
                    { key = "prof", flow = {
                        { t = "p", v = "目前還不清楚哪些專業技能對防護戰士收益最大。縱觀各個經典資料片，工程學一直是最強選項。坦克一直面臨「夠不着遠處怪物、拉不到仇恨」的問題，而工程師造的手雷正好能解決這個問題。" },
                        { t = "p", v = "不過，除工程學外的所有專業都能通過屬性獲得一項特殊加成。這些屬性加成能否勝過工程學的收益，還有待觀察。" },
                        { t = "p", v = "開局選工程學搭配鍛造或珠寶加工，大概率是穩妥的組合。" },
                    } },
                },
            },
        },
        PALADIN = {
            holy = {
                updated = "2026/09/21",
                sections = {
                    { key = "changes", flow = {
                        { t = "p", v = "神聖聖騎士的新增內容主要專注於補齊此前工具集中的短板，並簡化一些繁瑣的操作。整體效果是一套更加均衡的技能體系，讓你能夠專注於戰鬥本身，而不是不停地維護增益。" },
                        { t = "p", v = "其中最核心的就是|s1311595|，這是神聖天賦樹的新終極技能。它是一項全新的群體治療手段，同時與|s20930|有大量聯動，甚至可以用於造成傷害。" },
                        { t = "tb", v = { { "|s1311595|", "為目標施加光明警戒，持續30秒。你對其施放的下一記聖光閃現不進入冷卻時間，並使友方目標治療其小隊成員，或使敵方目標受到神聖傷害，同時返還光明警戒75%的法力值。同一聖騎士對同一小隊同時只能存在1個光明警戒。" }, { "|s10333|", "一次瞬發打擊，造成40%武器傷害，並附加額外神聖傷害。" }, { "|s1310897|", "使你免疫沉默和打斷效果，持續6秒。" } } },
                        { t = "p", v = "現有技能方面最重要的改動是祝福類增益的持續時間延長至1小時。這意味着過去每5分鐘就要為小隊刷新增益的操作已經不復存在。" },
                        { t = "tb", v = { { "像|s25290|", "祝福的持續時間由5分鐘延長至1小時。" }, { "|s20271|", "使用時不再消耗當前已激活的聖印增益。" } } },
                    } },
                    { key = "beginner", flow = {
                        { t = "p", v = "神聖聖騎士的核心循環相當簡單，新玩家也能輕鬆上手。原本那些令人煩躁、不順暢的地方在《魔獸世界：無限》都得到了改善；該專精自給自足，擁有強力的治療能力、非常優秀的防禦技能和可觀的傷害輸出，練級體驗會非常順暢。" },
                        { t = "p", v = "唯一可能稍顯複雜的地方在於你最終會掌握相當多的技能。隨着等級提升，你會解鎖各種不同的祝福、增益、光環和聖印，可能需要花點時間才能學會每種情況下最好用哪個。" },
                    } },
                    { key = "systems", flow = {
                        { t = "p", v = "聖騎士玩法的一部分就是管理你的聖印。這些效果包括|s20349|和|s20357|等，它們會給你不同的增益，而你同一時間只能激活一種聖印效果。此外，使用|s20271|會根據你當前激活的聖印對目標造成不同效果。例如，被光明聖印審判的敵人有幾率治療攻擊它的人，而被智慧聖印審判的敵人則會偶爾恢復法力值。對當前帶有你某個聖印審判效果的敵人進行自動攻擊，會刷新該效果的持續時間。" },
                        { t = "p", v = "你對目標施加的審判效果不必與你當前激活的聖印一致：你可以先激活|s20349|，然後對首領使用|s20271|，這樣你的隊伍攻擊它時就能獲得治療，緊接着切換到|s20357|，這樣你自己的自動攻擊就能恢復法力值，並刷新首領身上的光明聖印效果。為了輸出傷害，你可以用|s20308|對敵人施放審判，使其承受額外的神聖傷害，然後切換到|s20293|，讓你的攻擊造成神聖傷害，而這一傷害會因十字軍聖印的效果而提高。" },
                    } },
                    { key = "races", flow = {
                        { t = "p", v = "《魔獸世界：無限》引入了前所未有的新種族/職業組合，包括讓部落也能擁有聖騎士。" },
                        { t = "races", v = { { race = "人類", side = "alliance", mark = "tick" }, { race = "矮人", side = "alliance", mark = "tick" } } },
                        { t = "p", v = "無限服新增的職業-種族組合" },
                        { t = "h4", v = "聯盟" },
                        { t = "p", v = "聯盟聖騎士的選擇有 和 。這兩者中 更有優勢，因為其種族特長組合|s20597|提供了比 更多的暴擊|s1259719|並且還擁有|s20598|。 則擁有|s20594|，這是一個強大的效果，但聖騎士已經有其他方式解除自身所有這類效果。" },
                        { t = "h4", v = "部落" },
                        { t = "p", v = "如果你打算玩部落，其實沒有太多選擇，因為 是在無限服中唯一擁有該職業的種族。" },
                    } },
                    { key = "prof", flow = {
                        { t = "p", v = "神聖聖騎士最好的專業是 和 。 提供各種實用和生活質量物品，而 則能讓你製作一些自己的裝備。這兩個專業都需要通過 獲取材料，所以如果你不打算購買所有礦石，就需要只選其中一個，並將採礦作為第二專業。" },
                    } },
                },
            },
            prot = {
                updated = "2026/09/18",
                sections = {
                    { key = "changes", flow = {
                        { t = "p", v = "防護聖騎士一直以來都擁有一套相當完善的坦克工具包，但總有一個問題阻礙了他們在團隊副本中的廣泛出場，那就是缺少一個類似|s355|的技能。如今這個問題已經通過引入|s20423|得到了解決，它允許你的|s20271|。此外，過往的痛點，比如戰鬥中缺乏法力回覆，也通過天賦樹得到了解決，玩防護聖騎士的手感應該比以往任何時候都好。" },
                        { t = "p", v = "在《魔獸世界：無限》中，我們獲得了前所未有的新技能，填補了防護聖騎士此前工具包中的空白。防護聖騎士也成為了唯一沒有專門百分比減傷爆發技能的坦克，轉而依賴|s1311015|，一個持續8秒的超大吸收盾。" },
                        { t = "tb", v = { { "|s20423|", "使聖騎士充滿神聖之怒，持續30秒，使近戰攻擊額外造成（法術強度的10%）神聖傷害。裝備盾牌時，每次攻擊還會獲得一個吸收盾，數值等於所造成神聖傷害的50%。同一時間聖騎士只能激活一個聖印。釋放該聖印的能量會對敵人造成（法術強度的45%）神聖傷害，並嘲諷目標攻擊你，持續4秒。" }, { "|s1311015|", "激活後，該技能為你提供一個吸收盾，數值等於你最大生命值的100%，持續8秒。施加1分鐘的自律。自律激活期間無法施放。" }, { "|s17143|", "一次瞬發打擊，造成42.0%武器傷害外加額外神聖傷害。" }, { "|s1224697|", "使你的總耐力提高4%，並使你的聖盾術、神聖保護和保護者壁壘的冷卻時間縮短60秒。" }, { "|s1314104|", "當狂怒聖印的護盾被完全吸收時，恢復60點法力值，攻擊者每比你高一級則提高15%，最多提高45%。" }, { "|s1310994|", "結束你審判技能的剩餘冷卻時間，並使你下一次審判的法力消耗降低100%。" }, { "|s1311034|", "使你的神聖震擊產生的威脅值提高30%。當正義之怒激活時，神聖震擊還會使你承受的傷害降低15%，持續6秒。" } } },
                        { t = "p", v = "雖然防護聖騎士的改動很多，但有一個重要的技能需要特別說明，那就是|s20923|的改動。這個標誌性技能是防護聖騎士成為強力AOE坦克的原因所在，雖然現在依然如此，但效果會大打折扣。該技能現在對效果範圍內的所有目標只造成極低的傷害，但有一個加成效果，會提高對進入區域的前4個目標的傷害。這將使該技能更接近防護戰士和野性德魯伊那種目標數限制在3-4的AOE。" },
                        { t = "tb", v = { { "|s20923|", "在聖騎士腳下的大地施加神聖之力，進入該區域的敵人每8秒受到280點神聖傷害。", "在聖騎士腳下的大地施加神聖之力，進入該區域的敵人每8秒受到64點神聖傷害。進入該區域的前4個敵人額外受到[(法術強度的9.5%) * 8]點傷害，持續8秒。" }, { "|s20928|", "使你的盾牌格擋幾率提高30%，持續10秒，且在激活期間每成功格擋一次攻擊便造成130點神聖傷害。神聖之盾造成的傷害額外產生20%的威脅值。每次格擋消耗一次充能。最多4次充能。", "使你的盾牌格擋幾率提高20%，持續10秒，且在激活期間每成功格擋一次攻擊便造成221點神聖傷害。神聖之盾造成的傷害額外產生20%的威脅值。" }, { "|s20127|", "你在受到一次暴擊攻擊後，使你的盾牌格擋幾率提高30%。持續10秒或5次格擋。", "近戰傷害性攻擊命中你時，有10%的幾率使你的盾牌格擋幾率提高30%。持續10秒或5次格擋。" }, { "|s20096|", "防禦技能提高10點。", "防禦技能提高20點。" }, { "|s20189|", "使用近戰武器時的命中率提高1%。", "使你的命中幾率提高1%。" }, { "|s20468|", "使你的正義之怒法術產生的威脅值提高50%。", "正義之怒激活期間，你受到的所有傷害降低6%。" }, { "|s20148|", "使你的盾牌吸收的傷害提高30%", "使你的盾牌吸收的傷害提高30%，並使你的格擋有100%的幾率恢復6%的最大法力值。該效果每3秒只能觸發一次。" }, { "|s20196|", "使你使用單手近戰武器造成的傷害提高6%。", "使你使用單手近戰武器造成的傷害提高10%。" }, { "|s20177|", "使你在受到暴擊之後有100%的幾率獲得一次額外攻擊。", "使你在格擋一次近戰攻擊之後有40%的幾率獲得一次額外攻擊，並在受到非週期性暴擊之後有100%的幾率獲得一次額外攻擊。" } } },
                    } },
                    { key = "beginner", flow = {
                        { t = "p", v = "防護聖騎士的操作難度並不算特別高，但你既要摸索坦克的基本門道，又要學會應對法力值方面的難題，過程中難免會遇到一些坎。" },
                        { t = "p", v = "防護聖騎士是較為容易上手的坦克之一，雖然有幾處交互可能不太直觀，但當你初入這個世界時，重點應放在學習不同聖印與|s20271|，並充分利用你的整套技能，尤其是諸如|s17143|,|s26573|，以及|s20925|(等你達到40級後)。在整個攻略過程中會包含大量優化建議，你可以在對遊戲核心機制有一定了解後再去關注這些內容。" },
                    } },
                    { key = "systems", flow = {
                        { t = "p", v = "聖騎士作為坦克的獨特之處在於使用法力值，而其他坦克則使用怒氣作為資源。因此，聖騎士處於一種利弊參半的境地。" },
                        { t = "tb", v = { { "優勢：聖騎士在戰鬥開始時絕不會缺資源，可以毫無資源壓力地打出整套技能。", "", "劣勢：在持久戰中，聖騎士必須謹慎管理法力，以免資源枯竭，而且往往需要等待法力恢復後才能迎戰新的敵人。" } } },
                        { t = "ul", v = { { text = "|s20357|- 每次攻擊獲得法力值。\n審判效果：攻擊該目標的每名玩家每次攻擊時獲得少量法力值。" }, { text = "|s20349|- 每次攻擊獲得生命值。\n審判效果：攻擊該目標的每名玩家每次攻擊時獲得少量生命值。" }, { text = "|s20308|- 提高攻擊速度和攻擊強度，但降低每次攻擊的傷害。\n審判效果：受到的聖光傷害提高，影響隊伍中的每名成員。" }, { text = "|s20164|- 偶爾使目標昏迷。\n審判效果：阻止目標在低血量時逃跑。" }, { text = "|s20453|- 每次揮砍造成傷害並獲得吸收效果。\n審判效果：造成傷害並嘲諷目標。" }, { text = "|s20293|- 每次揮砍造成傷害\n審判效果：對目標造成傷害。" } } },
                        { t = "p", v = "此外，騎士還要管理聖印和聖印造成的減益，這對隊伍/團隊至關重要，並需要考慮如何管理聖印以平衡仇恨、法力值、治療以及目標身上的減益。" },
                        { t = "p", v = "雖然某些聖印比其他更實用，但根據實際戰況靈活切換聖印至關重要，同時還要與隊友協調，確保目標身上有合適的審判效果。" },
                    } },
                    { key = "races", flow = {
                        { t = "p", v = "騎士在種族選擇上不必糾結太多，因為只有2個聯盟種族和1個部落種族可選。各種族能力的真正價值還有待觀察，但無論選哪個都不會錯。" },
                        { t = "races", v = { { race = "人類", side = "alliance", mark = "tick" }, { race = "矮人", side = "alliance", mark = "tick" } } },
                        { t = "p", v = "無限服新增的職業-種族組合" },
                        { t = "h4", v = "聯盟" },
                        { t = "p", v = "人類騎士" },
                        { t = "p", v = "人類之所以能在早期《魔獸世界》中成為事實上的首選種族，是因為他們極為強力的武器專精加成。在《魔獸世界：無限》中，種族天賦已被重新設計，|s20597|現在改為對所有攻擊和法術提供 2% 暴擊幾率。由於|s26573|等技能現在可以暴擊，這項加成變得尤為強力。" },
                        { t = "p", v = "|s1259718|也已加入遊戲，它能讓你每 3 分鐘解除一次昏迷效果。這在 PVP 中用途不言而喻，在 PVE 中同樣有很高的實用價值。" },
                        { t = "p", v = "假設你能輕鬆獲取劍類武器作為最佳裝備，那麼人類很可能是你的最優選擇。" },
                        { t = "p", v = "矮人聖騎士" },
                        { t = "p", v = "矮人同樣能通過種族天賦獲得大量實用效果，例如通過|s1259719|獲得 1% 的暴擊加成，儘管其強度只有人類對應天賦的一半。" },
                        { t = "p", v = "為了彌補這部分強度差距，矮人擁有|s20594|，這一天賦在特定情況下非常強力，因為持續流血效果無法被驅散。" },
                        { t = "p", v = "此外，|s1259721|能對所有野獸造成 5% 的額外傷害。世界上存在數量驚人的野獸類敵人，這使得該天賦在練級階段表現出色。在團隊副本環境中通常野獸較少，但由於《魔獸世界：無限》將推出新的副本，我們無法對該天賦的完整價值做出評估。" },
                        { t = "p", v = "總的來說，矮人是很好的備選，特定場景下甚至優於人類。" },
                        { t = "h4", v = "部落" },
                        { t = "p", v = "亡靈聖騎士" },
                        { t = "p", v = "亡靈是聖騎士的新可選種族，而且作為部落目前唯一的選擇，如果你想扛起那面猩紅色的戰旗，基本沒什麼其他可選的。" },
                        { t = "p", v = "幸運的是，亡靈種族獲得了一些新的種族技能，對聖騎士來說價值頗高。當攻擊敵人時，|s1260189|有 5% 的概率吸取目標生命值，最多為你最大生命值上限的 5%。目前該效果僅有 1 秒的內部冷卻時間，因此觸發相當頻繁。不過具體哪些技能可以觸發此效果，以及低傷害法術究竟能吸到多少，仍不明確。" },
                        { t = "p", v = "此外，亡靈還擁有|s7744|在 PvP 和 PvE 中都有很強的應用場景。|s20577|現在還會恢復法力值，對我們聖騎士來說是個好訊息。" },
                    } },
                    { key = "prof", flow = {
                        { t = "p", v = "目前尚不清楚哪些專業對防護聖騎士收益最大。在整個經典懷舊服的每個資料片中，始終是最強的備選。聖騎士一直以來都面臨一個問題：在距離較遠時難以建立仇恨，而工程學制造的炸彈可以很好地解決這個問題。" },
                        { t = "p", v = "除工程學以外的所有專業都能通過屬性獲得專屬加成。這些屬性收益能否超過工程學的優勢，仍有待觀察。" },
                        { t = "p", v = "在資料片初期選 和 或 是一個比較穩妥的選擇。" },
                    } },
                },
            },
            ret = {
                updated = "2026/09/21",
                sections = {
                    { key = "changes", flow = {
                        { t = "p", v = "此前，懲戒聖騎士曾是相當弱勢的職業，缺乏職業特色，能為團隊和隊伍成員提供的支援也較為有限。《魔獸世界：無限》將通過引入煥然一新的天賦樹、新法術與新技能，並對現有技能進行重製，使其更加強大且更具分量，力求解決這些問題。" },
                        { t = "p", v = "在所有新技能和新天賦中，最有趣且影響最大的當屬神聖打擊——我們的新瞬發攻擊，造成神聖傷害——以及光明之旋，這是懲戒天賦樹當前的終極天賦，使你可以通過在兩個聖印之間來回切換，讓同一次自動攻擊同時享受兩個聖印的加成。" },
                        { t = "tb", v = { { "|s10333|", "一項基於武器傷害和法術強度造成神聖傷害的新瞬發攻擊，類似於十字軍打擊。這是全新的主力輸出技能。" }, { "|s1310735|", "懲戒天賦樹的新終極天賦；允許你在兩個聖印之間“交替切換”，以同時享受兩者對近戰攻擊的加成效果。當你切換聖印時，之前的聖印會變為一個“迴響”，在你的下一次攻擊中觸發該聖印的效果。" }, { "|s20423|", "一項全新的防禦向聖印，根據法術強度為近戰攻擊附加額外的神聖傷害。裝備盾牌時，你還將獲得一個吸收護盾，數值等於此聖印造成的神聖傷害的50%。審判此聖印會使目標被嘲諷4秒，並造成額外神聖傷害。" } } },
                        { t = "p", v = "除了新的天賦和技能之外，我們還對大量現有技能進行了調整，任何在經典魔獸中體驗過懲戒的玩家都會對其中部分改動感到熟悉。在這些改動中，比較重要的內容包括抗性光環作用於團隊成員，祝福持續1小時，並且審判使用時不再消耗你的聖印。" },
                        { t = "tb", v = { { "|s25290|", "現在持續1小時。" }, { "|s25291|", "現在持續1小時。" }, { "|s20217|", "現在持續1小時；現在通過訓練習得，而非從防護天賦樹中獲得。" }, { "|s10310|", "使用時不再打斷法力回覆。" }, { "|s20924|", "現在對站在其中的前4個敵人造成額外傷害；現在通過訓練習得，而非從神聖天賦樹中獲得。" }, { "|s10318|", "現在使其擊中的亡靈和惡魔敵人昏迷2秒。" }, { "|s25780|", "現在使威脅值生成提高90%，而非60%。" }, { "|s19896|", "現在為所有團隊成員提供抗性，而非僅小隊成員。" }, { "|s19898|", "現在為所有團隊成員提供抗性，而非僅小隊成員。" }, { "|s19900|", "現在為所有團隊成員提供抗性，而非僅小隊成員。" }, { "|s20271|", "使用時不再消耗你的聖印。" } } },
                    } },
                    { key = "viability", flow = {
                        { t = "p", v = "《魔獸世界：無限》的目標之一是讓每個職業和專精都有一席之地。雖然目前關於懲戒在滿級時的表現我們掌握的資訊不多，但可以做出一些合理推測。與經典懷舊服的其他許多分支類似，乍看之下，懲戒在PvE內容中將擁有中等的傷害輸出能力，同時為團隊和隊伍成員提供強大的支援與功能增益，並且可以輕鬆以副專精或在緊急情況下擔任坦克或治療。" },
                        { t = "p", v = "在PvP內容中，懲戒很可能延續其爆發前置的輸出定位，擁有中等的機動性和強大的支援與功能增益，但缺乏主要的傷害爆發技能。" },
                    } },
                    { key = "sw", flow = {
                        { t = "p", v = "懲戒聖騎士的主要定位是一名輸出者，能在打出中等DPS的同時，用祝福、光環和功能法術支援團隊——我們的優劣勢也將圍繞這一主要定位展開。遺憾的是，我們的主要職責並不是登頂傷害統計，因為我們缺乏能實現這一點的強力傷害爆發技能。" },
                        { t = "good", v = { "中等的單體傷害- 一名稱職的輸出者。", "紮實的群體傷害- 適合同時應對多個敵人。", "強大的功能與支援能力- 祝福、光環和功能法術是我們的核心優勢。", "高機動性- 得益於清潔術和自由祝福。", "應急技能- 用聖療術或保護祝福力挽狂瀾，絕境翻盤。" } },
                        { t = "bad", v = { "無主要爆發技能- 目前缺少主要傷害爆發技能。", "法力值較少- 最大法力值非常有限，很容易耗盡。", "嚴重依賴裝備- 目前非常依賴通過裝備堆疊法術強度。", "治療與坦克能力較弱- 若想有效地擔任坦克或治療角色，需要更換天賦。" } },
                    } },
                    { key = "beginner", flow = {
                        { t = "p", v = "與其它職業相比，高階懲戒玩法會有中等複雜的輸出循環，但對新手來說仍然比較容易上手和適應，尤其是在低級階段。職業設計目前非常直白，學習門檻有限，即便是從未玩過的玩家也能輕鬆駕馭。總的來說，《魔獸世界：無限》中的懲戒玩法對新玩家相當友好，容易入門。" },
                        { t = "p", v = "聖騎士也是一個在輔助他人時最強的職業，能讓新手為隊友提供諸多強力增益，例如驅散或祝福，隊友們會對此非常受用。" },
                    } },
                    { key = "systems", flow = {
                        { t = "p", v = "《魔獸世界：無限》中懲戒聖騎士的核心職業體系是終極天賦：|s1310735|因此，我會用一小節來解釋它的運作方式。無需擔心，其實相當簡單。" },
                        { t = "p", v = "該|s1310735|機制是其他《魔獸世界》經典舊世版本中“聖印切換”的簡化版，能讓你在一次普通攻擊中享受多重聖印的效果。由於聖印是為近戰附加傷害的技能，這個終極天賦允許你切換到新的聖印時，仍然通過這個“迴響”機制保留上一個聖印的增益——你的下一次近戰攻擊將同時受益於新施放的聖印以及上一個聖印的“迴響”，相當於讓一次攻擊同時擁有兩個聖印的效果。" },
                        { t = "p", v = "根據目前的理解，這將成為高等級懲戒玩法背後的核心機制。與其他版本的“聖印切換”相比，它要簡單得多，但不再具有揮砍節奏或時機把控的要素，因此玩家對此看法不一。好在暴雪已在基礎介面中加入了揮砍計時器，以便更好地支援這種玩法。我們希望儘快開始測試該天賦，並在之後帶來更多訊息。" },
                    } },
                    { key = "races", flow = {
                        { t = "p", v = "下面是我們首次整理出的職業與種族搭配，以及對應的種族特長。" },
                        { t = "races", v = { { race = "人類", side = "alliance", mark = "tick" }, { race = "矮人", side = "alliance", mark = "tick" } } },
                        { t = "ul", v = { { text = "|s1259718|- 立即解除所有昏迷效果。" }, { text = "|s20600|- 大幅提升潛行偵測能力，持續20秒。" }, { text = "|s20597|- 使用劍類武器時，所有法術和攻擊的暴擊幾率提高2%。" }, { text = "|s20598|- 精神提高5%。" }, { text = "|s20594|- 移除並免疫所有流血、中毒和疾病效果，並使承受的傷害降低10%，持續8秒。" }, { text = "|s2481|- 在小地圖上感知附近的寶箱位置。" }, { text = "|s1259719|- 使用錘類武器時，所有法術和攻擊的暴擊幾率提高1%。" }, { text = "|s1259721|- 對野獸造成的傷害提高 5%。" }, { text = "|s1260189|- 有 5% 的幾率從敵人目標身上偷取生命值，偷取量最多為你最大生命值的 5%。" }, { text = "|s5227|- 在水下呼吸的時間延長至原來的 300%。" }, { text = "|s20577|- 通過吞噬倒下的敵人屍體來回復生命值。" }, { text = "|s7744|- 立刻解除自身受到的魅惑、恐懼或睡眠效果。" } } },
                        { t = "p", v = "無限服新增的職業-種族組合" },
                        { t = "h4", v = "聯盟" },
                        { t = "p", v = "對於聯盟來說，你有兩種選擇人類和矮人。個人建議堅持選擇人類由於其種族特長過於強大，例如解除昏迷效果以及額外的1%暴擊幾率。" },
                        { t = "p", v = "人類種族特長：" },
                        { t = "p", v = "矮人種族特長：" },
                        { t = "h4", v = "部落" },
                        { t = "p", v = "部落聖騎士的唯一選擇是亡靈。" },
                        { t = "p", v = "亡靈種族特長：" },
                    } },
                    { key = "prof", flow = {
                        { t = "p", v = "雖然我們仍在調查和收集資訊，但目前的共識似乎是採礦和鍛造是當前懲戒聖騎士的強力副業選擇。" },
                    } },
                },
            },
        },
        HUNTER = {
            bm = {
                updated = "2026/09/25",
                sections = {
                    { key = "changes", flow = {
                        { t = "p", v = "在《魔獸世界：無限》中，暴雪對獸王獵人的改動並不大。幾個天賦被合併為一個，我們還獲得了一個新版本的技能，也就是之前正式服中大家熟知的“群鴉盛宴”：|s1293241|這些鷹隼算是某種“僞”第二寵物，因為其他幾個天賦也能提高它們的傷害。不過，獸王獵人最重要的改動還是體現在寵物方面。寵物現在會受益於獵人的部分屬性，雖然相比其他版本的《魔獸世界》稍弱一些。部分寵物種類還獲得了新技能，讓更多寵物變得可用。" },
                        { t = "tb", v = { { "|s1293241|- 天賦", "命令一隻鷹隼俯衝轟炸你指定的敵人，造成物理傷害並持續攻擊18秒。同時只能有2只鷹隼處於激活狀態。召喚鷹隼與奧術射擊共享冷卻時間。冷卻時間6秒。" }, { "|s1223755|- 天賦", "你的寵物處於激活狀態時，你和你寵物造成的所有傷害提高2%。" } } },
                        { t = "p", v = "一個非常重要的改動似乎是移除了0.5秒的施法時間，涉及|s75|，此外還有其他改進。這會讓獵人成為更強大的風箏高手。" },
                        { t = "tb", v = { { "|s75|", "自動射擊目標，直到取消。現在沒有隱藏的0.5秒施法時間，並且可以在施放其他技能期間持續進行。這讓你只要武器就緒並且停止移動，就能立刻射擊。" }, { "|s20904|- 技能", "一次瞄準射擊，使遠程傷害提高166。瞄準射擊與多重射擊共享冷卻時間。重要的新內容是它與|s2643|共享冷卻時間。它現在也是基礎技能，而非天賦。" }, { "|s2643|- 技能", "發射多枚導彈，命中3個目標。多重射擊與瞄準射擊共享冷卻時間。似乎不再有額外等級來提升傷害。" }, { "|s19583|- 天賦", "使你的寵物生命值和護甲提高15%。" }, { "|s19549|- 天賦", "使你的猴子守護提供的閃避加成提高6%。此外，你的寵物獲得你的猴子守護技能50%的效果。" }, { "|s19577|- 天賦", "命令你的寵物在下次成功攻擊時擊昏目標3秒，該次攻擊的暴擊幾率提高100%。產生大量威脅值。" }, { "|s19590|- 天賦", "使你的寵物集中值回覆速度提高20%，並允許施法時保留50%的法力值回覆。" } } },
                    } },
                    { key = "viability", flow = {
                        { t = "p", v = "《魔獸世界：無限》的目標之一是讓每個職業和專精都具備可玩性。對於獸王獵人而言，他們在無限服中是否達到了這一標準值得商榷。獸王獵人無法為團隊提供任何增益，最多隻能通過高嶺陸行鳥的新技能提供一些護甲削減|s1265904|. 唯一的亮點在於擁有（極高的）基礎傷害,只要能衝上傷害榜首就足以讓你在團隊中佔有一席之地。" },
                        { t = "p", v = "在 PvP 中,獸王獵人有一定的潛力,前提是我們的寵物不會一受到傷害就倒下。移除|s75|的施法時間在 PvP 場景中非常強力,但很難成功施放出一次|s20904|。部分寵物係獲得了一些強力的 PvP 技能。雙倍|s1293241|搭配一隻|s19574|強化後的寵物,可以構成非常致命的爆發連擊。" },
                    } },
                    { key = "sw", flow = {
                        { t = "good", v = { "高爆發- 獸王獵人在其|s19574|爆發窗口期間應當具備較高的爆發傷害。", "強大的風箏能力- 無論是在 PvE 還是 PvP 場景中,只要目標沒有遠程控制或突進技能,你都可以輕鬆風箏小怪或玩家。", "擁有功能的寵物隨着新寵物技能的加入，讓所有寵物都有機會大放異彩，獵人能夠根據當時的需求靈活調整。|s1265904|在PvE中很強，|s1264933|在PvP中能壓制治療，|s1265058|在盜賊偷襲你時能反制他們，等等。" } },
                        { t = "bad", v = { "無團隊輔助能力- 獵人目前無法為小隊或團隊提供任何有用的增益。這使得你在競爭環境中只能依靠高基礎傷害來獲得位置。", "盲區- 任何進入你8碼範圍內的怪物或玩家都無法被你的遠程傷害技能命中。由於獸王獵人仍然偏好遠程射擊，這會對你造成不利影響。" } },
                    } },
                    { key = "beginner", flow = {
                        { t = "p", v = "獵人上手簡單，適合任何玩家，而在《魔獸世界：無限》的三個專精中，獸王大概率是最容易上手的。但這並不意味着獸王完全不需要思考。正確地保持兩層|s1293241|持續刷新且不過早重新施加，是成為優秀獸王獵人的關鍵。獵人的一大樂趣在於其極高的操作上限，尤其是在單人內容和PvP中。如果你足夠熟練地掌握穿插近戰（即進出近戰範圍使用近戰技能的操作），你會發現總傷害有所提升。對陷阱和釘刺的良好控制會讓你在PvP中很強。最後，良好的寵物和環境控制讓你在單人內容中非常強大，使你能夠單刷其他職業無法單刷的內容。這對獵人的三個專精都適用。" },
                    } },
                    { key = "systems", flow = {
                        { t = "h4", v = "子彈與箭矢" },
                        { t = "p", v = "目前，彈藥系統似乎沒有明顯改動。你仍然需要箭袋來裝箭矢，或用彈藥袋來裝子彈。這意味着我們仍然比大多數其他職業少一個背包。" },
                        { t = "h4", v = "寵物" },
                        { t = "ul", v = { { text = "耐力：玩家每 1 點耐力為寵物提供 2 點生命值" }, { text = "護甲：寵物獲得玩家護甲值的 30%" }, { text = "攻擊強度：寵物獲得玩家最高攻擊強度來源的 10%" }, { text = "暴擊：寵物獲得玩家暴擊率的 100%" } } },
                        { t = "p", v = "寵物在《魔獸世界：無限》中獲得了一些顯著改動。所有的寵物類型現在都擁有至少一個獨特技能，其中一些在 PvE 場景中非常實用，另一些則更適合 PvP。獵人寵物的屬性還會按比例受到玩家屬性的影響，具體如下：" },
                        { t = "p", v = "所有這些資訊同樣在角色介面的寵物面板中展示並說明。寵物現在也擁有閃避屬性，並且不再能被其他職業的增益效果加成。" },
                    } },
                    { key = "races", flow = {
                        { t = "p", v = "各個種族在種族特長方面進行了大量改動，旨在讓所有種族同樣強力。目前來看，一些種族整體表現更優，而另一些則可能在某一特定玩法中大放異彩。在《魔獸世界：無限》中，人類現在也可以選擇獵人，同時新增了天裔這一可選種族。" },
                        { t = "races", v = { { race = "矮人", side = "alliance", mark = "tick" }, { race = "暗夜精靈", side = "alliance", mark = "tick" }, { race = "獸人", side = "horde", mark = "tick" }, { race = "牛頭人", side = "horde", mark = "tick" }, { race = "巨魔", side = "horde", mark = "tick" } } },
                        { t = "p", v = "無限服新增的職業-種族組合" },
                        { t = "p", v = "天裔只要隊伍裏有元素法系存在，天裔憑藉其種族被動技能|s1259707|幾乎穩居榜首。雖然暴雪試圖讓所有種族的種族能力都具有競爭力，但他們並沒有取消針對特定怪物類型的種族特長。另一個能顯著提升你 DPS 的種族被動是|s1259710|。在經典服中急速屬性十分稀有，因此這可能比你想像的更強。" },
                        { t = "h4", v = "聯盟" },
                        { t = "p", v = "暗夜精靈 暗夜精靈可能是獵人最強的聯盟種族，因為他們擁有全新的主動技能|s1259799|。該技能冷卻時間為3分鐘，但若與|s3045|和/或|s19574|搭配使用，你的傷害會在短時間內大幅提升。戰鬥時間越短，該技能的效果越顯著。注意，由於全新的寵物繼承規則，在此期間你的寵物還會額外獲得10%的暴擊幾率。" },
                        { t = "p", v = "矮人" },
                        { t = "p", v = "目前，矮人在PvE場合唯一的收益是|s1259721|，而且僅在你與野獸作戰時纔有效。|s20594|則是相當不錯的PvP種族特長，所以如果你想成為盜賊的剋星，不妨選擇矮人。" },
                        { t = "p", v = "人類" },
                        { t = "p", v = "目前，人類對遠程獵人幾乎沒有助益，因為|s20597|只對你的近戰攻擊和技能生效。不過寵物依然能獲得暴擊提升，因為它們會複製獵人的近戰和法術暴擊幾率。這也確實意味着人類能為使用劍的生存獵人提供不錯的增益。而在PvP中，人類則擁有一個強力技能：|s1259718|其作用基本上和大家熟悉的PvP飾品相同。" },
                        { t = "h4", v = "部落" },
                        { t = "p", v = "獸人" },
                        { t = "p", v = "獸人大概無論PvE還是PvP都遠是部落最好的種族。|s20572|提供強力的攻擊強度加成，同時也能小幅強化你的寵物。它現在是瞬發，並且冷卻時間只有2分鐘，而大多數其他種族特長的冷卻時間都是3分鐘。生存獵人可以額外獲得|s20574|裝備斧時的加成。在PvP中，你還有|s20573|來降低昏迷的效果，以及|s1299026|來反制任何施法者（尤其是術士）。" },
                        { t = "p", v = "巨魔" },
                        { t = "p", v = "和矮人一樣，巨魔通過種族被動獲得對野獸的額外傷害|s20557|。不過巨魔確實有一個非常強力的PvE主動技能，那就是|s20554|。該技能不再根據已損失生命值提升效果，因此比經典舊世時更弱，但仍然提供相當不錯的攻擊速度加成。" },
                        { t = "p", v = "牛頭人" },
                        { t = "p", v = "牛頭人獵人可以獲得額外的 1% 命中率加成，來源是|s20550|。在後期命中難以達標的情況下，這一加成非常強力；而額外的生命值在開荒期團本中也相當有用。|s1259918|會與|s5118|產生競爭，但使用它可以在不切獵豹的情況下風箏某些怪物，從而在使用雄鷹守護時打出更高傷害。|s20549|依然是非常強力的群體昏迷技能，無論在 PvP 還是 PvE 中都很好用。" },
                    } },
                    { key = "prof", flow = {
                        { t = "p", v = "制皮 隨着制皮的改動與新增內容，這項專業看起來已成為獵人的必備專業。許多配方被改動或新增，製作的裝備為拾取綁定。這些裝備在對應等級往往非常強力。如果當前已知的專業內容在滿級時保持不變，那麼學習制皮幾乎是必選。" },
                        { t = "p", v = "工程學 工程學讓獵人獲取到非常強力的裝備，尤其是槍械與頭部附魔道具，還有強力的消耗品，例如各種手雷和地雷。目前還不清楚該專業在後續階段的完整內容，但如果加入類似工程附件的額外內容，也不會令人意外。" },
                    } },
                },
            },
            mm = {
                updated = "2026/09/25",
                sections = {
                    { key = "changes", flow = {
                        { t = "p", v = "在《魔獸世界：無限》中，暴雪正在強化射擊獵人的設定，使其成為孤身作戰的弓箭手（或槍手），使用高傷害的遠程技能進行射擊，就像我們當前在正式服看到的那樣。隨着|s415370|加入天賦樹，你很可能在副本或團隊副本中不會使用寵物。" },
                        { t = "tb", v = { { "|s1310687|- 天賦", "一次穩定的狙擊，使遠程傷害提高160點。施法時間為4(!)秒，冷卻時間為15秒。它是射擊天賦樹的終極天賦。" }, { "|s415370|- 天賦", "當你沒有激活的寵物時，所有攻擊造成的傷害提高20%。" }, { "|s1223987|- 天賦", "用毒蛇釘刺擊中目標可使你在接下來的15秒內施法時獲得50%的法力值回覆，消耗急速殺戮則可獲得100%的法力值回覆。開發者為幾乎所有天賦和職業提供了法力值回覆天賦，因此可以減少戰鬥中的空檔期。" }, { "|s1223984|- 天賦", "攻擊強度提高智力的100%。這個天賦可能會帶來一些有趣的裝備屬性搭配選擇。" }, { "|s1310661|- 天賦", "毒蛇釘刺的傷害提高20%，蝰蛇釘刺的冷卻時間縮短6秒，蠍毒釘刺的持續時間延長45秒。" } } },
                        { t = "p", v = "一個非常重要的改動似乎是移除了|s75|的0.5秒施法時間，以及其他改進。這會讓獵人的風箏能力更加強大。" },
                        { t = "tb", v = { { "|s75|", "自動射擊目標直至取消。現在沒有隱藏的0.5秒施法時間，並且可以在施放其他技能期間繼續射擊。這讓你在武器就緒且停止移動時可以立即射擊。" }, { "|s20904|- 技能", "一個瞄準射擊，使遠程傷害提高166。瞄準射擊與多重射擊共享冷卻時間。重要的新改動是與|s2643|共享冷卻時間。它現在也是基礎技能，而非天賦。" }, { "|s2643|- 技能", "發射數枚導彈，命中3個目標。多重射擊與瞄準射擊共享冷卻時間。似乎不再有額外等級，傷害提高。" }, { "|s20906|- 天賦", "使45碼內小隊成員的遠程攻擊強度提高50。持續30分鐘。不再顯著提高近戰攻擊強度，並且被大幅削弱。" }, { "|s24293|- 天賦", "在追蹤野獸、惡魔、龍類、元素生物、巨人、人型生物或亡靈時，你對所追蹤生物類型造成的所有傷害提高5%。" } } },
                    } },
                    { key = "viability", flow = {
                        { t = "p", v = "《魔獸世界：無限》的目標之一是讓每個職業和專精都可行。對於射擊獵人來說，他們在無限服中是否達到了這個標準值得懷疑。移除了近戰攻擊強度後，|s20906|顯著降低了在物理傷害隊伍中擁有獵人的實用性。再加上（很可能）缺少能提供任何有用減益效果的寵物，射擊獵人將無法為任何隊伍或團隊提供顯著的增益。其彌補因素將是（極其）高的基礎傷害。" },
                        { t = "p", v = "在PvP中，射擊獵人是否能夠表現出色也仍然值得懷疑。移除了|s75|的施法時間在PvP場景中非常強大，但很難施放任何|s20904|或|s1310687|。不過，如果無人關注且被放任不管，射擊獵人將極其致命。" },
                    } },
                    { key = "sw", flow = {
                        { t = "good", v = { "高爆發- 射擊獵人在長施法時間技能下能打出高爆發。特別是配合|s1310687|。", "強大的風箏能力- 無論是在PvE還是PvP場景中，只要目標沒有遠程控制或突進技能，你就可以輕鬆地風箏怪物或玩家。" } },
                        { t = "bad", v = { "沒有團隊增益- 缺少|s20906|上的近戰攻擊強度加成，以及沒有寵物，會讓你不受歡迎，除非你能提供足夠高的傷害。", "近戰盲區- 任何進入你8碼範圍內的怪物或玩家都無法被你的遠程傷害技能命中。作為射擊獵人，這一點尤其致命。" } },
                    } },
                    { key = "beginner", flow = {
                        { t = "p", v = "獵人是任何玩家都能輕鬆上手的職業，但在《魔獸世界：無限》中，射擊很可能是三個專精中最難操作的。這並不意味着射擊是一個非常難的專精，至少在團隊內容中不是。獵人的樂趣在於上限很高，尤其是在單人和PvP中。如果你足夠熟練地掌握走位（在近戰範圍內來回移動以使用近戰技能），你會發現自己的總傷害會提高。良好的陷阱和釘刺控制能力會讓你在PvP中更加強大。最後，良好的寵物和環境控制能力讓你在單人內容中非常強力，並允許你完成其他職業無法完成的單刷內容。三個獵人專精都適用這一點。" },
                    } },
                    { key = "systems", flow = {
                        { t = "h4", v = "彈藥" },
                        { t = "p", v = "目前，彈藥系統似乎沒有重大改動。你仍然會使用箭袋裝箭矢或彈藥袋裝子彈。這意味着我們仍然比其他大多數職業少一個背包格。" },
                        { t = "h4", v = "寵物" },
                        { t = "ul", v = { { text = "耐力：每1點玩家耐力為寵物提供2點生命值" }, { text = "護甲：寵物獲得玩家護甲的30%" }, { text = "攻擊強度：寵物獲得玩家最高攻擊強度來源的10%" }, { text = "暴擊：寵物獲得玩家暴擊幾率的100%" } } },
                        { t = "p", v = "寵物在《魔獸世界：無限》中經歷了一些顯著改動。現在所有寵物種類都至少擁有一個獨特技能，有些在PvE場合非常實用，有些則在PvP中表現出色。獵人寵物現在也會隨我們的屬性成長，具體如下：" },
                        { t = "p", v = "所有這些資訊也會在角色介面的寵物面板中顯示和說明。寵物現在還將擁有規避。它們不再能受到其他職業增益的加成。" },
                    } },
                    { key = "races", flow = {
                        { t = "p", v = "各族的種族特長都經歷了大量改動，力求讓它們同樣優秀。目前來看，有些整體上更強，而另一些可能在特定的玩法中更為出色。在《魔獸世界：無限》中，人類現在可以成為獵人，同時還有新加入的天裔。" },
                        { t = "races", v = { { race = "矮人", side = "alliance", mark = "tick" }, { race = "暗夜精靈", side = "alliance", mark = "tick" }, { race = "獸人", side = "horde", mark = "tick" }, { race = "牛頭人", side = "horde", mark = "tick" }, { race = "巨魔", side = "horde", mark = "tick" } } },
                        { t = "p", v = "無限服新增的職業-種族組合" },
                        { t = "p", v = "天裔只要有元素存在，天裔必定憑藉其|s1259707|種族被動佔據榜首。雖然暴雪曾試圖讓所有種族都擁有具競爭力的種族特長，但他們並未擺脫針對特定怪物類型的那些。另一個能顯著提升你DPS的種族被動是|s1259710|。急速在經典舊世中尤為難得，所以這可能比你想像的更強。" },
                        { t = "h4", v = "聯盟" },
                        { t = "p", v = "暗夜精靈 暗夜精靈或許是聯盟中最強的獵人種族，這得益於他們的新主動技能|s1259799|。該技能冷卻時間為3分鐘，但與|s3045|和/或|s19574|配合使用時，能在短時間內大幅提升你的傷害。戰鬥越短，該技能的影響就越顯著。需要注意的是，由於新的寵物繼承機制，你的寵物在此期間也會獲得10%的額外暴擊率。" },
                        { t = "p", v = "矮人" },
                        { t = "p", v = "目前，矮人在PvE場景下唯一的優勢在於|s1259721|，且僅在對抗野獸時有效果。|s20594|是一個不錯的PvP種族技能，所以如果你想成為盜賊的剋星，可以考慮選擇矮人。" },
                        { t = "p", v = "人類" },
                        { t = "p", v = "人類當前對遠程獵人幾乎沒有增益，因為|s20597|只作用於你的近戰攻擊和技能。不過寵物仍會獲得暴擊加成，因為它們繼承獵人的近戰和法術暴擊率。這也意味着人類能為使用劍的生存獵人提供不錯的增益。而在PvP中，人類則擁有一個強力技能|s1259718|，其效果與大家熟悉的PvP飾品基本相同。" },
                        { t = "h4", v = "部落" },
                        { t = "p", v = "獸人" },
                        { t = "p", v = "獸人可能是無論PVP（還是PvE）中最好的部落種族。|s20572|提供強力的攻擊強度加成，這反過來也會略微增強你的寵物。它現在是瞬發技能，冷卻時間只有2分鐘，而大多數其他種族特長的冷卻時間是3分鐘。生存獵人會獲得額外的加成，|s20574|，當裝備斧類武器時。並且在PvP中，你擁有|s20573|來降低昏迷效果，以及|s1299026|來對抗任何施法者（特別是術士）。" },
                        { t = "p", v = "巨魔" },
                        { t = "p", v = "就像矮人一樣，巨魔通過其種族被動技能對野獸造成額外傷害，|s20557|。不過，巨魔在PvE中確實擁有一個非常強力的主動技能，形式為|s20554|。該技能不再根據缺失的生命值縮放，因此在經典版本中效果較弱，但仍能提供可觀的攻擊速度加成。" },
                        { t = "p", v = "牛頭人" },
                        { t = "p", v = "牛頭人獵人可以通過以下種族特長獲得額外的 1% 命中|s20550|。如果後期內容中命中屬性較難獲取，這會顯得非常強力；而額外的生命值在開荒團隊副本時也相當實用。|s1259918|確實會與以下技能產生競爭|s5118|，但它能讓你在某些怪物戰中保持風箏走位而不必切換獵豹守護，從而通過雄鷹守護打出更高的傷害。|s20549|仍然是一個極強的群體昏迷技能，無論在 PvP 還是 PvE 中都表現強勁。" },
                    } },
                    { key = "prof", flow = {
                        { t = "p", v = "制皮 隨着制皮專業的改動與新增，該專業已成為獵人的必備選擇。許多配方經過調整或新增，使所製造的裝備變為拾取綁定。這些裝備通常在你可裝備的等級下非常強力。如果該專業目前已知的內容一路持續到滿級都保持不變，那麼學習制皮幾乎是顯而易見的選擇。" },
                        { t = "p", v = "工程學 工程學為獵人提供了非常強力的裝備，包括槍械和頭部附魔物品，以及各種手雷和地雷等強力消耗品。目前尚不清楚該專業在更高階段會如何發展，但如果加入類似工程學附件的內容也毫不令人意外。" },
                        { t = "p", v = "專業總覽指南" },
                    } },
                },
            },
            surv = {
                updated = "2026/09/27",
                sections = {
                    { key = "changes", flow = {
                        { t = "p", v = "在《魔獸世界：無限》中，生存專精的身份被重新定位——從以干擾為主，轉型為結合近戰技能與陷阱的近戰專精。幾個天賦被合併為一個，天賦樹後半段也加入了一大批以近戰為導向的天賦。另一項可能影響生存獵人的重要改動來自寵物系統。寵物現在會按獵人部分屬性的一定比例獲得強化（比《魔獸世界》其他版本略弱）。部分寵物種類還獲得了新技能，使更多寵物變得可用。" },
                        { t = "tb", v = { { "|s1317257|- 天賦", "一個簡單的近戰\\\"踢擊\\\"技能，造成等同於你近戰傷害100%的傷害，並使你的移動速度提高3秒。冷卻時間8秒。無法打斷目標。" }, { "|s1310627|- 天賦", "使你的近戰暴擊傷害提高30%，副手武器傷害提高50%。相比其他雙持職業，這個副手傷害加成看起來非常強力。" }, { "|s1310532|- 天賦", "你對帶有獵人印記的目標攻擊時，有10%的幾率觸發5秒的貓鼬撕咬。這是讓|s14271|可以在輸出循環裏使用而無需躲避的關鍵。" }, { "|s440529|- 天賦", "該天賦使你的陷阱和近戰技能的法力值消耗降低60%，且暴擊有一定幾率使你的法力值回覆提高30秒。這基本上是維持法力值的主要天賦。" }, { "|s1310496|- 天賦", "使你的陷阱和威懾技能的冷卻時間縮短40%。簡單有效，因為陷阱的冷卻時間在《無限》中被提升至30秒的基礎水平。" }, { "|s1310533|- 天賦", "生存的新終極天賦。使你的|s14271|（對目標）造成持續較長時間的流血傷害。" } } },
                        { t = "tb", v = { { "|s14271|- 技能", "對敵人造成近戰武器傷害加固定數值。僅在躲閃後纔可使用，除非獲得|s1310532|。傷害不再是一個固定數值，而是使用武器傷害。" }, { "|s24293|- 天賦", "怪物追蹤和人形生物追蹤合併為一個天賦。滿級時對被追蹤生物類型造成的所有傷害提高5%。現在對獵人的所有追蹤技能都生效。" }, { "|s19184|- 天賦", "現在陷阱觸發時總會定身所有受影響的目標，滿級時定身時間最長為5秒。" }, { "|s19376|- 天賦", "經典版中的陷阱命中率和假死命中率天賦合併為一個。" }, { "|s19306|- 天賦", "在招架對手攻擊後激活的一擊。現在會隨着武器傷害而變化，而不是造成固定數值的傷害。" } } },
                    } },
                    { key = "viability", flow = {
                        { t = "p", v = "《魔獸世界：無限》的一個目標是讓每個職業和每個天賦都能登場。生存獵或許已經達到了這一點，只要它的傷害能衝上榜首，因為生存獵不會給團隊提供任何增益，最多隻能通過高鳥的新能力提供一些破甲效果|s1265904|或是已經被其他職業提供的其他增益/減益效果。" },
                        { t = "p", v = "在PvP中，生存獵或許有一定的潛力，只要我們的寵物不會一碰就倒。有幾個寵物家族獲得了一些強力的PvP技能。|s1317257|是一個對技能組合很好的補充，尤其是它的移速加成效果，而且一些以陷阱為核心的天命也變得更強了。" },
                    } },
                    { key = "sw", flow = {
                        { t = "good", v = { "強大的持續傷害- 生存獵應該擁有強大的持續傷害，因為他們幾乎可以一直按鍵。在經典版魔獸中沒有任何空窗期是非常強力的。", "強大的風箏能力無論在 PvE 還是 PvP 場景中，只要目標沒有遠程控制或突進技能，你都可以輕鬆地風箏怪物或玩家。", "寵物的功能性隨着新寵物技能的加入，所有寵物都有發揮的空間，獵人可以根據當前需要靈活應對。|s1265904|在 PvE 中表現出色，|s1264933|在 PvP 中壓制治療，|s1265058|在盜賊先手時反制他們，等等。" } },
                        { t = "bad", v = { "沒有團隊增益獵人當前無法為隊伍或團隊提供任何有用的增益。在競爭激烈的環境中，你只能憑藉高額的基礎傷害才能被選中。", "裝備競爭你需要與戰士、盜賊甚至聖騎士爭奪武器。" } },
                    } },
                    { key = "beginner", flow = {
                        { t = "p", v = "獵人對任何玩家來說都容易上手，在《魔獸世界：無限》中生存專精也不例外，不過由於天賦要求，該專精要等到大約 32 級左右纔會真正發光發熱。你幾乎總會按鍵可按，只是偶爾需要選擇先按哪一個。作為生存獵人，你可以選擇帶寵物或不帶寵物。獵人的樂趣在於其上限很高，尤其是在單人和 PvP 內容中。如果你能夠熟練運用遠程和近戰技能的全部組合，你會變得非常難以對付。良好的陷阱和釘刺控制會讓你在 PvP 中變強。最後，優秀的寵物和場地控制能力會讓你在單人內容中非常強力，能夠單刷其他職業無法單刷的內容。三個獵人專精都是如此。" },
                    } },
                    { key = "systems", flow = {
                        { t = "h4", v = "彈藥與箭矢" },
                        { t = "p", v = "目前彈藥系統似乎沒有重大改動，你仍然需要使用箭袋來裝箭矢，或者使用彈藥袋來裝子彈。這意味着我們的背包數量依然比其他職業少一個。" },
                        { t = "h4", v = "寵物" },
                        { t = "ul", v = { { text = "耐力：玩家每 1 點耐力為寵物提供 2 點生命值" }, { text = "護甲：寵物獲得玩家護甲值的 30%" }, { text = "攻擊強度：寵物獲得玩家最高攻擊強度來源的 10%" }, { text = "暴擊：寵物獲得玩家暴擊率的 100%" } } },
                        { t = "p", v = "寵物在《魔獸世界：無限》中獲得了值得注意的改動。如今所有寵物種類都至少擁有一個獨特技能，其中一些在 PvE 場景中非常實用，另一些則在 PvP 中大放異彩。獵人寵物現在也會隨我們的屬性成長，具體如下：" },
                        { t = "p", v = "所有這些資訊也可以在角色介面的寵物面板中查看和了解。寵物現在還會擁有閃避屬性，並且無法再享受其他職業的增益效果。" },
                    } },
                    { key = "races", flow = {
                        { t = "p", v = "為了讓所有種族特長都同樣出色，各種族的種族特長都經歷了不少改動。就目前而言，有些種族總體上似乎更強，而另一些則可能在某種特定玩法中大放異彩。在《魔獸世界：無限》中，人類現在可以成為獵人，還可以選擇新增的天裔種族。" },
                        { t = "races", v = { { race = "矮人", side = "alliance", mark = "tick" }, { race = "暗夜精靈", side = "alliance", mark = "tick" }, { race = "獸人", side = "horde", mark = "tick" }, { race = "牛頭人", side = "horde", mark = "tick" }, { race = "巨魔", side = "horde", mark = "tick" } } },
                        { t = "p", v = "無限服新增的職業-種族組合" },
                        { t = "p", v = "|s1259707|天裔如果戰鬥中存在任何元素生物，天裔的種族天賦必定能讓他們佔據榜首位置。雖然暴雪試圖讓所有種族的種族天賦具備競爭力，但他們仍未放棄針對特定怪物類型的專屬加成。另一個能為你的 DPS 提供可觀加成的，是|s1259710|. 急速在經典服中非常稀有，因此這個效果可能比你想像中更強。" },
                        { t = "h4", v = "聯盟" },
                        { t = "p", v = "暗夜精靈 暗夜精靈可能是獵人最強的聯盟種族，原因在於他們新增的主動技能|s1259799|。該技能冷卻時間為3分鐘，但當它與|s3045|和/或|s19574|搭配使用時，你的傷害會臨時獲得巨大提升。戰鬥時間越短，這一技能的影響就越大。需要注意的是，在此期間你的寵物也會因新的寵物屬性繼承規則獲得額外的10%暴擊率。" },
                        { t = "p", v = "人類" },
                        { t = "p", v = "人類為使用劍的生存獵人提供了不錯的增益，同時也會提升你的寵物暴擊率。在PvP中，人類獲得了強力技能|s1259718|，其效果基本與大家熟悉的PvP飾品相同。" },
                        { t = "p", v = "矮人" },
                        { t = "p", v = "目前，矮人在PvE場景中唯一的好處就是|s1259721|，而且這僅在面對野獸類型敵人時纔會生效。|s20594|是一個不錯的PvP種族技能,所以如果你想成為盜賊的剋星,可以選擇矮人。" },
                        { t = "h4", v = "部落" },
                        { t = "p", v = "獸人" },
                        { t = "p", v = "獸人可能是部落在PvE和PvP中最強的種族。|s20572|能提供強力的攻擊強度加成,這也會略微增強你的寵物。它現在是瞬發技能,冷卻時間也僅為2分鐘,而大多數其他種族技能的冷卻時間為3分鐘。生存獵人在使用|s20574|時還能獲得斧專精加成。而在PvP中,你擁有|s20573|以降低昏迷效果|s1299026|來應對那些施法者(尤其是術士)。" },
                        { t = "p", v = "巨魔" },
                        { t = "p", v = "和矮人一樣,巨魔通過種族被動技能|s20557|對野獸造成額外傷害。不過巨魔在PvE中擁有一個非常強力的主動技能,也就是|s20554|。該技能不再根據已損失生命值提升威力,比經典舊世版本更弱,但仍然能提供不錯的攻擊速度加成。" },
                        { t = "p", v = "牛頭人" },
                        { t = "p", v = "牛頭人獵人可以通過種族特長獲得額外的 1% 命中|s20550|。在後期命中難以堆疊時，這個加成非常強力，額外的生命值在開荒團本中也很有用。|s1259918|確實會與之競爭|s5118|，但它能讓你在不開獵豹的情況下風箏部分怪物，從而在使用雄鷹守護時提高傷害。|s20549|仍然是非常強力的群體昏迷技能，無論是 PvP 還是 PvE 都很好用。" },
                    } },
                    { key = "prof", flow = {
                        { t = "p", v = "制皮 隨着制皮的改動與新增內容，這項專業看起來已經成為獵人的標配。許多配方被改動或新增，製作的裝備變為拾取綁定。這些部件通常在你可裝備的等級就已經非常強力。如果目前已知的關於該專業的內容在滿級之前都保持不變的話，學習制皮是理所當然的選擇。" },
                        { t = "p", v = "工程學 工程學讓獵人能用到非常強力的裝備，例如槍械和頭部附魔，以及強力的消耗品，例如手雷和地雷。雖然目前還不清楚該專業在更高階段會帶來什麼，但如果後續加入類似附魔寶石之類的內容，也不會令人意外。" },
                    } },
                },
            },
        },
        ROGUE = {
            assa = {
                updated = "2026/10/05",
                sections = {
                    { key = "changes", flow = {
                        { t = "p", v = "從標準經典舊世到《魔獸世界：無限》，盜賊迎來了大量改動，有的影響巨大，有的只是小幅微調。其中影響最大的兩處是：毒藥現在隨攻擊強度成長，以及能量改用了巫妖王之怒及之後版本的平滑回復機制，取代了舊版按跳回復的模式。此外值得一提的還有，毒藥現在可以與風怒圖騰以及磨刀石疊加生效。" },
                        { t = "p", v = "奇襲盜賊獲得了一些亮眼的新技能，比如|s1329|和|s1310703|。我們從毒藥的改動中獲益最多，而我們的天賦也在方方面面利用並強化毒藥。" },
                        { t = "tb", v = { { "|s1329|", "毀傷已加入天賦樹，為我們提供了一個專屬於本專精的出色連擊點生成技能。該技能對已中毒目標的傷害提高20%，進一步深化了專精的主題設定，也促使你至少在一把武器上塗毒。待測試版等級上限提升到30級、我們能真正開始測試後，將補充更多資訊。" }, { "|s1310703|", "我們的新終結技，可將毒藥傷害提高30%，並將毒藥的施加幾率提高10%。不得不承認，它算不上最令人興奮的技能，因為它實際上相當於第二個|s5171|需要去維持。它確實缺少了遊戲後續版本中的傷害成分。" } } },
                        { t = "p", v = "奇襲天賦樹對現有技能做出了一批改動，主要圍繞提升我們的毒藥輸出，同時強化主要連擊點生成技能的傷害。" },
                        { t = "tb", v = { { "|s14138|", "現在還會提高你的毒藥暴擊幾率。" }, { "|s14144|", "該天賦的收益現在也延伸到了毀傷。" }, { "|s14158|", "現在每點天賦提供2%的傷害加成，由1%上調。不再對野獸和龍人生效。" }, { "|s14128|", "收益現在也適用於毀傷。傷害加成下調至每點天賦4%，原先為6%。" }, { "|s14168|", "該天賦已被完全重做。現在每點天賦使破甲的能量消耗降低5點，並且在5連擊點時使用會返還2個連擊點。" }, { "|s14174|", "現在只提高你對被眩暈目標造成的傷害。" }, { "|s14983|", "該天賦在天賦樹中上移，現在為2點天賦，最大能量提升不變。" }, { "|s14113|", "現在使你的毒藥有50%幾率不消耗層數。" }, { "|s14177|", "現在還會提高毀傷的暴擊幾率。" } } },
                    } },
                    { key = "viability", flow = {
                        { t = "p", v = "奇襲的實際可行性仍有待測試。初步看法是，每當面對高護甲值的對手時，奇襲將開始嶄露頭角，因為它能無視敵人護甲，並且比另外兩個專精擁有更高的成長性。" },
                    } },
                    { key = "sw", flow = {
                        { t = "p", v = "奇襲盜賊最大的優勢和劣勢本質上是一樣的。我們無法提供有益的團隊增益/減益，只能靠純粹的傷害輸出來爭取團隊位置。因此，你可以預期盜賊在傷害統計上表現非常出色，以彌補功能性的不足。毒藥應占我們傷害的一大部分，而任何免疫自然傷害的怪物都會大幅削弱我們的貢獻。" },
                        { t = "good", v = { "毒藥傷害- 我們的毒藥天然無視敵人護甲。", "破甲的應用- 在需要時，奇襲追求強化破甲的損失最小。", "生存能力我們擁有一些不錯的自保技能，例如|s5277|、|s1856|以及|s1966|。" } },
                        { t = "bad", v = { "無團隊增益在與戰士|s7386|持平的情況下|s8647|，我們在傷害和打斷之外幾乎沒有任何實質性的團隊貢獻。", "自然免疫若戰鬥首領具有毒性免疫，此專精立刻會受到限制。", "能量恢復在獲得套裝或任何可能提升能量回復的改動之前，所有盜賊專精的循環都會顯得有些\"遲緩\"。" } },
                    } },
                    { key = "beginner", flow = {
                        { t = "p", v = "奇襲歷來是盜賊各專精中最簡單的一個。我們用|s1310707|積攢連擊點數，並主要將它們用於維持|s5171|和|s1310703|。奇襲沒有任何重要的爆發大招，這個專精的絕大部分內容就是維持好你的 2 個增益。" },
                    } },
                    { key = "races", flow = {
                        { t = "p", v = "盜賊可選種族新增了天裔,目前看來這個種族特長相當平庸。" },
                        { t = "races", v = { { race = "人類", side = "alliance", mark = "tick" }, { race = "矮人", side = "alliance", mark = "tick" }, { race = "暗夜精靈", side = "alliance", mark = "tick" }, { race = "侏儒", side = "alliance", mark = "tick" }, { race = "獸人", side = "horde", mark = "tick" }, { race = "亡靈", side = "horde", mark = "tick" }, { race = "巨魔", side = "horde", mark = "tick" } } },
                        { t = "ul", v = { { text = "|s1259416|- 在空中向下滑翔10秒,同時控制移動方向。" }, { text = "|s1259686|- 嘗試從元素交匯處汲取力量並獲得祝福,移動速度與坐騎移動速度提高10%。如果附近沒有元素交匯處,持續30秒;如果找到,則持續15分鐘。" }, { text = "|s1259705|- 嘗試汲取附近地脈的能量,生命值與法力值回覆速度提高100%。如果附近沒有地脈,持續15秒;如果找到,則持續15分鐘。" }, { text = "|s1259710|- 法術、近戰和遠程急速提高1%。" }, { text = "|s1259707|- 對元素生物造成的傷害提高5%。" }, { text = "|s20589|- 立刻解除所有限制移動的效果,並獲得3秒的免疫。" }, { text = "|s1259812|- 你接下來的3個傷害技能的能量消耗降低10%,且造成的傷害提高10%。" }, { text = "|s1259803|- 最大能量值提高5。" }, { text = "|s20593|- 侏儒的聰明才智使你使用的工程學裝置的故障或反噬幾率降低20%。" }, { text = "|s1259799|- 使你的所有法術和攻擊的暴擊幾率提高10%，持續15秒。" }, { text = "|s20580|- 激活後遁入陰影，降低敵人偵測到你存在的幾率。持續直到主動取消或移動為止。在戰鬥中使用此技能會降低敵人攻擊你的慾望，但冷卻時間延長至2分鐘。其功能更接近漸隱術，而非讓我們獲得潛行狀態或使用需要潛行的技能。" }, { text = "|s20582|- 閃避幾率提高1%，移動速度提高2%。暗夜精靈盜賊和德魯伊在潛行狀態下更難被偵測到，效果相當於高出1級。" }, { text = "|s20585|- 死亡後變身為小精靈，移動速度提高75%。" }, { text = "|s1259718|- 立即移除所有昏迷效果。" }, { text = "|s20600|- 大幅提高潛行偵測能力，持續20秒。" }, { text = "|s20597|- 裝備劍或雙手劍時，你的所有法術和攻擊的暴擊幾率提高2%。" }, { text = "|s20598|- 精神提高5%。" }, { text = "|s20594|- 立即移除所有流血、中毒和疾病效果並使你免疫這些效果，同時使你受到的所有物理傷害降低10%，持續8秒。" }, { text = "|s2481|- 使矮人能夠感知附近的寶藏，並將其顯示在小地圖上。持續直到取消。" }, { text = "|s1259719|- 裝備錘或雙手錘時，你的所有法術和攻擊的暴擊幾率提高1%。" }, { text = "|s1259721|- 對野獸造成的傷害提高5%。" }, { text = "|s20572|- 攻擊強度與法術強度提高 10%，持續 15 秒。" }, { text = "|s1299026|- 立即移除並免疫所有詛咒與惡意效果，並使受到的所有魔法傷害降低 15%，持續 8 秒。" }, { text = "|s20574|- 當你裝備斧或雙手斧時，所有法術與技能的暴擊幾率提高 1%。" }, { text = "|s20573|- 你身上的昏迷效果持續時間縮短 20%。" }, { text = "|s7744|- 立即移除所有魅惑、恐懼和睡眠效果。" }, { text = "|s20577|- 激活後，每 2 秒恢復 7% 的總生命值和 7% 的總法力值，持續 10 秒。僅對 5 碼範圍內的人型或亡靈屍體生效。食屍過程中任何移動、動作或受到傷害都會取消該效果。" }, { text = "|s5227|- 水下呼吸時間延長 300%。" }, { text = "|s1260189|- 你的法術和攻擊有 5% 的幾率從目標身上吸取生命值，最多為你最大生命值的 5%。" }, { text = "|s20554|- 施法與攻擊速度提高 10%，持續 10 秒。" }, { text = "|s1260270|- 在 6 秒內恢復 50% 的最大生命值。任何移動、動作或受到傷害都會取消該效果。" }, { text = "|s20557|- 對野獸造成的傷害提高5%。" }, { text = "|s20555|- 生命值回覆速度提高 10%。此外，10% 的總生命值回覆效果可以在戰鬥中進行。" } } },
                        { t = "p", v = "無限服新增的職業-種族組合" },
                        { t = "h4", v = "聯盟" },
                        { t = "p", v = "在《魔獸世界：無限》中，聯盟盜賊通常會優先選擇暗夜精靈或侏儒，因為他們擁有遠超其他種族的高強度主動技能。暗夜精靈提供|s1259799|，能帶來可觀的暴擊率加成，並可與其他主動技能和觸發效果疊加，打出高額的爆發傷害。侏儒則提供|s1259812|，使接下來3個技能的能量消耗降低20%，此外還有|s1259803|，可以避免其他種族在使用該技能時因能量恢復機制順暢而產生的能量溢出浪費。" },
                        { t = "p", v = "天裔——根據所選陣營不同，天裔擁有對應的聯盟或部落專屬主動種族技能。" },
                        { t = "p", v = "侏儒" },
                        { t = "p", v = "暗夜精靈" },
                        { t = "p", v = "人類" },
                        { t = "p", v = "矮人" },
                        { t = "h4", v = "部落" },
                        { t = "p", v = "在無限服中，部落盜賊會更傾向於選擇獸人或亡靈。獸人的標誌性種族技能|s20572|，一個強力的主動爆發技能，其邏輯與夜精靈相同。可以疊加在其他技能和觸發效果之上，用來實現強力的按需爆發。此外種族特長還能帶來|s20574|在裝備斧類武器時獲得額外的1%暴擊率。亡靈則提供|s1260189|，觸發幾率為5%，內置1秒觸發條件冷卻時間。考慮到盜賊的攻擊速度非常快，這一觸發型種族特長的利用率應當高於任何其他職業。" },
                        { t = "p", v = "獸人" },
                        { t = "p", v = "亡靈" },
                        { t = "p", v = "巨魔" },
                    } },
                    { key = "prof", flow = {
                        { t = "p", v = "乍看之下，工程學依舊是曾經的強力專業之一，多種小裝置和插件帶來了極強的靈活性和功能性。剝皮和制皮同樣值得關注——新增了大量配方，讓你至少在遊戲初期更容易製作一些裝備。隨着資料不斷收集，本節內容將持續擴充。" },
                    } },
                },
            },
            combat = {
                updated = "2026/10/05",
                sections = {
                    { key = "changes", flow = {
                        { t = "p", v = "盜賊從原版香草年代過渡到《魔獸世界：無限》時經歷了大量改動，有些變動幅度很大，有些只是小幅調整。其中影響最深的兩項是：毒藥現在可以享受攻擊強度的加成，以及能量回復採用了《巫妖王之怒》之後的平滑回復機制，不再是原本的節拍式回覆。此外值得一提的是，毒藥現在可以與風怒圖騰以及磨刀石疊加。" },
                        { t = "p", v = "盜賊進入無限版本後的改動主要圍繞天賦樹的重新平衡。因此，基礎技能大體保持不變，玩過香草時代盜賊的玩家會覺得非常熟悉。戰鬥賊在 PvE 中一直是香草版本完成度最高的專精，因此整體改動也最少。" },
                        { t = "tb", v = { { "|s1224716|", "該天賦取代了舊版強化背刺。它現在還會使你的|s1329|獲得暴擊率加成，併為你的|s53|附加 45% 的幾率，使該技能在目標身上額外獲得一個連擊點數。" }, { "|s1310711|", "使你的|s2098|能量消耗降低 10 點。" } } },
                        { t = "p", v = "雖然新增的天賦與技能數量不多，但現有技能的改動相當深遠。最值得關注的是，所有武器專精天賦已合併為一個天賦：|s13960|。另外，未命中的技能現在會部分返還能量，與遊戲中後期版本的機制類似。" },
                        { t = "tb", v = { { "|s1225295|", "該天賦現在是 3 點天賦，提供 3% 命中加成，而舊版為 5 點天賦提供 5% 命中。" }, { "|s13742|", "該天賦現在會縮短|s2983|和|s5277|降低30%/60%。相當於將這些技能的冷卻時間縮短為原先的一半。" }, { "|s13960|", "這個天賦將我們之前所有的武器專精天賦整合為一個獨立天賦。它會讓斧和劍獲得5%的幾率觸發額外攻擊，匕首和拳套武器提升5%暴擊率，而錘類武器則無視目標15%的護甲。這意味着只要你保持武器技能不斷更新，就不必因為獲得了一把新類型武器而專門去洗天賦。對，我們現在也可以使用斧頭了！" }, { "|s23584|", "該天賦每點使副手傷害增加的比例從原先的10%下調至5%。這很可能是為了配合我們的毒藥現在按攻擊強度縮放而進行調整的主要天賦之一。" }, { "|s18427|", "該天賦現在還會提升我們使用|s53|造成的傷害。" }, { "|s30919|", "不再提升武器技能。改為每點天賦使你的攻擊被閃避或招架的幾率降低1%。" } } },
                    } },
                    { key = "viability", flow = {
                        { t = "p", v = "戰鬥賊在《魔獸世界：無限》中仍將是盜賊最實用的天賦之一，原因在於他們不依賴毒藥或持續傷害效果，而部分戰鬥可能會有對這些效果的免疫。純粹的自動攻擊傷害，再加上通過|s13877|實現的順劈能力，將讓戰鬥賊在當前版本中保持競爭力。類似於巫妖王之怒版本加入雙天賦時的情況，大多數盜賊很可能都會準備一套戰鬥天賦，以及另外一套用於純單體輸出的天賦。" },
                    } },
                    { key = "sw", flow = {
                        { t = "p", v = "盜賊最大的優勢與劣勢本質上是相同的：我們不提供有益的團隊增益/減益，而是依靠原始傷害輸出來爭取團隊位置。因此，你可以預見盜賊的傷害資料會非常亮眼，以彌補我們相對缺乏的功能性。" },
                        { t = "good", v = { "以自動攻擊為核心的天賦- 不依賴毒藥和持續傷害意味着你的技能組合不會受到任何限制。", "順劈能力強- 唯一擁有可觀群體傷害能力的盜賊天賦。", "不錯的爆發能力- 通過|s13877|，|s13750|，以及激活的種族特長，戰鬥盜賊可以提前傾瀉傷害，或將其保留用於特定的DPS爆發階段。", "生存能力- 我們擁有一些不錯的生存技能，例如|s5277|，|s1856|，以及|s1966|造成的傷害。" } },
                        { t = "bad", v = { "沒有團隊增益- 隨着戰士|s7386|與|s8647|持平，我們在傷害和腳踢之外缺乏實質性的團隊貢獻。", "能量回復- 在等到可能提升我們能量回復的套裝或後續改動之前，盜賊的所有專精玩起來都會顯得有些“慢”。" } },
                    } },
                    { key = "beginner", flow = {
                        { t = "p", v = "戰鬥盜賊是一個相當直白的專精。我們用|s1752|積攢連擊點數，主要將它們花在維持|s5171|上，多餘的連擊點數則傾瀉到|s2098|。|s13877|和|s13750|是我們擁有的兩個大爆發技能。拿不準的時候，最好一好就用、儘量同開。" },
                    } },
                    { key = "races", flow = {
                        { t = "p", v = "盜賊的種族列表中唯一新增的是全新的天裔，就目前來看它給人的感覺相當乏善可陳。" },
                        { t = "races", v = { { race = "人類", side = "alliance", mark = "tick" }, { race = "矮人", side = "alliance", mark = "tick" }, { race = "暗夜精靈", side = "alliance", mark = "tick" }, { race = "侏儒", side = "alliance", mark = "tick" }, { race = "獸人", side = "horde", mark = "tick" }, { race = "亡靈", side = "horde", mark = "tick" }, { race = "巨魔", side = "horde", mark = "tick" } } },
                        { t = "ul", v = { { text = "|s1259416|- 在空中向下滑翔10秒，期間可控制移動方向。" }, { text = "|s1259686|- 嘗試從元素交匯處汲取力量並獲得其祝福，使你的移動速度和騎乘速度提高10%。若附近沒有元素交匯處，效果持續30秒；若找到交匯處，則持續15分鐘。" }, { text = "|s1259705|- 嘗試汲取附近地脈的力量，使你的生命值和法力值回覆速度提高100%。若附近沒有地脈，效果持續15秒；若找到地脈，則持續15分鐘。" }, { text = "|s1259710|- 使你的施法、近戰和遠程急速提高1%。" }, { text = "|s1259707|- 對元素生物造成的傷害提高5%。" }, { text = "|s20589|- 立即掙脫所有移動限制效果，並在此後的3秒內免疫這些效果。" }, { text = "|s1259812|- 你接下來的3個傷害技能能量消耗降低10%，造成的傷害提高10%。" }, { text = "|s1259803|最大能量值提高5%。" }, { text = "|s20593|侏儒的巧思使你使用的工程學裝置的故障或反噬幾率降低20%。" }, { text = "|s1259799|使所有法術和攻擊的暴擊幾率提高10%，持續15秒。" }, { text = "|s20580|激活後融入陰影，降低敵人發現你的幾率。持續到取消或開始移動為止。在戰鬥中使用會勸退敵人攻擊你，但冷卻時間延長至2分鐘。該技能更類似於漸隱術，而非提供潛行或需要潛行的技能。" }, { text = "|s20582|閃避幾率提高1%，移動速度提高2%。侏儒潛行等級比夜精靈高1級。" }, { text = "|s20585|死亡後變形為幽魂，移動速度提高75%。" }, { text = "|s1259718|立即移除所有昏迷效果。" }, { text = "|s20600|大幅提高潛行偵測能力，持續20秒。" }, { text = "|s20597|裝備單手劍或雙手劍時，所有法術和攻擊的暴擊幾率提高2%。" }, { text = "|s20598|精神提高5%。" }, { text = "|s20594|立即移除所有流血、中毒、疾病、魔法、惡魔、激變效果，並在8秒內使受到的物理傷害降低10%。" }, { text = "|s2481|使矮人感知附近的寶藏，並顯示在小地圖上。持續到取消為止。" }, { text = "|s1259719|- 裝備釘錘或雙手錘時，所有法術和攻擊的暴擊幾率提高 1%。" }, { text = "|s1259721|- 對野獸的傷害提高 5%。" }, { text = "|s20572|- 攻擊強度和法術強度提高 30%，持續 15 秒。" }, { text = "|s1299026|- 立即移除並免疫所有詛咒與邪惡效果，並使受到的魔法傷害降低 15%，持續 8 秒。" }, { text = "|s20574|- 裝備斧或雙手斧時，所有法術和技能的暴擊幾率提高 1%。" }, { text = "|s20573|- 你身上的昏迷效果持續時間縮短 20%。" }, { text = "|s7744|- 立即移除所有魅惑、恐懼和睡眠效果。" }, { text = "|s20577|- 激活後，每 2 秒恢復 7% 的生命值上限和 7% 的法力值上限，持續 10 秒。僅對 5 碼內的人型生物或亡靈屍體生效。進食期間任何移動、動作或受到傷害都會打斷該效果。" }, { text = "|s5227|- 水下呼吸時間延長 300%。" }, { text = "|s1260189|- 你的法術和攻擊有 5% 的幾率吸取目標生命值，吸取量最多為你生命值上限的 5%。" }, { text = "|s20554|- 施法和攻擊速度提高 10%，持續 10 秒。" }, { text = "|s1260270|- 在 6 秒內恢復 50% 的生命值上限。任何移動、動作或受到傷害都會打斷該效果。" }, { text = "|s20557|- 對野獸的傷害提高 5%。" }, { text = "|s20555|生命值回覆速度提高10%。此外，10%的總生命值回覆會在戰鬥狀態下持續進行。" } } },
                        { t = "p", v = "無限服新增的職業-種族組合" },
                        { t = "h4", v = "聯盟" },
                        { t = "p", v = "《魔獸世界：無限》聯盟盜賊方面，由於夜精靈運營和侏儒運營擁有超越其他選項的強力活動技能，我們將更傾向於選擇這兩個種族。夜精靈提供|s1259799|，可為我們提供中等數量的暴擊率，配合其他觸發效果使用能打出可觀的爆發傷害。侏儒提供|s1259812|，使接下來使用的3個技能的能量值消耗降低20%，同時還有|s1259803|，減少了在平滑能量恢復機制下其他種族使用時容易出現的溢出浪費。" },
                        { t = "p", v = "天裔——根據所選陣營，天裔可加入部落或聯盟，並擁有特定的主動種族技能。" },
                        { t = "p", v = "侏儒" },
                        { t = "p", v = "夜精靈" },
                        { t = "p", v = "人類" },
                        { t = "p", v = "矮人" },
                        { t = "h4", v = "部落" },
                        { t = "p", v = "對於無限服中的部落盜賊，我們傾向於選擇獸人或亡靈。獸人提供其招牌的|s20572|，這是一個強力的爆發技能，其運作邏輯與夜精靈相同，能夠與其他技能和觸發效果疊加，帶來極強的瞬時爆發能力。此外，獸人還提供|s20574|，當持有一把斧頭時，免費獲得1%的暴擊幾率加成。亡靈提供|s1260189|，觸發幾率為5%，內置1秒冷卻時間。考慮到盜賊的攻擊速度，我們應當是所有職業中最能從這個種族特長中獲益的。" },
                        { t = "p", v = "獸人" },
                        { t = "p", v = "亡靈" },
                        { t = "p", v = "巨魔" },
                    } },
                    { key = "prof", flow = {
                        { t = "p", v = "乍看之下，工程學依然和以往一樣強大，其各種小工具和裝置帶來了極高的靈活性和實用性。制皮師也頗具亮點，新增了大量配方，使得至少在遊戲前期你能更輕鬆地製作一些裝備。隨着資料不斷積累，本節內容也會進一步完善。" },
                        { t = "p", v = "專業技能概述指南" },
                    } },
                },
            },
            sub = {
                updated = "2026/10/05",
                sections = {
                    { key = "changes", flow = {
                        { t = "p", v = "盜賊從原版經典舊世到《魔獸世界：無限》經歷了大量改動，其中有些影響深遠，有些只是微調。最重要的兩點是：我們的毒藥傷害現在會隨攻擊強度而提升，能量回復機制也採用了巫妖王及之後版本的流暢回覆方式，取代了原有的跳動式回覆。此外值得一提的是，毒藥現在可以與風怒圖騰以及磨刀石疊加。" },
                        { t = "p", v = "敏銳獲得了一些新天賦，比如|s1310728|和|s1310721|這些天賦旨在讓敏銳擺脫長期以來以PvP為核心的形象。目前很多資料仍不確定，很遺憾在等級上限30級的情況下，我們還無法很好地判斷敏銳在測試服中的輸出表現。" },
                        { t = "tb", v = { { "|s1310721|", "我們的新終極天賦會使|s1943|的週期性傷害跳數降低你在10秒內施放的下一個|s16511|或|s53|的能量消耗3點。該效果最多可疊加5次。在保持割裂完美覆蓋的情況下，這實際上為我們每秒提供1.5點能量。" }, { "|s1310728|", "使|s1752|、|s16511|和|s14278|對生命值低於35%的目標造成10%額外傷害。如果某個首領戰全程都處於斬殺階段，我們就可以從該天賦中獲得極為可觀的收益。" }, { "|s1224782|", "新天賦，2點，使悶棍和致盲的能量消耗每點降低25%。" }, { "|s462708|", "5點天賦，使背刺有3%/點概率使下一次伏擊不再需要潛行。" } } },
                        { t = "p", v = "敏銳天賦樹改動最大，這是有原因的。我們還需要更多測試，但鑑於這些大幅改動，敏銳天賦在單體傷害上應當能與其他兩個天賦分支抗衡。" },
                        { t = "tb", v = { { "|s14183|", "不再需要潛行，並且可添加連擊點數的窗口時間從10秒延長至20秒。" }, { "|s13975|", "該天賦的第一點現在額外使潛行冷卻時間縮短1秒。" }, { "|s14057|", "現為2點天賦，滿級時提高10%傷害。原為5點天賦，滿級時提高20%傷害。" }, { "|s14095|", "該天賦已被移除，因為悶棍不再有幾率使你脫離潛行。" }, { "|s13983|", "伺機而動已上移至天賦樹更高位置，現在使躲避或完全抵抗法術時有100%幾率添加一個連擊點數。該效果原滿級時上限為45%。" }, { "|s13976|", "現在使相關技能有100%幾率添加連擊點數（原為75%）。" }, { "|s14278|", "現在在裝備匕首時造成更高傷害。" }, { "|s14171|", "護甲削減效果已改為固定百分比，而非隨玩家等級提升的數值。" }, { "|s16511|", "現在在裝備匕首時造成更高傷害。對盟友造成的物理傷害加成已移除，改為使割裂傷害提高15%。" }, { "|s14082|", "\\\"割裂\\\"技能不再需要站位要求。" } } },
                    } },
                    { key = "viability", flow = {
                        { t = "p", v = "任何關於敏銳賊在 PvE 環境中的可行性評估都基本是猜測。我們有許多新內容可以提高我們的可行性，但在測試階段我們無法接觸到大部分技能組合。" },
                    } },
                    { key = "sw", flow = {
                        { t = "p", v = "敏銳盜賊最大的優勢與弱點本質上是一樣的。我們不能為團隊提供有益的增益/減益效果，只能依靠原始傷害輸出來爭取團隊位置。因此，你將看到盜賊在傷害統計中表現非常出色，以彌補缺乏更多輔助能力的不足。" },
                        { t = "good", v = { "持續傷害- 由於專注於強化\"割裂\"傷害以及\"千割\"效果，敏銳在戰鬥中的主動停頓期受到的懲罰最小。", "生存能力- 我們可以使用一些不錯的技能來幫助生存，例如|s5277|、|s1856|和|s1966|。" } },
                        { t = "bad", v = { "無團隊增益- 由於戰士|s7386|的表現與|s8647|持平，除了傷害和\"腳踢\"之外，我們缺乏任何真正的團隊貢獻。", "流血免疫- 如果一場首領戰中出現流血免疫機制，這個專精會立刻受到限制。", "能量回復- 在等到能提升能量回復速度的套裝或更多改動之前，盜賊的所有專精手感都會有點“慢”。" } },
                    } },
                    { key = "beginner", flow = {
                        { t = "p", v = "敏銳盜賊的核心玩法是用|s16511|積攢連擊點數，並主要將它們用於維持|s5171|以及給目標掛上|s1943|。這個專精比其他專精多一點細節：要穿插使用|s1856|來解鎖更多潛行相關技能，同時保持|s16511|在目標身上的覆蓋率以強化你的|s1943|。" },
                    } },
                    { key = "races", flow = {
                        { t = "p", v = "- 盜賊可選種族名單中唯一的新增內容是新種族天裔，就目前來看，這個種族的表現相當平淡。" },
                        { t = "races", v = { { race = "人類", side = "alliance", mark = "tick" }, { race = "矮人", side = "alliance", mark = "tick" }, { race = "暗夜精靈", side = "alliance", mark = "tick" }, { race = "侏儒", side = "alliance", mark = "tick" }, { race = "獸人", side = "horde", mark = "tick" }, { race = "亡靈", side = "horde", mark = "tick" }, { race = "巨魔", side = "horde", mark = "tick" } } },
                        { t = "ul", v = { { text = "|s1259416|- 在空中向下滑翔10秒，期間可控制移動方向。" }, { text = "|s1259686|- 嘗試從元素匯聚之處汲取力量並獲得其祝福，使你的移動速度和騎乘速度提高10%。若附近沒有元素匯聚之處，效果持續30秒；若找到一處，則持續15分鐘。" }, { text = "|s1259705|- 嘗試汲取附近魔網的力量，使你的生命值和法力值回覆速度提高100%。若附近沒有魔網，效果持續15秒；若找到一處，則持續15分鐘。" }, { text = "|s1259710|- 使你的施法、近戰和遠程急速提高1%。" }, { text = "|s1259707|- 對元素生物造成的傷害提高5%。" }, { text = "|s20589|- 立即擺脫所有移動限制效果的影響，並在3秒內免疫這些效果。" }, { text = "|s1259812|- 你接下來的3個傷害技能的能量消耗降低10%，並且造成的傷害提高10%。" }, { text = "|s1259803|- 能量上限提高5%。" }, { text = "|s20593|- 你天生的侏儒才智使工程學裝置在你使用時發生故障或反噬的幾率降低20%。" }, { text = "|s1259799|- 使你的法術和攻擊的暴擊幾率提高10%，持續15秒。" }, { text = "|s20580|- 激活後遁入陰影，降低敵人偵測到你的幾率。持續到主動取消或移動為止。戰鬥中使用該技能會打消敵人攻擊你的念頭，但冷卻時間延長至2分鐘。它更像一個漸隱術類技能，並不能讓我們進入潛行狀態或使用需要潛行的技能。" }, { text = "|s20582|- 閃避幾率提高1%，移動速度提高2%。暗夜精靈盜賊和德魯伊在潛行時更難被偵測到，效果相當於等級提高1級。" }, { text = "|s20585|- 死亡後變身為小精靈，移動速度提高75%。" }, { text = "|s1259718|- 立即解除所有眩暈效果。" }, { text = "|s20600|- 大幅提高你的偵測潛行能力，持續20秒。" }, { text = "|s20597|- 當你裝備劍或雙手劍時，你的法術和攻擊的暴擊幾率提高2%。" }, { text = "|s20598|- 精神提高5%。" }, { text = "|s20594|- 立即移除並使你免疫所有流血、中毒和疾病效果，同時使你受到的所有物理傷害降低10%，持續8秒。" }, { text = "|s2481|- 使矮人可以感知附近的寶藏，並顯示在小地圖上。持續直到取消。" }, { text = "|s1259719|- 當裝備錘或雙手錘時，所有法術和攻擊的暴擊幾率提高 1%。" }, { text = "|s1259721|- 對野獸造成的傷害提高 5%。" }, { text = "|s20572|- 攻擊強度和法術強度提高 10%，持續 15 秒。" }, { text = "|s1299026|- 立即移除並免疫所有詛咒與惡毒效果，並使所有魔法傷害降低 15%，持續 8 秒。" }, { text = "|s20574|- 當裝備斧或雙手斧時，所有法術和技能的暴擊幾率提高 1%。" }, { text = "|s20573|- 受到的昏迷效果持續時間縮短 20%。" }, { text = "|s7744|- 立即移除所有魅惑、恐懼和沉睡效果。" }, { text = "|s20577|- 激活後，每 2 秒恢復 7% 的總生命值和 7% 的總法力值，持續 10 秒。僅對 5 碼範圍內的人型生物或亡靈屍體生效。進食期間任何移動、動作或受到傷害都會打斷該效果。" }, { text = "|s5227|- 水下呼吸的持續時間延長 300%。" }, { text = "|s1260189|- 你的法術和攻擊有 5% 的幾率從目標身上吸取生命值，吸取量最多為你最大生命值的 5%。" }, { text = "|s20554|- 施法速度和攻擊速度提高 10%，持續 10 秒。" }, { text = "|s1260270|- 在6秒內恢復50%最大生命值。任何移動、動作或受到傷害都會打斷此效果。" }, { text = "|s20557|- 對野獸造成的傷害提高 5%。" }, { text = "|s20555|- 生命值恢復速度提高10%。此外，戰鬥中將持續恢復總生命值恢復量的10%。" } } },
                        { t = "p", v = "無限服新增的職業-種族組合" },
                        { t = "h4", v = "聯盟" },
                        { t = "p", v = "在《魔獸世界：無限》中，聯盟盜賊更推薦選擇夜精靈或侏儒，因為他們的主動技能非常強力，勝過其他種族。夜精靈提供|s1259799|，為我們帶來中等程度的暴擊率，可以與其他主動技能和觸發效果結合，打出高額爆發傷害。侏儒提供|s1259812|，使接下來3次技能的能量值消耗降低20%，同時|s1259803|能夠減少其他種族在使用|平滑能量恢復機制時產生的能量溢出。" },
                        { t = "p", v = "天裔 - 天裔可根據所選陣營加入部落或聯盟，其主動種族技能也會隨之不同。" },
                        { t = "p", v = "侏儒" },
                        { t = "p", v = "夜精靈" },
                        { t = "p", v = "人類" },
                        { t = "p", v = "矮人" },
                        { t = "h4", v = "部落" },
                        { t = "p", v = "對於無限服中的部落盜賊，我們更推薦選擇獸人或者亡靈。獸人的標誌性種族特長是|s20572|，這是一項強力的主動爆發技能，其邏輯與夜精靈相似，可以與其他技能疊加以獲得強大的瞬時爆發。他們還提供|s20574|，當手柄斧刃時獲得免費提升 1% 暴擊率。亡靈提供|s1260189|，觸發幾率 5%，內置 1 秒冷卻。考慮到盜賊的攻擊速度非常快，我們應當能比其他任何職業更頻繁地從這個種族特長中受益。" },
                        { t = "p", v = "獸人" },
                        { t = "p", v = "亡靈" },
                        { t = "p", v = "巨魔" },
                    } },
                    { key = "prof", flow = {
                        { t = "p", v = "乍看之下，工程學依然是熟悉的核心強力專業，各種小裝置和附魔零件提供了高度的靈活性和功能性。製革與裁縫也頗具價值，加入了大量新圖紙，讓你在遊戲初期就能更輕鬆地製造一些裝備。隨着我們收集到更多資料，這一節的內容將會進一步擴充。" },
                        { t = "p", v = "專業概覽指南" },
                    } },
                },
            },
        },
        PRIEST = {
            disc = {
                updated = "2026/09/22",
                sections = {
                    { key = "changes", flow = {
                        { t = "p", v = "在《魔獸世界：無限》中,戒律牧師獲得了徹底重做的天賦樹,開啓了多種全新的玩法路線。重點強化了戒律牧師在後續資料片中發展出的特色,比如通過吸收傷害來|s10901|以及|s431622|。根據具體數值平衡,該專精有望成為所有團本的常駐人選,也是副本治療者的優質選擇。得益於|s402174|的加入,它同樣適合作為升級專精使用!" },
                        { t = "p", v = "《魔獸世界：無限》為牧師職業引入了大量經典版本中沒有的全新有趣技能。" },
                        { t = "tb", v = { { "|s402174|", "|s402174|是戒律牧師的標誌性法術,首次加入於《巫妖王之怒》資料片。可對敵人造成傷害,也可對盟友進行治療。2秒引導可造成大量治療,並縮短目標身上虛弱靈魂的持續時間,從而實現將|s402174|以及|s10901|組合使用,大幅治療單一目標的玩法。同時也是野外練級的優秀傷害技能。" }, { "|s431622|", "作為吸收傷害體系中的另一關鍵拼圖,|s431622|會為受到我們暴擊治療的目標添加一層吸收護盾。" }, { "|s1277324|", "|s1277328|是亡靈牧師的新種族特長。可以在15秒內將生命值轉化為法力值。雖然冷卻時間很長,但可以在整場戰鬥期間提供可觀的額外法力值。對治療專精來說,損失的生命值基本可以忽略不計。" }, { "|s1277462|", "|s1277640|是侏儒(現在可以首次選擇牧師)的新種族技能。|s1277640|是一個指向性增益,當目標生命值降低時會為其附加護盾並持續治療。是非常強力的種族特長。" } } },
                        { t = "p", v = "《魔獸世界》中的戒律牧師：《無限》對現有技能也有一些改動，不過比其他一些專精要少一些。" },
                        { t = "tb", v = { { "|s14521|", "該|s14521|天賦現在允許你在施法時保留高達 50% 的精神法力回覆（原版《魔獸世界》中為 15%）。這意味着你有更多法力可以運用——前提是裝備上的精神屬性仍如預期般充足。" }, { "|s6346|", "|s6346|，一項關鍵的輔助能力，現在所有牧師都可以使用。" }, { "|s2944|", "|s19280|現在成為所有牧師的基礎法術，冷卻時間為一分鐘。" } } },
                    } },
                    { key = "viability", flow = {
                        { t = "p", v = "由於許多終局內容仍籠罩在神祕之中，很難判斷每個專精的可行性。不過，戒律牧師吸收傷害而非治療傷害的定位往往極具統治力，很有可能出現在許多團隊配置中。它可能遇到的唯一困難是，那些點數在天賦樹中非常靠前，一個大膽的神聖牧師也許能在不深入戒律天賦樹的情況下獲得類似的優勢。" },
                    } },
                    { key = "sw", flow = {
                        { t = "p", v = "以下是基於當前可用資訊，戒律牧師最明顯的優勢和劣勢：" },
                        { t = "good", v = { "遊戲中最強的吸收- 較低的|s10901|通常是造就一個出色甚至近乎壓制的治療專精的配方。|s431622|進一步增強了這一優勢，不過其數值調整相當低。", "單刷不死專精- 出色的生存能力與不俗的傷害相結合，使戒律成為戶外單練的絕佳專精。很少有精英怪能與你抗衡。", "核心輔助能力-|s27681|，|s21564|以及|s6346|都是核心輔助能力。|s10060|也相當不錯。" } },
                        { t = "bad", v = { "與神聖專精競爭激烈- 上述大多數優勢，神聖牧師點出|s10901|天賦後同樣具備。我們天賦樹更深層的天賦並沒有那麼不可或缺。", "群體治療較弱- 我們獲得的大部分激動人心的新內容只是進一步強化了單體治療。群體治療依然只是中規中矩。" } },
                    } },
                    { key = "beginner", flow = {
                        { t = "p", v = "總體而言，戒律牧師是新手玩家的絕佳選擇。它單練能力足夠，生存能力出色，而且進組治療毫無問題。它也非常簡單直接，上手快——用魔杖攻擊敵人是你早期升級體驗的常態。你還擁有一系列應急控制技能，例如|s8122|一旦陷入麻煩,儘管恐懼的怪物可能會吸引更多仇恨,所以務必跑得快!你的治療和輸出循環都具備足夠的複雜度,足以保持趣味性。" },
                    } },
                    { key = "systems", flow = {
                        { t = "p", v = "牧師在《魔獸世界：無限》中區別於其他職業的主要特徵就是種族專屬法術。你將在10級時獲得第一個,然後在20級時獲得第二個。每個種族提供兩個獨特的種族專屬法術,此外還有所有職業共享的常規種族特長。" },
                        { t = "tb", v = { { "10級", "|s1277370|", "|s13908|", "|s10797|", "|s1277455|", "|s2652|", "|s9035|" }, { "20級", "|s13896|", "|s1277331|", "|s2651|", "|s1277462|", "|s1277324|", "|s18137|" } } },
                    } },
                    { key = "races", flow = {
                        { t = "p", v = "《魔獸世界：無限》同時包含全新與熟悉的職業與種族組合。以下是所有可選方案的快速一覽:" },
                        { t = "races", v = { { race = "暗夜精靈", side = "alliance", mark = "tick" }, { race = "牛頭人", side = "horde", mark = "tick" } } },
                        { t = "ul", v = { { text = "|s1259823|是一個非常節省法力值的選擇,並且在合理的冷卻時間內提供了不錯的傷害爆發。" }, { text = "|s1277462|是救命神技,儘管冷卻時間確實較長。作為種族特長來說,它非常強大。" }, { text = "|s20591|和|s20589|完善了種族技能組合。前者是通用的法力值提升手段,後者在PvP中表現卓越,在PvE中也偶有用武之地。" } } },
                        { t = "p", v = "無限服新增的職業-種族組合" },
                        { t = "p", v = "雖然現在下定論戒律牧師最佳種族選項還為時過早,但以下是Beta測試階段的幾個熱門候選:" },
                        { t = "p", v = "聯盟聯盟玩家可以選擇人類、矮人、暗夜精靈和侏儒。" },
                        { t = "p", v = "尤其能帶來種族特長與牧師專屬種族法術的絕佳組合：" },
                        { t = "p", v = "如果侏儒不合你意，那麼值得一提，因為其強大之處在於|s1259799|。與我們的|s431622|天賦結合後，它應該會成為一個非常強大的爆發治療窗口。可惜的是，我們其他一些法術如|s10901|無法暴擊。" },
                        { t = "p", v = "部落部落玩家可以在和之間選擇。你的選擇相當靈活，但我建議你選亡靈。|s20577|能快速回復法力值，在升級時為你節省時間。|s1277324|是戰鬥中的法力回覆，代價是無關緊要的生命值消耗，|s7744|仍然是遊戲中最佳的 PvP 種族特長之一，並且|s1260201|提供免費的傷害加成，即使在治療天賦中也同樣實用。" },
                    } },
                    { key = "prof", flow = {
                        { t = "p", v = "專業技能內容在《魔獸世界：無限》版本中進行了徹底重做，許多滿級專業物品目前還沒有公開資料。在練級初期以及無限測試服中，推薦選擇附魔和裁縫。" },
                        { t = "p", v = "附魔可以製作魔杖，在練級過程中會構成傷害輸出的主要來源之一。能夠製造更高等級的魔杖會帶來巨大優勢。附魔還可以讓你為裝備附魔，在升級過程中獲得額外屬性。初期留意" },
                        { t = "p", v = "附魔紮營加成是" },
                        { t = "p", v = "裁縫可以製作布甲，這是牧師唯一能穿的護甲類型。在《無限》版本中有許多極為強力的裁縫布甲可以製作，成為裁縫能顯著提升練級速度和副本表現。裁縫製作的裝備往往優於同等級的任務獎勵，同時每個部位還有更多的選擇。" },
                        { t = "p", v = "裁縫紮營加成是" },
                    } },
                },
            },
            holy = {
                updated = "2026/09/21",
                sections = {
                    { key = "changes", flow = {
                        { t = "p", v = "神聖牧師在經典懷舊服團本治療中已是核心，治療手段圍繞治療術、強效治療術、快速治療、恢復和群體治療展開。《魔獸世界：無限》保留了這一套技能組合，並新增了應對分散傷害的機制，鼓勵切換治療目標，同時移除了一些舊天賦和種族限制。神聖天賦樹中移除了治療專注、強化群體治療和光明之泉。取代它們的是束縛治療、癒合禱言和光明禮讚。所有牧師都可以學習神聖之靈和防護恐懼結界。" },
                        { t = "p", v = "《魔獸世界：無限》為牧師職業引入了不少經典原版中並不存在的新技能與新機制。" },
                        { t = "tb", v = { { "|s1240774|", "束縛治療是神聖系的新天賦。它會同時治療友方目標與施法者本人，威脅值較低，施法時間1.5秒。" }, { "|s1240827|", "癒合禱言是神聖系的新天賦，也是神聖天賦樹的最終天賦點。它會在目標下一次受到傷害或受到非週期性治療時為其治療一次，隨後跳躍至20碼範圍內的一名隊友或團友身上。同一施法者只能存在一個癒合禱言，最多跳躍5次。" }, { "|s1277370|", "神聖恩典是人類牧師的新種族特長，立即治療一名生命值低於50%的友方目標，並移除虛弱靈魂效果。無法對自己施法，冷卻時間10分鐘。人類牧師不再擁有絕望禱言。" }, { "|s1277462|", "應急方案侏族牧師的新種族特長，對一名隊友施加持續30秒的護盾。下一次使其生命值降至35%以下的攻擊將觸發一次吸收效果和一個持續治療效果。每個目標只能存在一個護盾，冷卻時間10分鐘。" } } },
                        { t = "p", v = "《無限》中的神聖牧師將獲得一系列重做與升級後的能力與天賦，以提升團本治療的遊戲體驗。" },
                        { t = "tb", v = { { "|s6346|", "防護恐懼結界現在所有牧師都可以在20級學習。此前它是矮人種族專屬。冷卻時間和持續時間均為3分鐘。" }, { "|s14752|", "神聖之靈現在從30級起即可學習，不再是戒律系天賦。最高等級持續時間1小時。" }, { "|s20711|", "救贖之靈在《無限》中的持續時間為15秒，經典懷舊服中為10秒。" }, { "|s596|", "群體治療現在的施法範圍為40碼，經典懷舊服中為30碼。" }, { "|s10938|", "真言術：韌的最高等級持續時間為1小時。經典懷舊服中6級持續時間為30分鐘。" } } },
                    } },
                    { key = "viability", flow = {
                        { t = "p", v = "神聖牧師依然是PvE中最強的治療者之一。新的神聖天賦補充了對分散傷害的應對，以及切換治療技能時的法力值返還。該專精依舊是布甲、依舊以站樁為主，依舊依賴法力值。" },
                    } },
                    { key = "sw", flow = {
                        { t = "p", v = "根據當前可用內容，神聖牧師最明顯的優缺點如下：" },
                        { t = "good", v = { "靈活的治療手段- 直接治療、恢復、真言術：盾和治療禱言，加上聯結治療和癒合禱言來應對分散傷害。", "強力的團隊增益- 真言術：韌和神聖之靈均為已習得的技能。韌持續1小時。", "驅散與功能性- 驅散魔法、驅除疾病、所有種族都可使用的防護恐懼結界，以及死亡後的救贖之靈。" } },
                        { t = "bad", v = { "易受物理傷害- 布甲與較低的生命值使神聖牧師成為近戰的首要目標。", "機動性不足- 大多數治療需要站樁施法。移動時主要可用的手段是恢復和真言術：盾。", "耗藍較高- 在切換治療技能時，光明聖詩會返還法力值。重複施放同一個法術仍會消耗法力。" } },
                    } },
                    { key = "beginner", flow = {
                        { t = "p", v = "神聖牧師，以及更廣泛的牧師職業，整體都非常容易上手，適合新玩家。牧師在前期練級中擁有出色的生存能力，可以使用多種治療與防禦技能，傷害能力也相當可靠。早期在傷害輸出或法力回覆方面可能遇到的任何問題，都能通過專業技能大幅簡化，尤其是附魔提供的魔杖和裁縫產出的各種布甲。牧師在練級期間的小隊內容中也十分靈活，在早期地下城中既能治療又能造成傷害。" },
                    } },
                    { key = "systems", flow = {
                        { t = "p", v = "《魔獸世界：無限》中牧師區別於其他職業的主要特色是牧師種族法術。首次在10級獲得，20級再次獲得；每個種族除該種族所有職業共有的基礎種族能力外，還提供兩個該種族獨有的法術。這些技能已在下表中整理：" },
                        { t = "tb", v = { { "10級", "|s1277370|", "|s13908|", "|s10797|", "|s1277455|", "|s2652|", "|s9035|" }, { "20級", "|s13896|", "|s1277331|", "|s2651|", "|s1277462|", "|s1277324|", "|s18137|" } } },
                    } },
                    { key = "races", flow = {
                        { t = "p", v = "《魔獸世界：無限》包含全新以及玩家熟悉的職業與種族組合。以下是所有可選方案的簡要一覽：" },
                        { t = "races", v = { { race = "人類", side = "alliance", mark = "tick" }, { race = "矮人", side = "alliance", mark = "tick" }, { race = "暗夜精靈", side = "alliance", mark = "tick" }, { race = "亡靈", side = "horde", mark = "tick" }, { race = "巨魔", side = "horde", mark = "tick" } } },
                        { t = "p", v = "無限服新增的職業-種族組合 目前雖然還無法明確判定哪種種族最適合神聖牧師，但一些可選種族絕對值得關注。聯盟聯盟玩家可以在人類、矮人、暗夜精靈和侏儒之間進行選擇。在這些選項中，侏儒擁有一套非常出色的基礎種族能力，包括|s1259823|，|s20591|，以及|s20589|和獨特的牧師種族技能|s1277455|，|s1277462|使其成為 PvE 和 PvP 內容中神牧的穩妥選擇。人類值得一提的榮譽獎是|s1277370|，一個外部瞬發治療技能，還能移除虛弱靈魂。矮人保留|s13908|並獲得|s1277331|。暗夜精靈仍然擁有|s20585|，|s20580|以及|s2651|，|s10797|。恐懼結界不再是矮人的專屬能力。" },
                        { t = "p", v = "部落部落玩家可以選擇亡靈或巨魔。兩者各有優勢，亡靈的基礎屬性與牧師種族特長組合非常出色，在升級、團本小隊玩法中都能提供價值，以及PvP內容中同樣適用。|s20577|是升級過程中（尤其是早期）維持生命值與法力值的優秀能力，而|s1260201|法術傷害則能提供穩定的被動傷害與生存能力。|s1277324|是一項有趣且獨特的法力值回覆手段，而|s7744|仍然是PvP戰鬥中的常備技能，儘管它已不再提供免疫效果。" },
                    } },
                    { key = "prof", flow = {
                        { t = "p", v = "說到專業技能，隨着遊戲進展，許多可行的選項最終都會在後期內容中變得有效或受歡迎。就當前階段而言，尤其是升級過程中，有兩個專業技能立刻脫穎而出：附魔和裁縫。附魔可以為玩家提供各種小幅裝備增強效果，但選擇這個專業的主要原因是可以製作魔杖。雖然起步武器的表現已經相當不錯，但旅行早期可製作的魔杖（分別在5級和13級需要）能極大提升傷害輸出，尤其在與……|s14524|。裁縫同樣能帶來各種容易獲取的布甲裝備，提升升級速度和生存能力，但特別值得一提的是它包含一些拾取綁定的稀有物品的圖紙，例如旅行初期可製作的特殊披肩，對於其等級要求而言尤其強大。作為額外獎勵，裁縫製作的旅行披風和附魔製作的旅行魔杖都提供露營加成，在升級過程中特別有用，可以提升法力值回覆和生存能力。" },
                    } },
                },
            },
            shadow = {
                updated = "2026/09/21",
                sections = {
                    { key = "changes", flow = {
                        { t = "p", v = "《魔獸世界：無限》開發團隊最雄心勃勃的目標之一，就是為傳統的弱勢專精提供新的增強手段。從無限版本的改動中可以看出，暗影牧師正是在這一理念下迎來重大變革的專精之一。在經典版本中，儘管暗影牧師憑藉單挑能力在PvP玩家中頗受歡迎，但在團隊副本中卻一直是最弱的輸出職業之一，通常只是為了給術士提供增益纔會帶一位。" },
                        { t = "p", v = "儘管遊戲中仍有大量內容有待探索,但開發團隊顯然已經加入了一系列改動,直接着眼於提升暗影牧師在終極PvE裏作為傷害輸出者的可用性,同時保留了暗影的核心定位。" },
                        { t = "p", v = "《魔獸世界：無限》為牧師職業引入了大量經典舊世中原本沒有的全新有趣技能。" },
                        { t = "tb", v = { { "|s1309595|", "暗言術：滅是暗影牧師在《燃燒的遠征》中首次引入的標誌性技能，在無限服中已被添加為基礎牧師法術，32級即可習得。暗言術：滅是斬殺低血量敵人的完美工具，可用於觸發|s15270|，並在其中投入兩點天賦|s1310076|，暗言術：滅成為一個強大的斬殺型循環技能，冷卻時間僅15秒。" }, { "|s1277324|", "黑暗犧牲是《無限》中新增的多個牧師種族特長之一，它為亡靈牧師提供類似於術士的效果。|s1454|能力，在15秒內將生命值轉化為法力值。儘管尚不清楚該技能在實際使用中的強度如何，尤其是考慮到其長達10分鐘的冷卻時間，但毫無疑問，這項能力與暗影牧師的技能體系天然契合。" }, { "|s1277462|", "應急方案是牧師的新種族特長之一，能讓侏儒牧師為指定目標附加一個防禦性的增益效果：當目標生命值較低時，獲得護盾併產生持續治療效果。假設應急方案可以在暗影形態下使用，那麼這項技能是一個非常有趣的外部防禦手段，可在緊急情況下對盟友或自己使用。" } } },
                        { t = "p", v = "暗影牧師在《魔獸世界：無限》中將一直受益於大量經過重做與更新的技能和天賦，這些改動旨在提升其作為輸出專精的整體可用性和操作體驗。" },
                        { t = "tb", v = { { "|s2944|", "吞噬瘟疫現在是牧師的基礎法術，冷卻時間縮短至1分鐘。此前，吞噬瘟疫只有亡靈牧師才能使用，冷卻時間為3分鐘。" }, { "|s15473|", "暗影形態基本上被徹底重做了：暗影形態現在僅提高10%的暗影傷害（原為15%），但同時使暗影法術的法力值消耗降低50%，並將暗影法術的暴擊傷害加成提高100%。此外，只有治療法術無法在暗影形態下施放，也就是說你可以在保持暗影形態的同時施放神聖系的傷害和輔助法術。受到物理傷害降低15%的效果保持不變。" }, { "|s15286|", "吸血鬼之擁的冷卻時間現在為1分鐘，持續30秒，並且新增了觸發心靈竊取的效果：當受影響的敵人死亡時會激活心靈竊取。這為暗影牧師在團隊作戰中提供了一種更穩定的心靈竊取觸發方式，特別是在有大量小怪的團戰首領戰中，敵人最後一擊幾乎不可能獲取。" }, { "|s15257|", "暗影交織已被重新調整，不再提高目標所承受的全部暗影傷害，而僅僅是提高施法者自身的暗影傷害。這與經典版本相比是重大改動，因為該天賦歷史上曾促使團隊為了獲取這一增益而帶上恰好一名暗影牧師，無視其整體傷害表現。這將遊戲末期PvE的重心重新拉回到暗影牧師個人的傷害輸出上，這也是整個職業設計新思路中反覆強調的主題。" } } },
                    } },
                    { key = "viability", flow = {
                        { t = "p", v = "雖然無限開發團隊對暗影牧師所做的改動顯然是為了直接改善其在遊戲末期PvE中的表現，但其實際效果仍有待觀察。" },
                    } },
                    { key = "sw", flow = {
                        { t = "p", v = "根據現有資訊，以下是暗影牧師一些最顯著的優勢與劣勢：" },
                        { t = "good", v = { "強大的單挑PvP能力暗影牧師的技能組合特別適合一對一的PvP，這在《魔獸世界：無限》中不太可能改變。", "全新的法力值回覆手段暗影牧師歷來法力值消耗極大，而《無限》中針對暗影的諸多改動都旨在改善該專精的法力值經濟。", "擁有斬殺階段傷害暗言術：死的加入以及配套天賦早逝為暗影牧師提供了一個針對生命值低於20%敵人的快速擊殺傷害定位。" } },
                        { t = "bad", v = { "遊戲末期團本表現尚不明朗針對暗影牧師的改動移除了其原有的團本定位，轉而專注於個人傷害輸出，但尚不清楚此版本的暗影牧師在與其他專精的團本對比中表現如何。", "暗影形態下無法治療- 其他混合型職業在副治療支援隊友時可能更輕鬆一些，因為暗影牧師在暗影形態下無法施放治療法術，只有吸血之擁等效果例外。", "升級過程中缺乏暗影特色- 暗影牧師的主題和視覺表現雖然經典，但需要一定時間才能完全成型。精神鞭笞在20級才能習得，而核心機制暗影形態要到40級才能解鎖。" } },
                    } },
                    { key = "beginner", flow = {
                        { t = "p", v = "暗影牧師，乃至整個牧師職業，都非常容易上手，適合新手玩家。牧師在早期升級時生存能力出色，擁有多種治療和防禦技能，同時傷害輸出也不差。早期在傷害或法力回覆方面遇到的任何困難，都可以通過專業技能大幅簡化，尤其是附魔提供的魔杖，以及裁縫製作的布甲。在升級期間的地下城中，牧師還能靈活切換治療與輸出，適應性很強。" },
                    } },
                    { key = "systems", flow = {
                        { t = "p", v = "《魔獸世界：無限》中區別於其他職業的牧師核心特色是種族專屬法術。分別在10級和20級解鎖，每個種族除了通用的種族特長之外，還擁有兩項獨有的種族專屬法術。下表列出了這些技能：" },
                        { t = "tb", v = { { "10級", "|s1277370|", "|s13908|", "|s10797|", "|s1277455|", "|s2652|", "|s9035|" }, { "20級", "|s13896|", "|s1277331|", "|s2651|", "|s1277462|", "|s1277324|", "|s18137|" } } },
                    } },
                    { key = "races", flow = {
                        { t = "p", v = "《魔獸世界：無限》包含了全新以及經典熟悉的職業與種族組合。以下是所有可選組合的快速概覽：" },
                        { t = "races", v = { { race = "人類", side = "alliance", mark = "tick" }, { race = "矮人", side = "alliance", mark = "tick" }, { race = "暗夜精靈", side = "alliance", mark = "tick" }, { race = "亡靈", side = "horde", mark = "tick" }, { race = "巨魔", side = "horde", mark = "tick" } } },
                        { t = "p", v = "無限服新增的職業-種族組合" },
                        { t = "p", v = "雖然現在下定論哪些種族最適合暗影牧師還為時尚早，但其中一些選項絕對值得特別關注。" },
                        { t = "h4", v = "聯盟" },
                        { t = "p", v = "聯盟玩家可以在人類、矮人、夜精靈和侏儒之間進行選擇。在這些選項中，侏儒擁有一套相當出色的基礎種族技能，例如|s1259823|、|s20591|和|s20589|，以及獨有的牧師種族法術|s1277455|和|s1277462|，無論是在 PvE 還是 PvP 內容中，都是暗影牧師的可靠選擇。夜精靈同樣值得一提，其基礎種族技能中既有|s20585|和|s20580|這類新奇獨特的效果，也擁有強大的|s1259799|技能。" },
                        { t = "h4", v = "部落" },
                        { t = "p", v = "部落玩家可以在亡靈和巨魔之間進行選擇。雖然兩種選項都有各自的優勢，亡靈的基礎種族技能和牧師職業種族技能組合非常出色，在練級、滿級團隊副本和PvP內容中都能提供價值。|s20577|是一個在練級過程中、尤其是初期階段維持生命值和法力值的優秀能力，而|s1260201|則同時提供可觀的被動傷害和生存能力。|s1277324|是一個有趣且獨特的工具，可提供額外的法力值回覆，而|s7744|儘管不再提供免疫窗口期，但仍然是PvP戰鬥中的常用技能。" },
                    } },
                    { key = "prof", flow = {
                        { t = "p", v = "在專業技能方面，許多可行的選項最終都可能成為滿級內容中有效或受歡迎的選擇。在這個階段，尤其是練級過程中，有兩個專業立刻脫穎而出：附魔和裁縫。" },
                        { t = "p", v = "附魔可以為玩家提供各種小型裝備強化效果，但早期選擇這個專業的主要原因是能夠製作魔杖。雖然魔杖在大多數可用初始武器中表現更出色，並且分別需要5級和13級才能使用，對傷害輸出有巨大提升，尤其是與|s14524|搭配時效果更佳。" },
                        { t = "p", v = "裁縫還提供多種容易獲取的布甲裝備，可提升練級速度和生存能力，但尤為值得一提的是，它擁有一些拾取後綁定的稀有品質特殊物品配方，例如 ，這些物品就其等級需求而言屬性格外強力。" },
                        { t = "p", v = "此外，裁縫的 和附魔的 都提供露營加成，在練級過程中特別實用，可提升法力值恢復和生存能力。" },
                    } },
                },
            },
        },
        SHAMAN = {
            ele = {
                updated = "2026/10/05",
                sections = {
                    { key = "changes", flow = {
                        { t = "p", v = "與其他專精相比，元素薩滿目前的改動總體不多，主要集中在一些便利性優化以及來自《燃燒的遠征》和《巫妖王之怒》中備受喜愛的迴歸技能，例如|s408438|和|s408490|。我們後期的法力值問題或許可以通過恢復天賦樹中的|s1223033|天賦來解決，但其他問題——例如練級難度——由於我們法術基礎傷害的改動以及天賦樹早期缺乏新天賦支援，反而變得更嚴峻。就目前來看，我們的單體傷害不盡如人意，但群體傷害因新加入的|s408341|技能而格外強大。" },
                        { t = "tb", v = { { "|s408341|", "法術——薩滿祭司基礎技能，對你當前火圖騰周圍10碼範圍內的敵人造成火焰傷害。該技能取代了火焰新星圖騰。其傷害數值非常高。" }, { "|s408438|", "元素天賦——3點——從《燃燒的遠征》中迴歸，使你的閃電箭和閃電鏈有3/6/10%的幾率在同一個目標上再施放一個相似的法術，不消耗法力值，傷害減半且不會產生仇恨。觸發幾率遠低於後續資料片中的版本，因此表現偏弱。" }, { "|s408490|", "元素天賦/技能/法術——向目標投擲熔岩，造成火焰傷害。如果目標身上已有烈焰震擊，熔岩爆裂的傷害提高20%。在歷史上，熔岩爆裂在烈焰震擊存在時必定暴擊，但本版本對此進行了調整，以避免我們在暴擊率提高時出現收益衰減的問題。" }, { "|s1223033|", "恢復天賦——3點——使你在施法時可以保留17/33/50%的法力值回覆。這應該能為元素薩滿提供一個更穩定的被動法力回覆來源，而這正是原汁味魔獸世界版本中我們極度欠缺的能力。" }, { "|s66842||s66843||s66844|", "法術——分別於20、30、40級習得，作為薩滿祭司的基礎技能加入，可以為大地、火、水、空氣四種圖騰各配置一套，然後一次性同時插下所有4個圖騰。這些技能最初在《巫妖王之怒》中加入，但本版本中較長的施法時間使其使用起來較為繁瑣。" }, { "|s36936|", "法術——將圖騰收回大地，按每個圖騰的法術消耗返還25%的法力值。該技能同樣最初在《巫妖王之怒》中加入，對於維持法力值以及避免因殘留圖騰意外激怒敵人而言，是一個非常實用的補充。" }, { "|s437009|", "法術——將你當前激活的圖騰重新放置到30碼範圍內的指定位置，冷卻時間1分鐘。該技能最初在《熊貓人之謎》中加入，是一個不錯的便利性技能，避免了為了重新插圖騰而不得不跑到相應位置的麻煩。" } } },
                        { t = "tb", v = { { "|s16089|", "元素天賦 - 5點 - 使你的灼熱圖騰與熔岩圖騰以及你的火焰、冰霜和自然法術的暴擊傷害加成提高20/40/60/80/100%。這一改動源自原先位於天賦樹更深處的單點天賦（提供100%加成）。這實際上對一個本就弱勢的專精造成了不必要的削弱，但能讓增強薩滿也能享受該天賦。" }, { "|s29062|", "元素天賦 - 3點 - 使你在施放閃電箭、閃電鏈和熔岩爆裂時，因受到傷害攻擊而被打斷的程度降低23/46/70%。在經典懷舊服中，施法打斷保護只在受到暴擊時觸發，使得該天賦的這一版本在所有場景中都更為實用。" } } },
                    } },
                    { key = "beginner", flow = {
                        { t = "p", v = "元素薩滿歷來擁有簡單的操作風格，非常適合新手玩家；不過，並不建議在30級後期之前用元素天賦進行練級，因為那時你才能點出|s16578|。在《魔獸世界：無限》目前的情況下更是如此——在缺少大量法術強度裝備的早期，元素薩滿的練級難度更高。" },
                    } },
                    { key = "races", flow = {
                        { t = "p", v = "矮人是玩家的唯一選擇。對於聯盟部落玩家而言，獸人可能略勝一籌，但所有可選種族的表現都應當相差無幾——主要取決於戰鬥時長、敵人類型以及你所擁有的裝備等因素。" },
                        { t = "races", v = { { race = "獸人", side = "horde", mark = "tick" }, { race = "牛頭人", side = "horde", mark = "tick" }, { race = "巨魔", side = "horde", mark = "tick" } } },
                        { t = "p", v = "無限服新增的職業-種族組合" },
                        { t = "p", v = "玩家的唯一選擇。對於" },
                        { t = "p", v = "矮人- 目前聯盟玩家的唯一可選種族。他們的種族特長|s1259719|在使用錘類武器時獲得 1% 暴擊幾率。這讓矮人相較於部落對應種族更為弱勢。" },
                        { t = "h4", v = "部落" },
                        { t = "p", v = "獸人- 獸人的種族特長|s20572|在使用斧類武器時於 2 分鐘冷卻時間內使攻擊強度與法術強度提高 10%，並因|s20574|獲得 1% 暴擊幾率。血性狂暴本身極強，平均下來相當於 2 分鐘內提升 1.25%。巨魔- 巨魔的種族特長|s20554|在 3 分鐘冷卻時間內使攻擊與施法速度提高 10%，持續 10 秒。這明顯弱於經典舊世時期根據已損失生命值獲得更高加成的版本。|s20557|僅在特定情況下有用。|s401460|和|s20555|對於喜歡練級與單刷的玩家來說極為強力。- 牛頭人的種族特長|s20550|現在還使你的命中幾率提高1%。這是相當強力的效果，可以讓你的配裝更加靈活。他們的其他種族特長在練級和戶外玩法中都很出色，擁有|s12566|讓你能夠快速穿越世界，以及標誌性的|s20549|- 非常適合用來脫離險境或在PvP中使用。天裔- 天裔的種族特長|s1259710|提供1%的攻擊和施法速度提升。這看起來似乎不多，但急速/施法速度對於元素薩滿來說歷來都是非常強力的屬性。|s1259686|是一個不錯的品質級技能，既能加快你的練級速度，也能在關鍵時刻幫你脫離敵人。|s1259707|依然在特定情況下非常強力，而|s1259416|在野外或許能在關鍵時刻救你一命。" },
                    } },
                    { key = "prof", flow = {
                        { t = "p", v = "制皮- 已經發現了數個裝備屬性優秀的新制皮圖紙。我們知道暴雪的理念是\"最佳裝備將更難獲得\"，因此製造的裝備在練級和遊戲後期都可能會成為你配裝的重要補充。**附魔**- 附魔一直是個強勢選擇，因為附魔師可以製作武器油，而且許多附魔的成本高得離譜。在《魔獸世界：無限》中，武器油的強度獲得了進一步提升。此外，附魔師現在還可以製作各種圖騰，例如 。目前還無法預測滿級後的情況，但附魔已經展現出了極大的潛力。" },
                    } },
                },
            },
            enh = {
                updated = "2026/10/02",
                sections = {
                    { key = "changes", flow = {
                        { t = "p", v = "先說最重要的事：增強薩滿祭司現在使用雙手武器。這個版本的遊戲中不會有官方的雙持支援，相關技能已被移除。這個改動對部分玩家來說是好事，對另一部分來說則可能是災難。不過除雙手武器高傷害帶來的爽快打擊感外，這種武器風格的變化對增強薩滿祭司的常規玩法可能影響不大。|s16362|來自我們高傷害雙手武器的強力打擊，當然也很過癮。另一個重大變化是天賦的加入，該天賦早在巫妖王之怒版本就已加入增強專精。疊加到5層後可以|s15208|獲得瞬發施法。還有一些圖騰也做了調整，同時新增了|s11307|法術，相關內容將在改動部分重點介紹。" },
                        { t = "tb", v = { { "|s11307|", "現在綁定你當前激活的火系圖騰，而不是作為獨立的圖騰存在。使用該技能會在你的火系圖騰周圍產生一次新星效果。" }, { "|s437009|", "該技能可以將你當前所有激活的圖騰重新放置到指定位置。" }, { "|s408498|", "該天賦疊加到5層後，可以讓你瞬發施放|s15208|。" }, { "", "這是一個3分鐘冷卻時間的爆發技能，開啓後使你的近戰攻速提高30%，持續25秒。" } } },
                        { t = "tb", v = { { "", "現在可以在室內變形為幽靈狼了。升級到2級時，它還會變成瞬發技能。" }, { "", "原本是將攻擊強度轉化為法術強度，現在改為將智力轉化為法術強度。" }, { "", "該天賦在2級時，讓你施法後仍能保持100%的法力值回覆，無視5秒回覆規則，並且還有100%的幾率重置|s17364|每當你閃避或招架時。" }, { "", "使你能夠招架攻擊。同時降低你製造的大量威脅值，除非你正在使用|s16316|，此時反而會提高30%。" }, { "|s17364|", "現在冷卻時間為8秒，而不是12秒。" }, { "|s66842|", "現在為3秒施法時間，可同時放置全部4個圖騰。" }, { "|s10614|", "不再為你的小隊提供脈衝式的武器附魔增益；改為穩定的團隊範圍增益，可與武器附魔疊加。" }, { "|s16387|", "現在提供一個短時脈衝增益，放大團隊主手攻擊傷害，可與武器附魔疊加。" }, { "|s16362|", "現在可以與|s16387|。" }, { "|s16342|", "現在可以與|s10614|。" } } },
                    } },
                    { key = "viability", flow = {
                        { t = "p", v = "《魔獸世界：無限》的一個目標是讓每個職業和天賦都能發揮用途。目前來看，增強天賦是非常強力的練級天賦，能夠依靠武器攻擊而無需消耗太多法力值。後期團本中的可用性目前還無法預測，但就薩滿祭司整體的當前實現而言，並沒有什麼明確的理由讓你優先選擇某個薩滿天賦而非另一個。但有一點非常清楚：每個近戰小隊都會需要至少一名薩滿祭司來提供|s10614|。這將使薩滿祭司職業整體在每次團本中都有極高的需求。增強薩滿祭司的群體傷害表現將非常出色，前提是我們有足夠的法力值來維持|s11307|。至於單體傷害，這仍需觀察，但目前看來同樣頗具競爭力。" },
                    } },
                    { key = "sw", flow = {
                        { t = "good", v = { "機動性- 可在室內使用的瞬發幽靈狼在戶外世界和團隊副本中都非常實用", "群體傷害潛力- 火焰新星是一個冷卻時間短的強力群體傷害技能；配合圖騰傳遞，你可以輕鬆打出漂亮的群體傷害", "功能性- 你不僅能為團隊提供有用的傷害輸出，還能通過圖騰強化和保護隊友" } },
                        { t = "bad", v = { "缺乏獨特性- 如果其他輸出專精的表現超過你，團隊完全可以換成其他薩滿祭司專精，因為圖騰效果是一樣的" } },
                    } },
                    { key = "beginner", flow = {
                        { t = "p", v = "這個版本的增強薩滿祭司對新玩家來說應該很容易上手。此前那些繁瑣的機制都已經得到改善，整體操作也非常簡單。對新手來說，最重要的兩件事就是學會正確使用圖騰和管理好法力值。你會非常依賴自動攻擊，這也能讓你有更多時間去思考這些，整體來說是一個非常適合新手的專精。" },
                    } },
                    { key = "systems", flow = {
                        { t = "p", v = "圖騰管理是每個優秀薩滿祭司玩家的關鍵。你需要清楚自己圖騰的位置、能否覆蓋到所有需要覆蓋的隊友，以及如何最高效地重新佈置圖騰以避免消耗過多法力值。強化自己和隊友是增強薩滿祭司的重要組成部分。" },
                        { t = "p", v = "隨着|s408498|天賦的加入，你將能夠無施法時間且不消耗法力值地使用|s15208|。立即使用一次|s15208|疊到 5 層之後再使用，避免溢出浪費層數。最大化這個天賦的收益一直是各版本經典遊戲中增強薩滿玩法的關鍵環節。" },
                    } },
                    { key = "races", flow = {
                        { t = "p", v = "這是對全新可用種族特長以及全新職業/種族組合的初步介紹。" },
                        { t = "races", v = { { race = "獸人", side = "horde", mark = "tick" }, { race = "牛頭人", side = "horde", mark = "tick" }, { race = "巨魔", side = "horde", mark = "tick" } } },
                        { t = "p", v = "無限服新增的職業-種族組合" },
                        { t = "h4", v = "聯盟" },
                        { t = "p", v = "已加入《魔獸世界：無限》中可選的種族池，成為聯盟方可選的薩滿種族。不幸的是，就 PvE 種族特長而言，即便不是最弱的選擇，也是非常弱的選擇之一。不過在聯盟方只有這一個可選，所以也只能選它。它們的種族特長|s1259721|對野獸的傷害提高 5%，以及|s1259719|只要裝備錘類武器，攻擊和法術的暴擊率就永久提高 1%。這兩個種族特長各有用處，卻都非常依賴場景。|s20594|依然是矮人的招牌種族特長，能立即移除並免疫所有流血、中毒和疾病效果，同時在 8 秒內受到的物理傷害降低 10%。" },
                        { t = "h4", v = "部落" },
                        { t = "p", v = "在《無限》中，部落方可選的薩滿種族非常豐富。最新的成員是|s1259707|和|s1259710|帶來的 1% 急速加成。這些種族特長沒有其他那些那麼依賴場景，但收益依然不高。天裔的真正優勢在於通過種族特長提供的大量移動能力，|s1259686|使你的（坐騎）移動速度提高10%，持續30秒，並且|s1259416|賦予你10秒免費的緩落術。也有一些改動加入到《無限》中，另外一些種族特長則保持不變。|s20549|保持不變，而|s20550|現在還會額外提高1%命中以及5%總生命值。兩個全新加入的種族特長是|s1259918|，在移動時緩慢提高你的行走速度，最高達到30%，以及|s20552|，允許你每小時採集一棵草藥而不需要學習草藥學技能，但每株草藥只能使用一次。|s20557|來強化對野獸的傷害，提高5%。|s20554|提高10%急速，持續10秒。|s20555|基本保持不變，使你的生命回覆速度提高10%，並且戰鬥外回覆總量的10%將在戰鬥內持續。全新加入的種族特長是|s1260270|，在6秒內回覆你最大生命值的50%，但任何移動動作或受到傷害都會打斷此效果。在《無限》中依然是增強薩滿祭司的最佳選擇。雖然|s20574|在裝備斧類武器時提供1%暴擊率依然是場景性的選擇，|s20572|獲得了不錯的改動，能在15秒內提升我們10%的攻擊強度和法術強度，沒有任何負面效果。|s1299026|同樣非常強力，可以瞬間解除並免疫所有詛咒與災厄效果，並且使受到的法術傷害降低15%，持續8秒。|s1299026|與|s20573|的組合，讓獸人成為適合各種內容的全能選擇。" },
                        { t = "p", v = "總體而言，如果你是部落玩家，獸人正在成為PvE和PvP中最強的選擇，但其他三個可選種族也根據你的需求提供各自獨特的增益。不幸的是，聯盟的選擇非常匱乏，矮人目前更多是針對特定情況的選擇，但這不應阻止你選擇矮人薩滿祭司。" },
                    } },
                    { key = "prof", flow = {
                        { t = "p", v = "在Beta測試期間，製造類專業，例如|s10662|和|s9785|看起來非常強力，因為它們可以讓你通過簡單方式獲得屬性不錯的裝備升級。尤其是早期的武器升級感覺提升巨大。當你能夠獲得副本獎勵後，|s9785|的價值可能會下降，但總體而言，它們似乎能夠很好地填補你裝備上的空缺。|s11611|在升級過程中同樣看起來非常強力，為你提供大量強力的增益，這些增益應該也能很好地延續到遊戲後期。" },
                    } },
                },
            },
            resto = {
                updated = "2026/09/23",
                sections = {
                    { key = "changes", flow = {
                        { t = "p", v = "恢復天賦相比其他專精到目前為止改動不多，主要集中在提升操作便利性，以及迴歸一些《燃燒的遠征》和《巫妖王之怒》中廣受喜愛的內容，例如|s408510|和|s1239243|。恢復天賦樹中的新加天賦也有助於緩解經典舊世版本中略顯乏力的法力值消耗問題。儘管練級階段的治療職業僅推薦組隊玩家選擇，但恢復薩滿在遊戲後期的潛力依然強勁，因為|s1223033|天賦樹中的新天賦也有助於改善經典版魔獸原本乏力的法力值經濟。雖然作為治療職業練級只建議在組隊的情況下進行，但恢復薩滿在遊戲後期的潛力依然強勁，因為|s10623|憑藉激流獲得了前所未有的增強，且|s25357|也獲得了強力新天賦的支援，讓薩滿在不考慮套裝獎勵和特定團隊戰鬥的情況下，已具備堅實的核心技能組合。" },
                        { t = "tb", v = { { "|s408341|", "法術 - 該法術為薩滿基礎技能，可對當前火焰圖騰周圍10碼範圍內的敵人造成火焰傷害，並取代火焰新星圖騰。其傷害數值極高。" }, { "|s1239243|", "恢復天賦/技能 - 為友方目標恢復一定生命值，並附加一個持續15秒的強力持續治療效果。同時使你對該目標施放的|s10623|法術的治療效果提高25%。" }, { "|s1223033|", "恢復天賦 - 3點 - 施法時可繼續分別恢復17%/33%/50%的法力值。這是一項強力的法力值回覆手段，使精神屬性對薩滿的價值遠超經典舊世版本。" }, { "|s66842||s66843||s66844|", "法術 - 分別在20級、30級和40級學會，該技能作為薩滿祭司的基礎技能，允許你為每種能力設定一組由土、火、水和空氣圖騰組成的獨特組合，然後一次性放下全部4種圖騰。雖然一次性放下多達4種圖騰非常強力，但你需要為此投入3秒施法時間，因此該法術最適合在準備開Boss前使用，或在當前圖騰到期後再使用。" }, { "|s36936|", "法術 - 將你的圖騰歸於大地，返還每個圖騰施法所需法力值的25%。該技能最初在巫王之怒資料片中加入，對於快速銷燬不需要的圖騰以避免拉到額外敵人，以及在圖騰即將失效或不再有用時恢復法力值都非常實用。" }, { "|s437009|", "法術 - 將你的激活圖騰重新放置到30碼範圍內的指定位置，冷卻時間為1分鐘。該技能最初在熊貓人之謎資料片中加入，是一項非常實用的便捷法術，可以在不跑到位的情況下重新佈置圖騰，或充分利用增益圖騰的較長持續時間，避免通過召喚類技能放下4個新圖騰所需的3秒施法時間。" } } },
                        { t = "tb", v = { { "|s29206|", "恢復天賦 - 3點 - 該天賦曾在你對目標施放|s25357|時最多可疊加3層，使其在應對傷害時表現糟糕且整體效果不佳，但現在它只是治療之湧的基礎強化增益，使其在所有情況下都更加強大，而非侷限於特定場景。" }, { "|s16184|", "恢復天賦 - 2點 - 除了縮短冷卻時間和提升|s20608|的生命值法力值外，現在還使你的最大生命值永久提升4%。" }, { "|s16179|", "恢復天賦 - 5點 - 現在除了法力值減免效果外，還可使命中幾率最多提升5%！" } } },
                    } },
                    { key = "beginner", flow = {
                        { t = "p", v = "恢復天賦歷史上擁有非常簡單的玩法（放下圖騰，使用治療鏈），這使其成為新手玩家的絕佳選擇。雖然你現在也需要使用新的激流和治療之湧——因為它現在作為基礎技能確實變得更強了——但這只是讓該專精變得更加全面，同時保持了其簡單性。一個群體治療技能、一個主要的單體治療技能、以及一個冷卻時間較短的週期性治療效果；這就是恢復天賦保持高效所需的一切！" },
                    } },
                    { key = "races", flow = {
                        { t = "p", v = "矮人是聯盟玩家的唯一選擇。對於部落玩家而言。對於玩家來說，玩家而言，獸人戰士可能略勝一籌，但所有可選種族的表現大致相當——主要取決於戰鬥時長、目標類型以及可用裝備的差異。" },
                        { t = "races", v = { { race = "獸人", side = "horde", mark = "tick" }, { race = "牛頭人", side = "horde", mark = "tick" }, { race = "巨魔", side = "horde", mark = "tick" } } },
                        { t = "p", v = "無限服新增的職業-種族組合" },
                        { t = "p", v = "玩家的唯一選擇。對於部落" },
                        { t = "p", v = "矮人- 聯盟玩家目前唯一的種族選擇。其種族特長在使用錘類武器時獲得1%暴擊幾率。這使得侏儒相對獸人略顯劣勢，因為獸人使用斧類對獲得類似的加成，且附帶其他非常實用的加成。|s1259719|在使用錘類武器時獲得 1% 暴擊幾率。這使得矮人相對弱於獸人，獸人擁有類似的斧類武器加成，同時還附帶其他非常有用的加成！" },
                        { t = "p", v = "玩家來說，" },
                        { t = "p", v = "獸人戰士- 獸人的種族特長|s20572|在使用斧類武器時，可使攻擊強度和法術強度提高 10%，持續 15 秒，冷卻時間為 2 分鐘，並且因|s20574|. 血性狂怒是一個強力的冷卻技能，應在戰鬥中治療需求最高的時刻使用，以增強你的治療量。巨魔- 巨魔的種族特長|s20554|使攻擊速度和施法速度提高10%，持續10秒，冷卻時間3分鐘。這比經典舊世中的同款技能弱得多，舊版初始為10%提速，生命值極低時最高可達30%。|s20557|對治療來說基本沒有用處，其他的自我治療加成也只有些許價值，因為需要時你可以隨時給自己施加遠超於此的治療。牛頭人- 牛頭人的種族特長|s20550|現在還能使你的命中率提高1%，但遺憾的是這對治療者來說基本無關緊要（除了用功能型法術命中目標之外）。他們的其他種族特長在練級和野外玩法中非常出色，其中|s12566|能讓你在世界中飛速穿行，而標誌性的|s20549|- 非常適合用來擺脫困境或參與PVP。天裔- 天裔的種族特長|s1259710|提供 1% 的攻擊和施法速度加成。雖然這點加成不多，但急速/施法速度對於恢復薩滿祭司來說歷來都非常強力。|s1259686|是一個提升移動速度的爆發技能，在某些情況下非常好用，而且|s1259416|可能在野外危機關頭救你一命。|s1259707|對於治療職業來說基本可以無視。" },
                    } },
                    { key = "prof", flow = {
                        { t = "p", v = "制皮—— 已經發現了幾種新的制皮圖紙，其裝備屬性非常優秀。我們知道暴雪的理念是“最佳裝備將更加難以獲得”，因此製造裝備在練級和滿級階段都可能特別有用，可以作為你裝備積累的補充。附魔—— 附魔一直是一個強力選擇，因為它能製作武器油，而且許多附魔的成本也很高。在《魔獸世界：無限》中，武器油（例如）的效果變得更強了。附魔師現在還可以製作圖騰（例如）。滿級階段會發現什麼還很難說，但附魔看起來已經是一個很好的選擇。" },
                    } },
                },
            },
        },
        MAGE = {
            arcane = {
                updated = "2026/10/05",
                sections = {
                    { key = "changes", flow = {
                        { t = "p", v = "奧術已經獨立成為一個專精，不再僅僅用於強化另外兩個法師專精。相反，你需要深入天賦樹，通過奧術法術來造成傷害。這一切都基於奧術衝擊，以及一些讓你消耗更多法力、並與之形成聯動效果的天賦。" },
                        { t = "p", v = "除了奧術衝擊（讓這個專精得以獨立存在）以及彈幕（讓循環更流暢）之外，其餘新加入的技能大多作為輔助天賦出現。" },
                        { t = "tb", v = { { "|s1239700|", "奧術衝擊在2.5秒延遲後造成傷害，每層疊加會使其他所有法術的傷害提高10%，最多疊加4層。每層都會使法力消耗提高175%。" }, { "|s400588|", "這個天賦是與上文提到的法術並列的兩大核心改動之一，讓你能在不消耗法力的情況下，充分利用奧術衝擊的層數來打出可觀的傷害。" }, { "|s11210|", "降低奧術法術的仇恨值，讓你在進行群體傷害時無需擔心仇恨問題。它還提供一定的法術穿透，在目標沒有抗性時可提高傷害。" }, { "|s11247|", "奧術法術的射程最多提升6碼。雖然大多數時候影響不大，但你通常會至少投入一點來解鎖後面的天賦。" } } },
                        { t = "p", v = "這些是對原有法術的改動，正是它們讓奧術擁有了自己的獨立定位。" },
                        { t = "tb", v = { { "|s18462|", "施法期間法力值依然可以持續回覆；該數值從原先滿級時的15%調整為50%。" }, { "|s11232|", "效果與經典舊世版本相同，提供等量智力，但現在還會使奧術法術的暴擊傷害提高100%。" }, { "|s11222|", "該天賦從原先每點2%命中、最高10%，下調為每點1%命中、最高5%。值得注意的是，整體命中屬性經過了重新設計，現在17%即可完全命中，不再有1%的不可避免未命中。" }, { "|s10216|", "同名不同等級的該法術不再疊加，無法再增加區域內生效的持續性傷害效果數量。" }, { "|s18459|", "該火焰天賦現在除了對火焰法術外，還為奧術衝擊和冰槍術提供暴擊幾率加成。" } } },
                    } },
                    { key = "viability", flow = {
                        { t = "p", v = "《魔獸世界：無限》的目標之一是讓每個職業和專精都切實可用。請寫上幾行、大約兩段文字，談談你對職業可行性的初步看法，重點關注團隊副本和 PvE 內容；也可以適當聊一點 PvP 和升級方面的話題。" },
                    } },
                    { key = "sw", flow = {
                        { t = "p", v = "奧法總體上是一個相當令人滿意的專精，最大的短板在於升級。玩家通常用冰霜或火焰專精練級，等到三個專精都各有一席之地的其他資料片，再換回奧術。你的整體表現也在很大程度上取決於你所在的公會以及團隊副本的輸出速度；對於喜歡在自身所處的限制條件下發揮到極致的玩家來說，這可能是一件好事；而對另一些玩家來說則可能令人非常惱火，因為在擊殺時間更短、法力管理更容易甚至無關緊要的戰鬥中，他們本可以打出高得多的表現。" },
                        { t = "good", v = { "爆發潛力- 憑藉奧術強化這類爆發技能，以及提升奧術暴擊傷害的天賦，奧法在遊戲後期極有可能擁有出色的爆發傷害（從歷史來看也確實如此）。", "流暢的輸出循環- 雖然更多是手感層面的事，但先用奧術衝擊疊出減益效果，再接一發迅捷的奧術飛彈，玩起來非常爽快，是很棒的玩法循環。", "法力管理- 很多玩家喜歡奧法的這一面：通過高效利用法力值來最大化傷害/覆蓋時間，從而體現自己的操作水平。" } },
                        { t = "bad", v = { "法力值問題- 雖然這可以算優點，但對於不擅長法力管理的玩家來說，藍量耗盡的感覺會讓人極其惱火。", "升級體驗差- 由於法術的法力消耗非常高，你會經常發現自己只能用魔杖來輸出——魔杖的傷害其實還不錯，但換成任何專精都能做到這一點。", "戰鬥時長不定- 表現與特定首領以及/或整個團隊的表現緊密掛鉤——限制擊殺時間會非常令人沮喪。" } },
                    } },
                    { key = "beginner", flow = {
                        { t = "p", v = "與經典懷舊服中的其他法師專精類似，《魔獸世界：無限》裏的這個所謂新專精起初玩起來非常簡單；至於之後會不會變得更復雜，目前還很難說——可能簡單到只需用奧術衝擊疊到4層，再用強化後的奧術飛彈清掉層數，也可能需要在觸發運氣不佳時中間插入某個法術來移除層數。此外，它很可能還需要根據Boss擊殺時間調整輸出循環，改變每次願意疊加的奧術衝擊層數，以最大化法力值的利用，讓你最關鍵的法術保持更高的整體覆蓋率。" },
                        { t = "p", v = "我猜測是前者，而且目前來看依然非常簡單，因為遊戲在懷舊魔獸世界精神層面上似乎極為簡易，不過這也很難確定。" },
                        { t = "p", v = "升級過程中，魔棒在升級時感覺非常有用，但任何施法者一直以來都是這樣。奧法擁有一個魔棒專精天賦，進一步強化了這一點，尤其是在早期。" },
                        { t = "p", v = "在地下城中進行戰鬥時，群體傷害感覺非常出色，是該天賦專精的最大亮點，並附帶來自|s11210|，這樣你就可以無顧慮地盡情使用魔爆術，假定你的坦克足夠強力（最好是聖騎士坦克）。這確實需要一些調整，才能確保你在地下城中始終保持良好的法力值；調整方法是使用魔杖或低耗法術，比如只用一次奧術衝擊後立刻接奧術飛刃，或者直接用魔杖來省藍，把法力留給那些用群體傷害更划算的拉怪場合。" },
                        { t = "p", v = "個人認為，這個專精對新手來說相當友好，因為初期操作非常簡單，後續優化主要是避免喝水休息，大多數隊伍都能接受。即使後期難度有所提升，我相信也不會太大，而且你還有充足的時間，在升滿級的過程中慢慢適應。" },
                    } },
                    { key = "systems", flow = {
                        { t = "ul", v = { { term = "奧術衝擊層數", text = "- 每次使用時|s1239700|，獲得一層負面效果，最多疊加 4 層——每層都會提高下一次奧術衝擊的法力消耗，並提升你隨後使用的任何一個其他法術的傷害。這個後續法術會將層數清零。玩法就是先疊層，然後用它們強化之後一個有意義的大法術；通常這會是用|s400588|強化過的奧術飛彈來完成，但也可能存在不同的變體。" }, { term = "法力管理", text = "- 奧法的核心要點之一在於不要把法力值視為負擔，而應將其當作必須被推到極限的資源,以便從專精中榨取最大傷害。通常的目標是把每一場戰鬥的法力值耗到 0,前提是之後沒有重要戰鬥。通過奧術衝擊疊層、以及在 2-3 層時清除來靈活控制法力消耗,比低裝等時穩定疊到 4 層要高效得多。到了後期,也會面臨類似的抉擇:在 4 層後賭一輪導彈彈幕觸發,還是用其他法術清掉層數再重新疊奧術衝擊。當然,未來的數值平衡、新法術加入以及現有法術之間的聯動都可能改變這裏給出的基礎思路。" } } },
                        { t = "p", v = "雖然非常簡單,但法師在戰鬥中有以下兩個系統或機制需要記住:" },
                    } },
                    { key = "races", flow = {
                        { t = "p", v = "除了舊的種族-職業組合外,法師現在在部落方還可以選擇獸人,在聯盟方還可以選擇天裔精靈。雖然這很有趣,但並不會蓋過舊的組合,因為所有種族特長都已被重做。目前還很難判斷哪種在終局更優,因為有太多尚未確定的因素。在測試服中,每個種族都有各自有趣的優勢,所以暫時不必過於擔心選擇問題,先挑自己覺得有趣或主題喜歡的就好。" },
                        { t = "races", v = { { race = "人類", side = "alliance", mark = "tick" }, { race = "侏儒", side = "alliance", mark = "tick" }, { race = "亡靈", side = "horde", mark = "tick" }, { race = "巨魔", side = "horde", mark = "tick" } } },
                        { t = "ul", v = { { text = "|s1259817|:" }, { text = "|s20591|:" }, { text = "|s20593|:" }, { text = "|s20589|:" }, { text = "|s1259718|:" }, { text = "|s20600|:" }, { text = "|s20597|:" }, { text = "|s20598|:" }, { text = "|s1259705|:" }, { text = "|s1259707|:" }, { text = "|s1259416|:" }, { text = "|s1259710|:" }, { text = "|s20574|:" }, { text = "|s20572|:" }, { text = "|s1299026|:" }, { text = "|s20573|:" }, { text = "|s20554|:" }, { text = "|s1260270|:" }, { text = "|s20557|:" }, { text = "|s20555|:" }, { text = "|s20577|:" }, { text = "|s5227|:" }, { text = "|s7744|:" }, { text = "|s1260201|:" } } },
                        { t = "p", v = "無限服新增的職業-種族組合" },
                        { t = "h4", v = "聯盟 侏儒" },
                        { t = "p", v = "|s1259817|是侏儒獲得的新的主動冷卻技能,除了傷害提升外,它還附帶一定的法力值消耗減免效果。傷害提升方面不錯,但法力值減免幅度較小。此外,|s20591|直接增加法力值上限,而不是智力。|s20593|不再提供額外等級,而是提升工程學道具的效果。" },
                        { t = "p", v = "種族加成" },
                        { t = "p", v = "人類" },
                        { t = "p", v = "|s1259718|是一個強力的PvP種族特長，讓法師除了閃現術之外還能解除昏迷效果。|s20597|現在也能讓法師受益，裝備劍類武器時暴擊幾率提高2%。精神無論是練級階段，還是隨着遊戲推進獲得法師護甲和奧術冥想天賦之後，都相當重要；即使在戰鬥和施法狀態下，它也能提高你的法力值回覆速度。|s20600|能偵測潛行。比較看情況，但有時能幫你贏下決鬥。" },
                        { t = "p", v = "種族加成" },
                        { t = "p", v = "高階天裔" },
                        { t = "p", v = "|s1259705|是這個新種族的種族特長，使法力值和生命值回覆速度提高100%，持續15秒。如果後期法師在高覆蓋輸出下法力值需求喫緊，它會很有用——不過除此之外，與侏儒增加法力值上限的種族特長相比，它顯得有些遜色。|s1259707|也可能有用，主要取決於你面對的敵人和/或未來要打的團隊副本。" },
                        { t = "p", v = "|s1259710|是其中最有意思的一個，提供1%法術急速。不過目前還很難判斷，與其他種族特長相比，它後期到底有多重要。" },
                        { t = "p", v = "種族加成" },
                        { t = "h4", v = "部落" },
                        { t = "p", v = "獸人" },
                        { t = "p", v = "|s20572|也是新增的，為施法者提供法術強度。|s20573|縮短昏迷效果的持續時間。盜賊恨死它了。|s1299026|另一項優秀的PvP主動冷卻類飾品，能移除詛咒和巫毒，但對法師來說基本沒用，因為我們自己有相應技能|s475|，但它還能在接下來的8秒內降低受到的魔法傷害。|s20574|毫無用處，因為很遺憾，法師無法使用斧類武器。" },
                        { t = "p", v = "種族加成" },
                        { t = "p", v = "巨魔" },
                        { t = "p", v = "巨魔法師依然有一席之地；其種族特長稍有改動|s20554|移除了基於生命值損失提升施法速度的機制，改為始終提供10%的增益。我們還能使用|s20557|，實用性非常看情況——如果目標是野獸就很有用，否則就沒多大意義。它的價值很大程度上取決於當前階段的內容環境。|s1260270|現在改為引導型，在6秒內回覆50%最大生命值，這非常實用，因為我們之前除了繃帶之外並沒有這類防禦手段。" },
                        { t = "p", v = "種族加成" },
                        { t = "p", v = "亡靈" },
                        { t = "p", v = "|s20577|現在除了生命值外還能回覆法力值，進一步改善了任務過程中的續航體驗。|s5227|帶來的提升相當有限。然而，法師PvP中最強的種族特長通常是|s7744|，它能解除或免疫魅惑、恐懼和睡眠效果。這相當於PvP中多了一個免費的飾品位。|s1260201|隨等級恢復，基於耐力值，會隨裝備成長。對 PvE 中的輸出職業，以及 PvP 中那些\"一點血量都關乎生死\"的時刻都很有影響。" },
                        { t = "p", v = "種族加成" },
                    } },
                    { key = "prof", flow = {
                        { t = "p", v = "《魔獸世界：無限》中的專業技能目前都得到了相當大的加強，使彼此之間的差距縮小了不少——即便過去對法師毫無用處的專業，如今也有了一定價值。這並不意味着它們都會一樣強，但現在還為時過早，無法確定未來法術/交互/縮放機制的改動，甚至尚未進行的平衡調整會如何影響各個專業的發揮。這並不妨礙我們對奧法法師可能適用的專業做出有依據的預判（雖然知道未來可能會有所變化）：\n工程學目前相當值得關注，因為它現在擁有諸如氮氣推進器這樣的工程道具，單憑這一點就讓該專業成為了畢業選擇。它常被用於短距離爆發移動以大幅提升站樁時間（從而獲得輸出提升），或完全規避某些機制（讓你無需堆疊防禦向屬性，以另一種方式獲得進攻向屬性）。此外，它仍會包含典型的爆炸物以及可能的其他功能性道具，這意味着它在團隊副本和 PvP 中都始終具有很高的價值。\n裁縫為布甲提供刺繡附魔，但由於我們仍處於 beta 階段，目前尚不清楚它是類似巫妖王之怒那樣在披風上帶有特定內置冷卻時間的法術強度觸發，還是像燃燒的遠征/巫妖王之怒中腿部附魔那樣只是附帶固定法術強度的廉價附魔，又或者是完全不同的形式。如果它是觸發型附魔，那麼在短時間戰鬥或與奧術強化等增益效果結合時可能會非常強力；如果只是固定法術強度，那麼它就歸屬於以下三個專業同一類別。\n鍊金、附魔和制皮在很大程度上取決於它們提供的總屬性加成，以及這些加成彼此之間的比較。" },
                        { t = "tb", v = { { "", "", "法力回覆", "製造特定試劑，隨後解鎖需要在鍊金實驗室製作的配方。" }, { "", "", "力量提高", "提供可用的鐵砧，隨後解鎖需要在鍛造臺製作的配方。" }, { "", "", "護甲、全屬性與抗性提高", "分解附魔素材更高效，隨後解鎖需要在奧術鍛造臺製作的配方。" }, { "", "", "購買試劑", "新增裝備修理，隨後解鎖需要在無政府主義者工作臺製作的配方。" }, { "", "", "智力提高", "種下的種子隨時間生長出草藥，隨後可將種子倍增或組合成更稀有的檔位。" }, { "", "", "休息經驗最多提升一級的5%", "製造特定試劑，隨後解鎖需要它的配方。" }, { "", "", "近戰攻擊強度提高", "隨時間生成一個普通礦點，隨後解鎖需要它的配方。" }, { "", "", "2%爆擊", "提供野獸追蹤，隨後新增一個陷阱。" }, { "", "", "精神提高", "製造特定試劑，隨後解鎖需要它的配方。" }, { "", "", "允許烹飪並提供3個營地功能位", "可容納5個、隨後10個營地功能；2級時還為提升耐力的食物提供解鎖。" }, { "", "", "耐力", "治療藥水與解毒劑，隨後是治療藥水與藥膏。" }, { "", "", "全屬性提高8%", "釣魚技能魚餌，外加1小時非常見魚，隨後是稀有魚。" } } },
                        { t = "p", v = "專業技能總覽指南" },
                    } },
                },
            },
            fire = {
                updated = "2026/10/05",
                sections = {
                    { key = "changes", flow = {
                        { t = "p", v = "火焰專精獲得的新技能不多，但其中最主要的那個——|s400624|——會讓|s11366|真正成為火焰法師輸出循環中重要的一環。至於|s11078|，它看起來主要是個練級用的技能。最後，|s1237313|，雖然它同樣造成火焰傷害，但目前還很難說它對火焰專精是否真正有用，因為這取決於該法術未來的數值成長和聯動機制，而這些我們暫時還無法測試。" },
                        { t = "tb", v = { { "|s400624|", "最多可疊加三層，每當你用非週期性法術打出兩次暴擊便可獲得一層。每層會使|s11366|的施法時間縮短25%。" }, { "|s11078|", "使火衝擊的冷卻時間縮短2秒。擊殺一個等級與你相近的怪物後，你的下一個火衝擊暴擊幾率提高50%。" }, { "|s1237313|", "發射一枚法術飛彈，造成冰火傷害，並對敵人同時施加減速效果和週期性傷害效果。" } } },
                        { t = "tb", v = { { "|s11119|", "你的法術暴擊會使目標燃燒，在4秒內受到相當於該法術傷害40%的傷害。現在這完全是一個屬於個人的傷害技能，不會與其他法師的點燃疊加，也就是說你無法再持續“滾動”點燃了。" }, { "|s11095|", "現在改為個人效果，不再是全團都能受益的目標減益；它只會增強你自身的火焰傷害。" }, { "|s11129|", "每命中一次，暴擊幾率便提高10%，直到你用火焰法術打出3次暴擊為止。" }, { "|s10216|", "在目標區域造成一些群體傷害，隨後留下一片地面效果，在8秒內對區域內的敵人持續造成傷害。" } } },
                    } },
                    { key = "viability", flow = {
                    } },
                    { key = "sw", flow = {
                        { t = "p", v = "火焰法師的強度需要相當多的裝備來支撐，因為它需要相對穩定的暴擊才能發揮大多數技能聯動。即便裝備相當出色，在達到專精上限方面也常常非常依賴運氣——這取決於玩家對這種遊戲風格的看法，可以是讓人喜愛，也可以是讓人厭惡的點。以當前的狀態來看，它的操作手感也有些彆扭，因為|s400624|目前遊戲內的是一個新版天賦，無法讓你瞬發炎爆術，只會縮短其施法時間，從巫妖王之怒版本（該天賦加入的版本）起就存在的專精流暢感基本上被破壞了。" },
                        { t = "good", v = { "高傷害潛力- 火焰通常是遊戲中成長性最高的專精之一。由於依賴暴擊，其數值通常針對滿級滿裝進行平衡。也就是說，當你達到那個階段時，傷害通常非常出色。", "運氣好時手感極佳- 當暴擊連續觸發、各項要素完美契合時，作為法師的體驗是無與倫比的。" } },
                        { t = "bad", v = { "依賴運氣- 雖然這可以是優點，但對於那些希望對自己的表現和輸出擁有更多掌控感的玩家來說，這是該專精的一大缺點。", "彆扭的輸出循環- 由於熱門天賦|s400624|的改動，它不再擁有瞬發炎爆術，而是改為每層提供少量施法時間縮短，削弱了玩家在未來資料片中喜愛的由該天賦帶來的機動性。", "依賴裝備- 雖然這常常是該天賦專精成長性出色的原因，但也意味着如果你想在裝備未成型時玩它，或是在裝備對天賦專精並不友好的團本里玩，它的傷害輸出很容易大幅落後。" } },
                    } },
                    { key = "beginner", flow = {
                        { t = "ul", v = { { text = "用魔杖收掉殘血目標；" }, { text = "在暴擊率較高時使用火焰衝擊來拉住下一隻怪物。" } } },
                        { t = "p", v = "與經典《魔獸世界》中的其他法師天賦專精類似，《魔獸世界：無限》中的火焰天賦起初感覺非常簡單；至於以後是否會變得更復雜，目前尚不清楚。它可能會保持現在這樣的簡單玩法：用火球術疊到3層熱力迸發，然後施放一次炎爆術。同時還要保持強化灼燒的減益效果始終生效，在持續時間較長的戰鬥中維持住。" },
                        { t = "p", v = "目前還無法得知霜火箭在該天賦專精中的影響，因為該法術的交互效果及潛在傷害尚未明確，Beta測試中也暫不可用。" },
                        { t = "p", v = "在練級時，這天賦專精的體驗很簡單，所用火焰就是|s11078|在轉到下一個目標時，儘量獲得一次暴擊，使用火焰衝擊作為起手。這樣可以讓你擊殺當前敵人後，對下一個目標施放炎爆術，再用火焰衝擊獲得更高的暴擊幾率。在非常低的等級時，你可以直接用法杖把敵人擊殺，然後用覺醒之火 火焰衝擊開啓下一個目標的戰鬥，如此循環：" },
                        { t = "p", v = "如果在初期點出奧術天賦中的魔杖專精，可以進一步提升這個流程，因為該天賦能進一步提高魔杖傷害；再加上現在魔杖也擁有法術強度係數，這讓它在練級時變得非常強力。" },
                        { t = "p", v = "同樣值得一提的是，在低等級時裁縫裝備以及副本和任務裝備更加重要，因為所有法術的基礎傷害都被削弱了，需要一定的法術強度才能恢復到經典《魔獸世界》中我們熟悉的強度。" },
                        { t = "p", v = "在副本中，群體傷害一如既往地出色，特別是現在還能用聖騎士作為坦克，讓你在很低的等級副本中就能開始使用AoE技能。這需要一定的適應，才能保證在副本中法力值始終充裕；具體做法是：預讀炎爆術後頻繁使用法術技能，並利用前一個怪物死亡時觸發的覺醒之火效果，把法力值留給更值得的AoE場合——先用火焰衝擊配合衝擊再施法術。" },
                    } },
                    { key = "systems", flow = {
                        { t = "ul", v = { { term = "點燃", text = "- 是火焰法師天賦的核心機制之一。當玩家用非週期性法術造成暴擊時，會將 40% 的傷害轉化為持續性傷害效果（DoT）。過去這一機制較為複雜，需要團隊配合，因為每個玩家的點燃效果會疊加成一個巨大的 DoT；而在《魔獸世界：無限》中，它變成了純個人機制，與未來版本的魔獸世界一致。這使得該天賦變得完全被動，無需調整任何玩法。總體而言，這讓該專精對絕大多數玩家來說更加簡單易上手。" }, { term = "熱力迸發", text = "- 這是與以往及未來版本的主要區別；只要用火焰系法術造成暴擊就能觸發該效果（不再需要連續兩次暴擊）。此外，它可使炎爆術的施法時間每層縮短 25%，最多疊加 3 層。這與過去天賦的“瞬發”效果不同。疊加這些觸發效果，再用主法術，然後接一發快速施法的炎爆術，將是輸出循環的關鍵。" }, { term = "強化灼燒", text = "- 是你的個人減益，給目標掛上後，可使火焰系法術對其造成的傷害提高 15%，最多可疊滿，這是最大化傷害的關鍵。務必保持該減益不間斷，尤其在首領戰中不能讓它斷掉。" } } },
                        { t = "p", v = "雖然火焰法師的玩法非常簡單，但有以下兩個需要時刻留意的機制：" },
                    } },
                    { key = "races", flow = {
                        { t = "p", v = "除了原有的種族與職業組合之外，法師現在還可以是部落方的獸人，以及聯盟方的天裔精靈。雖然這兩個組合很有意思，但它們並不會蓋過原有組合，因為所有種族特長都經過了重做。目前還很難判斷哪種組合在滿級強更出色，因為有太多未知因素。在測試服中，每個組合都有各自的優勢，所以現在不用太糾結選擇；不如先挑一個你覺得在外觀或主題上有趣的組合。" },
                        { t = "races", v = { { race = "人類", side = "alliance", mark = "tick" }, { race = "侏儒", side = "alliance", mark = "tick" }, { race = "亡靈", side = "horde", mark = "tick" }, { race = "巨魔", side = "horde", mark = "tick" } } },
                        { t = "ul", v = { { text = "|s1259817|:" }, { text = "|s20591|:" }, { text = "|s20593|:" }, { text = "|s20589|:" }, { text = "|s1259718|:" }, { text = "|s20600|:" }, { text = "|s20597|:" }, { text = "|s20598|:" }, { text = "|s1259705|:" }, { text = "|s1259707|:" }, { text = "|s1259416|:" }, { text = "|s1259710|:" }, { text = "|s20574|:" }, { text = "|s20572|:" }, { text = "|s1299026|:" }, { text = "|s20573|:" }, { text = "|s20554|:" }, { text = "|s1260270|:" }, { text = "|s20557|:" }, { text = "|s20555|:" }, { text = "|s20577|:" }, { text = "|s5227|:" }, { text = "|s7744|:" }, { text = "|s1260201|:" } } },
                        { t = "p", v = "無限服新增的職業-種族組合" },
                        { t = "h4", v = "聯盟侏儒" },
                        { t = "p", v = "|s1259817|是侏儒獲得的新主動冷卻技能，除了傷害提升之外，還附帶法力值減免效果。不錯，但除了傷害提升本身之外，並沒有特別大的意義——可以與燃燒一起使用，讓點燃稍微高一點。|s20589|可以解除定身和減速效果。在 PvP 中你會每次都用。|s20591|直接提高法力值，而非智力。|s20593|不再提供額外的等級加成，而是提高工程學小裝置的效果。" },
                        { t = "p", v = "種族加成" },
                        { t = "p", v = "人類" },
                        { t = "p", v = "|s1259718|是一個強大的 PvP 種族特長，可以讓法師在除了閃現術之外還能解除昏迷效果。|s20597|現在也能讓法師受益——裝備單手劍時暴擊幾率提高 2%。精神屬性在練級和遊戲進程中都非常實用，搭配法師護甲後能在戰鬥和施法過程中提高法力值回覆。|s20600|反潛。視情況而定，但能幫助你贏得決鬥。" },
                        { t = "p", v = "種族加成" },
                        { t = "p", v = "高階天裔" },
                        { t = "p", v = "|s1259705|是該新種族的種族特長，能在 15 秒內將法力值和生命值的回覆速度提高 100%。對於高強度施法時法力值壓力較大的法師來說，後期可能會有用——但相比侏儒的法力池增大等種族特長，它顯得較為平庸。|s1259707|同樣可能相關，主要取決於你所對抗的敵人和未來的團隊副本。" },
                        { t = "p", v = "|s1259710|最為值得關注，它提供 1% 的法術急速。目前還難以判斷它與其他種族特長相比，後期究竟有多大的價值。" },
                        { t = "p", v = "種族加成" },
                        { t = "h4", v = "部落" },
                        { t = "p", v = "獸人" },
                        { t = "p", v = "|s20572|也是新增的，可以為施法者提供法術強度。|s20573|減少昏迷效果的持續時間。盜賊對此很頭疼。|s1299026|是另一個強大的PvP主動爆發技能，可以解除詛咒和有害效果，對法師來說基本沒什麼用，因為我們自己有|s475|，不過它還能在接下來的8秒內減少受到的魔法傷害。|s20574|毫無用處，因為我們很遺憾不能用斧頭。" },
                        { t = "p", v = "種族加成" },
                        { t = "p", v = "巨魔" },
                        { t = "p", v = "巨魔法師依然有一席之地；其種族特長稍有變化|s20554|該效果並不附帶提高施法速度部分的血量缺失，而是每次直接提供10%。我們還可以使用|s20557|，實用性取決於具體場景——如果對手是野獸則效果拔群，否則毫無價值。它的價值很大程度上取決於當時相關的內容是什麼。|s1260270|現在變為引導型法術，在6秒內恢復最大生命值的50%，這一點非常實用，因為此前除了繃帶外我們沒有任何此類防禦手段。" },
                        { t = "p", v = "種族加成" },
                        { t = "p", v = "亡靈" },
                        { t = "p", v = "|s20577|現在恢復法力的同時也恢復生命值，進一步提升了它在任務時本就不錯的減少坐地板時間的能力。|s5227|其實沒多大價值。不過法師PvP最強的種族特長通常是|s7744|，它能解除或免疫魅惑、恐懼和睡眠效果。這在PvP中相當於白送一個飾品欄位。|s1260201|隨耐力提升，因此會隨裝備成長。在PvE中對DPS有影響，在PvP中則在那些“差1點血就決定生死”的時刻發揮作用。" },
                        { t = "p", v = "種族加成" },
                    } },
                    { key = "prof", flow = {
                        { t = "p", v = "《魔獸世界：無限》中的專業目前都被大幅增強，使它們之間的差距縮小了不少——就連過去對法師毫無幫助的專業現在也有了一定相關性。這並不意味着它們都一樣強，但考慮到未來的法術/互動/成長，甚至尚未完成的平衡性調整，現在判斷哪個表現最好還為時過早。不過這並不妨礙我們對火焰法師可能有用的選擇做出有根據的推測（同時清楚未來可能變化）：\n工程學目前相當有趣，因為它現在擁有像硝基推進器這樣的工匠裝置，僅憑這些就已經讓該專業成為最佳選擇。它被用於短時間爆發移動來獲得大量輸出時間（從而提高DPS），或完全規避某個否則需要你堆更多防禦屬性的機制（以迂迴的方式為你換來進攻屬性）。此外，它仍然包含典型的炸藥，可能還有一些其他功能性的東西，這意味着它在團本和PvP中始終具有極高的價值。\n裁縫為布甲提供刺繡附魔，但由於目前只是Beta，我們還不知道這會不會像WotLK那樣，是披風上帶有特定內置冷卻的法術強度觸發效果，還是像TBC/WotLK那樣只是便宜的附魔（如帶有固定法術強度的腿部附魔），亦或是完全不同的東西。如果是觸發型的，它在短時間戰鬥中或與燃燒等增益搭配時可能非常出色，因為它能增強那些必定暴擊的傷害；如果只是固定法術強度，那它就與接下來3個專業歸為同一類。\n鍊金、附魔與制皮將在很大程度上取決於它們提供的總屬性加成，以及日後這些加成之間的對比。" },
                        { t = "tb", v = { { "", "布料刺繡——法術強度、攻擊強度或耐力，共5個等級。可從人形生物身上獲取額外布料。" }, { "", "戒指附魔 - 法術強度、攻擊強度或耐力，共5個等級。" }, { "", "沒有屬性加成，但有各種裝置、工匠和炸彈。" }, { "", "藥劑學：藥劑和混合藥劑的持續時間更長、效果更強。點金石可以升級。" }, { "", "天生特質：抵抗所有魔法系，強度隨技能提升。" }, { "", "對野獸和龍類敵人造成的傷害提高5%。" }, { "", "+5%總生命值。" }, { "", "護腕護甲片（法術強度/攻擊強度/耐力）、最高提供+5%坐騎速度的馬鞍、背包。" }, { "", "皮帶扣，提供全屬性，共分4檔。附帶全部修理，冷卻8小時，2級時縮短為4小時。" }, { "", "幾乎所有制造的食物都提供屬性加成和少量經驗值加成。" }, { "", "繃帶的治療量已調整為匹配TBC耐力數值縮放。" }, { "", "熔岩釣魚、魚竿盒、黑口村日常任務、鹹魚頭銜。" } } },
                    } },
                },
            },
            frost = {
                updated = "2026/09/22",
                sections = {
                    { key = "changes", flow = {
                        { t = "p", v = "冰霜不再只是寒冰箭了！冰槍術將在技能組中第二次亮相，其運作方式與其他版本基本相同（與燃燒的遠征版本最為接近）。這讓輸出循環有了些新內容，再加上從巫妖王之怒移植過來的寒冰指，你將擁有一套以寒冰箭起手、以冰槍術打出鉅額傷害收尾的觸發反應型輸出循環（還能給你留出一些移動時間）。" },
                        { t = "tb", v = { { "冰槍術", "對一名敵方目標造成冰霜傷害。對被凍結的目標造成的傷害提高300%。這個法術是從魔獸世界的另一條時間線移植而來的，是對我們技能組的可喜補充，它很可能是你輸出循環中的主要反應點，用來利用凍結效果及其收益。" }, { "寒冰指", "使你的冰冷效果有15%的幾率賦予你寒冰指效果，將你的下1次施法視同目標已被凍結。持續15秒。這將是你PvE中的主要觸發來源，使你能夠使用冰槍術，或對那些本無法被凍結的敵人（大多數首領）利用其他天賦帶來的凍結收益！" } } },
                        { t = "p", v = "相比經典舊世的三大改動在於冰霜及其副天賦樹的天賦重構，但最大的很可能是暴風雪減速效果的削弱，開發者大概是希望藉此減少法師多年來在經典舊世中沿用的群體傷害刷怪打法。" },
                        { t = "tb", v = { { "強化暴風雪", "為你的暴風雪法術附加冰冷效果。該效果使目標的移動速度降低15/25/40%，持續1.5秒。相比原先的30/50/65，這是對暴風雪減速效果的一次重大削弱，與經典舊世相比，很可能會對群體傷害練級和刷怪戰術產生重大影響。" }, { "冰霜天賦樹改動", "這裏的變化很多：命中天賦要多投2點，整體命中卻少了1%；碎裂現在變成3點天賦，效果不變；極寒在天賦樹中的位置比以前更靠下；此外還有不少調整。希望你對舊版沒有太深的感情！" }, { "火焰與奧術天賦樹改動", "與上文類似，火焰和奧術也有許多改動，其中一些暗示了可能出現圍繞奧術飛彈彈幕的構築，或是冰霜火箭的迴歸！" } } },
                    } },
                    { key = "viability", flow = {
                        { t = "p", v = "在《魔獸世界：無限》中,既定設計目標之一是讓每個天賦在任意內容中都具備可用性,到目前為止冰霜專精感覺在20級之前都很合適。隨着進度推進,我會更新本帖,但三個法師專精整體上彼此相當,與其他九個職業相比也沒有明顯落後。" },
                    } },
                    { key = "sw", flow = {
                        { t = "p", v = "冰霜有一個鮮明的定位——遠程減速的大師級施法者,也是一名全方位的堅韌施法者,在群體傷害和單體戰鬥中同樣有效。我們總體上存在一些不足之處,即自身的續航能力不佳,缺乏奧術和火焰那樣的爆發能力。另外一個在經典舊世中經常出現的較大弱點是,怪物免疫或抵抗狀態可能讓我們在霜火箭可用時更傾向於使用它,或在某些戰鬥中不把冰霜作為主天賦。" },
                        { t = "good", v = { "難以擊殺- 冰霜法師是《魔獸世界》中最典型的安全型施法者;冰霜法術會減速敵人,使風箏和傷害輸出更加輕鬆,且自身毫無風險。冰甲術和寒冰屏障進一步增強了不可忽視的防禦能力。", "團隊功能性- 與其他法師不同,冰霜法師可以輕鬆使用急速冷卻,瞬間讓冰霜新星和寒冰屏障等技能的效果翻倍,在關鍵時刻能夠決定局勢。", "機動性- 與經典舊世的輸出循環相比,寒冰箭的加入帶來了許多即插即用發的瞬發公共冷卻時間,可以用於優化移動。", "群體傷害- 法師在群體傷害方面堪稱霸主;冰霜法師很好地契合了這一特點,招牌群體傷害法術附帶強力減速效果。" } },
                        { t = "bad", v = { "自我治療- 冰霜法師在《魔獸世界》歷史上向來有些難以應對持續性傷害;《魔獸世界：無限》不打算改變這一點,我們仍然缺乏合適的戰鬥中生命恢復技能。", "爆發- 我們天賦樹內的冰霜法師缺少像奧術強化或燃燒這樣合適的冷卻爆發技能。", "免疫敵人- 冰霜法師極度依賴敵人能夠受到冰霜傷害，且不會擁有提升過的抗性或免疫。當敵人擁有冰霜免疫時，我們投入的大量天賦點數都會浪費，因為我們不得不改用其他法術系。" } },
                    } },
                    { key = "beginner", flow = {
                        { t = "p", v = "冰霜的輸出循環很可能非常簡單，不過要想把收益壓榨到極限，可能還需要一定的快速反應能力。這使得它非常適合那些想要穩定且有趣的玩法、又不想使用過於複雜循環的玩家。話雖如此，如果你可能在處理觸發時反應不過來，冰霜法師可能會是個問題，但請注意，目前仍處於測試服早期，在正式上線前或上線後我們瞭解更多時，很多內容都可能會改變！" },
                    } },
                    { key = "systems", flow = {
                        { t = "p", v = "法師在《魔獸世界：無限》中擁有一套全新的職業系統，即我們可以解讀卷軸，並（有可能）研究它們以學會製作卷軸。這第二部分尚未確認，因為曾在測試服出現但已被移除。與盜賊的鎖箱類似，卷軸會掉落給玩家，只有法師可以使用其解讀卷軸的能力來解鎖額外的增益和效果。" },
                    } },
                    { key = "races", flow = {
                        { t = "p", v = "法師在《魔獸世界：無限》中有6個種族可選：人類、侏儒、天裔（聯盟），以及獸人、亡靈和巨魔。" },
                        { t = "races", v = { { race = "人類", side = "alliance", mark = "tick" }, { race = "侏儒", side = "alliance", mark = "tick" }, { race = "亡靈", side = "horde", mark = "tick" }, { race = "巨魔", side = "horde", mark = "tick" } } },
                        { t = "p", v = "無限服新增的職業-種族組合" },
                        { t = "p", v = "顯然，現在還處於測試服早期，無法正確理解種族改動；以下只是一些初步看法。法師在《魔獸世界：無限》中有6個種族可選：人類、侏儒、天裔（聯盟），以及獸人、亡靈和巨魔。天裔法師在練級時非常強力；依靠這個種族特長我大量減少了喝水次數，尤其是在他們出生地幾乎一直保持激活。巨魔和獸人感覺都是快速輸出的強力候選；同樣，其他選項也並非明顯不好。值得一提的是，由於部分種族對特定敵人類型有明確的5%傷害加成，因此也會自然存在一個針對該戰鬥的“最佳種族”。下面我將討論每種種族的功能性優缺點，但輸出能力的問題其實更應該留到以後再考慮（很可能要到正式上線之後很久纔會有明確答案）。" },
                        { t = "h4", v = "聯盟" },
                        { t = "p", v = "人類- 人類對法師來說略顯多餘，因為我們可以用閃現解除昏迷，而且警覺對我們來說也沒那麼有用——我們可以用魔爆術來探查隱身敵人。侏儒- 逃脫高手與閃現術也有一定功能重疊，但工程學技能可以在關鍵時刻避免施法失敗。高階天裔- 滑翔與緩落術同樣存在功能重疊，不過它不需要材料。在天裔區域練級時，奔逸之紋非常實用，但在此之後作用就不大了。" },
                        { t = "h4", v = "部落" },
                        { t = "p", v = "獸人- 與上面提到的聯盟種族類似，對於一個能自行解除詛咒的職業來說，免疫昏迷也有些功能重疊，雖然目前還不清楚詛咒具體指哪些；法術傷害減免也很不錯，昏迷持續時間縮短同樣有用。亡靈- 被遺忘者的意志是這裏第一個基本沒有功能重疊的選項，它實實在在地幫我們省去使用冰霜新星或承受失控後果的麻煩。食屍和墓穴之觸在練級及之後都很實用，可以減少停頓時間並幫助維持狀態。巨魔- 被動與主動的生命值回覆都能在一定程度上彌補我們在生命恢復方面的弱點，但主動技能要求我們不受到傷害，而偏偏在我們最需要它的時候最難達成這個條件。" },
                    } },
                    { key = "prof", flow = {
                        { t = "p", v = "我一直推崇工程學，因為它能在戰鬥中為你提供各種選擇和靈活性；不過，裁縫和附魔可以通過裝備的形式在練級期間提供強大的力量加成。到目前為止，魔杖看起來非常、非常強力。" },
                    } },
                },
            },
        },
        WARLOCK = {
            affli = {
                updated = "2026/10/02",
                sections = {
                    { key = "changes", flow = {
                        { t = "p", v = "術士在學會第一個新技能後會首先注意到，|s348|，現在遭遇傷害的技能可以造成暴擊了！這讓痛苦天賦能夠更好地受益於遊戲中主要的增傷屬性之一。造成傷害的詛咒被改造成了災厄。災厄原本是另一類技能；例如|s11713|可以與|s1311680|同時使用。|s1316697|於災厄與咒文之間進行選擇|s25307|的傷害|s18271|同時使用。" },
                        { t = "tb", v = { { "|s1225177|", "" }, { "|s437032|", "" }, { "|s403511|", "" }, { "|s427712|", "" }, { "|s1310949|", "" }, { "|s1316697|", "" } } },
                        { t = "ul", v = { { text = "的傷害來為其他專精提供增益。惡魔學奇術對戰或毀滅對戰指南中瞭解其他專精技能與天賦的詳細資訊。" } } },
                        { t = "p", v = "|s18174|現在為所有屬性提供命中並降低仇恨。這讓它成為大多數對戰對戰專精的關鍵天賦。|s11713|並且|s1311680|同時使用。|s1311680|現在影響所有魔法學派，包括奧術、自然和神聖法術！|s11689|現在隨精神縮放，略微提升了該屬性的實用性。|s11717|不再提高被詛咒目標造成的傷害。|s17810|現在還會提高造成的傷害。|s11675|現在在造成傷害時也有幾率產生靈魂碎片，而不再僅僅是目標死亡時。" },
                        { t = "tb", v = { { "|s11713|", "" }, { "|s603|", "" }, { "|s11689|", "" }, { "|s11717|", "" }, { "|s18174|", "" }, { "|s17810|", "" }, { "|s18827|", "使你的痛苦詛咒造成的傷害提高10%。" }, { "|s18223|", "" }, { "|s17783|", "" }, { "|s17804|", "" }, { "|s18271|", "" } } },
                    } },
                    { key = "viability", flow = {
                        { t = "p", v = "痛苦在團隊副本中表現出色。詛咒不再限制你使用|s11713|或|s603|。與此同時，|s17793|不再被其他施法者消耗。除此之外，痛苦的自愈能力在PvP中大有幫助，使舊的吸取生命/靈魂鏈接流派（|s18881|+|s19028|）更為強大。" },
                    } },
                    { key = "sw", flow = {
                        { t = "p", v = "痛苦術的主要傷害來源是週期性傷害，因此擁有極強的順劈潛力，因為我們可以對多個目標預鋪大量傷害。然而這種預鋪也意味着面對快速死亡的敵人時缺乏爆發傷害。痛苦術在有兩個或更多目標的長線戰鬥中表現出色，此時我們的週期性傷害法術才能發揮全部潛力。急速不會影響持續性傷害技能或吸取類引導法術。這意味着與惡魔學識不同，後者使用|s17924|或毀滅系搭配|s1293813|，急速對我們來說很可能是浪費的屬性。" },
                        { t = "good", v = { "順劈- 給每個目標掛上週期性傷害，使我們擁有遊戲中最優秀的順劈能力之一，且不在乎怪物分散程度", "長線戰鬥- 週期性傷害能夠完整跳出，這正是該專精脫穎而出的地方" } },
                        { t = "bad", v = { "缺乏爆發- 預鋪的傷害仍需等待跳出；難以搶殺低血量怪物", "短線戰鬥- 週期性傷害需要時間才能打出全部傷害" } },
                    } },
                    { key = "beginner", flow = {
                        { t = "p", v = "這是上手週期性傷害玩法的完美起點。你能享受到在多個怪物之間切換並追蹤多個週期性傷害的滿足感，又不必面對後續（還是說更早？）資料片中快照機制的複雜度。大多數週期性傷害會在你獲得增益或對目標施加減益時動態更新傷害；只要確保每個目標都正確掛上了週期性傷害，你就完成了90%。" },
                    } },
                    { key = "systems", flow = {
                        { t = "p", v = "痛苦天賦親和力較低，玩法非常直接——在目標身上掛上週期性傷害效果，並使用吸取類法術填充傷害循環。痛苦天賦中的核心動態效果來自天賦選擇|s17804|。當完全點出後，它會根據目標身上痛苦法術的數量，最多提升你的|s11700|、|s11675|以及|s1316697|法術傷害達 36%。這意味着始終在你的主要目標身上保持至少 3 個痛苦系效果（詛咒、災禍、|s25311| 等），以便最大化傷害輸出。" },
                    } },
                    { key = "races", flow = {
                        { t = "p", v = "新增的種族/職業組合現在包括巨魔術士。多數種族特長也被改動過，使種族選擇更加平衡但仍各具特色。對於術士來說，現在還很難判斷哪個種族最強。外形條件請隨意選擇你喜歡的種族（比如你覺得最好看的——你得盯着它看很久）。" },
                        { t = "races", v = { { race = "人類", side = "alliance", mark = "tick" }, { race = "侏儒", side = "alliance", mark = "tick" }, { race = "獸人", side = "horde", mark = "tick" }, { race = "亡靈", side = "horde", mark = "tick" } } },
                        { t = "ul", v = { { text = "|s1259817|：" }, { text = "|s20591|：" }, { text = "|s20593|：" }, { text = "|s20589|：" }, { text = "|s1259718|：" }, { text = "|s20600|：" }, { text = "|s20597|：" }, { text = "|s20598|：" }, { text = "|s20574|：" }, { text = "|s20572|：" }, { text = "|s1299026|：" }, { text = "|s20573|：" }, { text = "|s20554|：" }, { text = "|s1260270|：" }, { text = "|s20557|：" }, { text = "|s20555|：" }, { text = "|s20577|：" }, { text = "|s5227|：" }, { text = "|s7744|：" }, { text = "|s1260201|：" } } },
                        { t = "p", v = "無限服新增的職業-種族組合" },
                        { t = "h4", v = "聯盟侏儒" },
                        { t = "p", v = "|s1259817|是侏儒獲得的新主動傷害爆發冷卻時間技能。|s20589|可以解除定身和減速效果。每次 PvP 都要使用它。此外，|s20591|直接增加法力值，而非智力。|s20593|不再提供額外等級；改為提高工程學裝置的效果。" },
                        { t = "p", v = "種族特長" },
                        { t = "p", v = "人類" },
                        { t = "p", v = "|s1259718|是一個強大的PvP種族特長，能讓術士解除眩暈效果。|s20597|現在對術士也有益，裝備劍時能提高2%的暴擊幾率。精神對我們影響不大，除了略微提升|s11689|，這使得|s20598|優勢更小。|s20600|偵測潛行。雖然要看情況，但能贏下決鬥。" },
                        { t = "p", v = "種族特長" },
                        { t = "h4", v = "部落" },
                        { t = "p", v = "獸人" },
                        { t = "p", v = "|s20572|現在的作用與後續資料片一致，並且還會給施法者提供法術強度。|s20573|縮短昏迷持續時間。盜賊對此深惡痛絕。|s1299026|是另一個很棒的PvP主動使用冷卻技能，能移除詛咒和災厄，並使我們免疫這些效果，同時在接下來8秒內降低受到的魔法傷害。|s20574|毫無用處，因為遺憾的是我們無法使用斧。" },
                        { t = "p", v = "種族特長" },
                        { t = "p", v = "巨魔" },
                        { t = "p", v = "巨魔是新種族！|s20554|終於讓術士的施法速度更快了。遺憾的是，它不影響週期性傷害效果或引導法術，降低了其傷害潛力。|s20557|對野獸造成的傷害提高5%。它是那種確保巨魔在野獸Boss戰中的輸出排名始終名列前茅的種族特長之一。|s1260270|是繃帶的強化版；它必須引導且容易被打斷。如同|s20577|對於亡靈來說，這極大地減少了術士在任務或地下城中的休整時間；|s11689|恢復至滿法力值，使用再生，繼續前進。" },
                        { t = "p", v = "種族特長" },
                        { t = "p", v = "亡靈" },
                        { t = "p", v = "|s20577|現在同時恢復法力和生命值，進一步提升了其在任務過程中本就不錯的減少休整時間的能力。|s5227|對術士來說並沒有太大意義，因為他們已經能獲取|s5697|。不過術士PvP最強的種族特長是|s7744|，可以解除或免疫魅惑、恐懼和沉睡效果，等於在PvP中免費多了一個飾品欄位。|s1260201|隨耐力成長，因此會隨着裝備提升而增強。在PvE中提升DPS，在PvP中那些\"一絲血也是生與死\"的時刻也很有用。" },
                        { t = "p", v = "種族特長" },
                    } },
                    { key = "prof", flow = {
                        { t = "p", v = "目前為時尚早。Beta測試剛剛開啓，所有專業的配方表都尚未公佈，所以我們還不知道什麼最強。在正式上線前，所有內容都可能變動。所有專業都已隨《魔獸世界：無限》重做。每個專業現在都會提供一項收益，例如魔法抗性或額外生命值。配合可獲得最高的預期傷害潛力，因為有炸彈和裁縫刺繡加成。另一方面，配合也很不錯，因為你 可以分解自己製作的物品。由於仍處於Beta階段，請隨意嘗試所有專業，找到最適合自己的。" },
                        { t = "tb", v = { { "", "", "法力回覆", "製造特定試劑，隨後解鎖需要在鍊金實驗室製作的配方。" }, { "", "", "力量提高", "提供可用的鐵砧，隨後解鎖需要在鍛造臺製作的配方。" }, { "", "", "護甲、全屬性與抗性提高", "分解附魔素材更高效，隨後解鎖需要在奧術鍛造臺製作的配方。" }, { "", "", "購買試劑", "新增裝備修理，隨後解鎖需要在無政府主義者工作臺製作的配方。" }, { "", "", "智力提高", "種下的種子隨時間生長出草藥，隨後可將種子倍增或組合成更稀有的檔位。" }, { "", "", "休息經驗最多提升一級的5%", "製造特定試劑，隨後解鎖需要它的配方。" }, { "", "", "近戰攻擊強度提高", "隨時間生成一個普通礦點，隨後解鎖需要它的配方。" }, { "", "", "2%爆擊", "提供野獸追蹤，隨後新增一個陷阱。" }, { "", "", "精神提高", "製造特定試劑，隨後解鎖需要它的配方。" }, { "", "", "允許烹飪並提供3個營地功能位", "可容納5個、隨後10個營地功能；2級時還為提升耐力的食物提供解鎖。" }, { "", "", "耐力", "治療藥水與解毒劑，隨後是治療藥水與藥膏。" }, { "", "", "全屬性提高8%", "釣魚技能魚餌，外加1小時非常見魚，隨後是稀有魚。" } } },
                    } },
                },
            },
            demo = {
                updated = "2026/10/02",
                sections = {
                    { key = "changes", flow = {
                        { t = "p", v = "隨着31點終極天賦的加入,|s425464|,你現在終於可以讓惡魔參戰,同時受益於|s18788|。惡魔學識術士最大的變化是寵物現在會按玩家的屬性縮放,你可以在角色面板中查看具體的縮放比例。|s440870|讓你可以更快地施放|s17924|,不消耗靈魂碎片,並縮短冷卻時間。虛空行者坦克在搭配|s1293695|,時或許有一戰之力,但仍有待觀察。惡魔學識已不再主要用於通過|s25307|來強化|s18788|另一項重大改動是寵物管理。在經典版中,你可以指揮寵物攻擊、跟隨或停留。停留已被移至替換為“移動到”,點擊後會在光標處的地面顯示一個標記,讓你指示寵物移動到該位置。" },
                        { t = "p", v = ",的傷害。" },
                        { t = "tb", v = { { "|s1235316|", "" }, { "|s1225214|", "" }, { "|s440870|", "" }, { "|s1293695|", "" }, { "|s1225217|", "" }, { "|s412732|", "" }, { "|s425464|", "" }, { "|s437169|", "" } } },
                        { t = "ul", v = { { text = "查看痛苦系概覽或毀滅 概述指南，瞭解其他新專精技能和天賦的更多詳情。" } } },
                        { t = "p", v = "|s18174|現在為所有職業技能提供命中加成並降低威脅值。這使其成為大多數 PvE 專精的關鍵天賦。傷害型詛咒與功能型詛咒被拆分，傷害型詛咒變為災禍。你不再需要在|s11713|和|s1311680|另一項重大改動是寵物管理。在經典版中,你可以指揮寵物攻擊、跟隨或停留。停留已被移至替換為“移動到”,點擊後會在光標處的地面顯示一個標記,讓你指示寵物移動到該位置。|s18769|的增益效果從 20% 降低至 10%，但在天賦樹中的獲取節點大幅提前。|s18788|現在持續時間為 2 小時，並且不同惡魔提供的增益有所調整：小鬼：暗影傷害，魅魔：火焰傷害，惡魔獵犬：生命恢復，虛空行者：法力值回覆。|s23785|小鬼改為提升火焰傷害，而非降低威脅值；惡魔獵犬改為減少受到的魔法傷害，而非提升全系抗性。|s17953|和|s17728|現在兩者均作為武器油使用。" },
                        { t = "tb", v = { { "|s18703|", "" }, { "|s18694|", "" }, { "|s18697|", "" }, { "|s18769|", "" }, { "|s18731|", "" }, { "|s18788|", "" }, { "|s23785|", "" }, { "|s17953|", "" }, { "|s17728|", "" } } },
                    } },
                    { key = "viability", flow = {
                        { t = "p", v = "惡魔學識在團本中表現非常出色。|s425464|讓你可以獻祭一隻寵物，召喚另一隻寵物造成傷害。疊加天賦後，你可以在某一系魔法傷害（暗影或火焰）上獲得約 30% 的加成。|s440870|在生命值低於 35% 時觸發，使你施放的|s17924|不消耗靈魂碎片，施法速度更快且冷卻時間縮短。惡魔學識強大的減傷能力在 PvP 中非常實用，使傳統的 吸取生命/靈魂鏈接 配裝（|s18881|+|s19028|) 更強的效果。" },
                        { t = "p", v = "一個有趣的天賦是|s1293695|，這是你通過|s17923|對敵人施加的一個減益效果。它會使你的寵物攻擊產生額外威脅值並造成更高傷害。通過使用此天賦並在|s17923|，你的寵物很可能成為主要的傷害來源。具體測試將在Beta中進行，以查看它產生的威脅值大小，以及在長期提升寵物傷害方面的可行性。|s25307|之間穿插" },
                    } },
                    { key = "sw", flow = {
                        { t = "p", v = "惡魔學識在理論上提供最高的單體DPS，因為它擁有大量的傷害加成以及你被強化的惡魔帶來的額外傷害。隨着戰鬥接近尾聲，由於|s440870|，你也會獲得額外的傷害。相比其他法系，你更加耐打，因為|s19028|和|s18697|提供了約64%的額外有效生命值。你很大一部分傷害來自你的惡魔。這也意味着如果它們不像它們的主人那樣跑出火圈，它們就會死亡。" },
                        { t = "good", v = { "單體目標- 疊加的傷害加成加上強化的惡魔帶來的傷害，使其成為遊戲中單體最強的專精之一", "造成傷害-|s440870|意為隨着戰鬥臨近結束，我們的傷害會持續攀升", "生存能力-|s19028|和|s18697|使我們更加耐打" } },
                        { t = "bad", v = { "依賴寵物- 我們的大量傷害來自四處走動的寵物，團隊群體傷害加上站位不佳都可能讓它喪命" } },
                    } },
                    { key = "beginner", flow = {
                        { t = "p", v = "惡魔學識能為你提供強力的寵物與出色的生存能力；它是一個非常友好的練級與PvP天賦。在 PvE 內容中，你需要保持寵物存活以最大化輸出。這意味着要妥善安排寵物站位，讓它避開傷害類機制，這並非總是易事。除此之外，輸出循環很簡單：保持你的持續傷害法術不斷，|s1293695|保持|s17923|作用於主目標，用|s25307|填充，在|s440870|生效時施放|s17924|。" },
                    } },
                    { key = "systems", flow = {
                        { t = "p", v = "惡魔學識專精，顧名思義，核心就是惡魔！這包括寵物管理，比如決定何時上把寶寶投入戰鬥或如何走位。" },
                        { t = "p", v = "|s18788|強化你惡魔的對立屬性。因此，你可以獻祭小鬼，召喚魅魔，獲得約30%的暗影傷害加成(1.15 × 1.03 × 1.10，分別來自|s18788|，|s23785|，和|s19028|。反過來——獻祭上品召喚小鬼——同樣獲得約30%的加成，但對應的是火焰傷害。" },
                        { t = "p", v = "|s440870|在35%血量以下使用，可獲得一段短暫的傷害提升，配合|s17924|。不過該技能有6秒冷卻時間，無法像遊戲後期那樣連續使用。" },
                    } },
                    { key = "races", flow = {
                        { t = "p", v = "就術士而言，現在還為時尚早，無法確定哪個種族收益最大。怎麼選都不會錯，選你最喜歡的外觀就好(比如覺得最好看的那一個——你要盯着它看很久呢)。" },
                        { t = "races", v = { { race = "人類", side = "alliance", mark = "tick" }, { race = "侏儒", side = "alliance", mark = "tick" }, { race = "獸人", side = "horde", mark = "tick" }, { race = "亡靈", side = "horde", mark = "tick" } } },
                        { t = "ul", v = { { text = "|s1259817|：" }, { text = "|s20591|：" }, { text = "|s20593|：" }, { text = "|s20589|：" }, { text = "|s1259718|：" }, { text = "|s20600|：" }, { text = "|s20597|：" }, { text = "|s20598|：" }, { text = "|s20574|：" }, { text = "|s20572|：" }, { text = "|s1299026|：" }, { text = "|s20573|：" }, { text = "|s20554|：" }, { text = "|s1260270|：" }, { text = "|s20557|：" }, { text = "|s20555|：" }, { text = "|s20577|：" }, { text = "|s5227|：" }, { text = "|s7744|：" }, { text = "|s1260201|：" } } },
                        { t = "p", v = "無限服新增的職業-種族組合" },
                        { t = "h4", v = "聯盟 侏儒" },
                        { t = "p", v = "|s1259817|對侏儒來說，是一個新的使用後提升傷害的爆發技能。|s20589|可以解除定身並造成減速效果。在 PvP 中你會一直使用它。此外，|s20591|直接提升法力值，而非智力。|s20593|不再提供額外的等級加成；取而代之的是，它會提升工程學道具的效果。" },
                        { t = "p", v = "種族特長" },
                        { t = "p", v = "人類" },
                        { t = "p", v = "|s1259718|是一個強力的 PvP 種族特長，可以讓術士解除昏迷效果。|s20597|現在能使術士在裝備劍類武器時暴擊幾率提高 2%。精神對你的影響不大，只是略微提升|s11689|，這使得|s20598|的優勢降低。|s20600|能偵測潛行。有一定侷限性，但可以贏得決鬥。" },
                        { t = "p", v = "種族特長" },
                        { t = "h4", v = "部落" },
                        { t = "p", v = "獸人" },
                        { t = "p", v = "|s20572|現在和後續資料片中的一樣，同時給予施法者法術強度。|s20573|縮短昏迷效果的持續時間，盜賊對此非常頭疼。|s1299026|是另一個PvP中強力的主動爆發技能，可以驅散詛咒與禍害效果，並使你在接下來的8秒內免疫此類效果，同時減少受到的魔法傷害。|s20574|沒有用，因為我們很不幸地無法使用斧頭。" },
                        { t = "p", v = "種族特長" },
                        { t = "p", v = "巨魔" },
                        { t = "p", v = "巨魔是新加入的！|s20554|終於讓術士的施法速度加快了。可惜的是，它不影響持續傷害效果和引導類法術，限制了其傷害潛力。|s20557|對野獸造成的傷害提高5%。這是一個讓巨魔在野獸類首領戰中永遠登頂傷害統計的種族特長。|s1260270|是強化版的繃帶；需要引導施法，且很容易被打斷。和|s20577|對亡靈一樣，這大幅減少了術士在任務或副本中的下線時間；|s11689|回到滿法力值，使用再生，繼續推進。" },
                        { t = "p", v = "種族特長" },
                        { t = "p", v = "亡靈" },
                        { t = "p", v = "|s20577|現在除了恢復生命值之外還會回覆法力值，在做任務時進一步縮短了本就十分優秀的停手時間。|s5227|對於術士來說並沒有太大用處，因為他們已經能夠使用|s5697|。然而，術士在 PvP 中最強的種族特長是|s7744|，它可以解除或抵抗魅惑、恐懼和沉睡效果，相當於在 PvP 中多出一個免費的飾品欄位。|s1260201|的收益會隨着耐力提升而成長，因此會隨着裝備提升而變強。在 PvE 中對輸出有顯著影響，在 PvP 中則是那些“一點血量都很關鍵”的時刻的關鍵技能。" },
                        { t = "p", v = "種族特長" },
                    } },
                    { key = "prof", flow = {
                        { t = "p", v = "目前還為時尚早。Beta 剛剛開放，任何專業的配方表都尚未公佈，所以我們還不知道什麼最強。在臨近正式上線之前，請把以下所有內容都視為可能改動。所有專業都已隨《魔獸世界：無限》重做。每個專業現在都會為你提供一項收益，例如魔法抗性加成或更高的生命值。配合" },
                        { t = "tb", v = { { "", "", "法力回覆", "製造特定試劑，隨後解鎖需要在鍊金實驗室製作的配方。" }, { "", "", "力量提高", "提供可用的鐵砧，隨後解鎖需要在鍛造臺製作的配方。" }, { "", "", "護甲、全屬性與抗性提高", "分解附魔素材更高效，隨後解鎖需要在奧術鍛造臺製作的配方。" }, { "", "", "購買試劑", "新增裝備修理，隨後解鎖需要在無政府主義者工作臺製作的配方。" }, { "", "", "智力提高", "種下的種子隨時間生長出草藥，隨後可將種子倍增或組合成更稀有的檔位。" }, { "", "", "休息經驗最多提升一級的5%", "製造特定試劑，隨後解鎖需要它的配方。" }, { "", "", "近戰攻擊強度提高", "隨時間生成一個普通礦點，隨後解鎖需要它的配方。" }, { "", "", "2%爆擊", "提供野獸追蹤，隨後新增一個陷阱。" }, { "", "", "精神提高", "製造特定試劑，隨後解鎖需要它的配方。" }, { "", "", "允許烹飪並提供3個營地功能位", "可容納5個、隨後10個營地功能；2級時還為提升耐力的食物提供解鎖。" }, { "", "", "耐力", "治療藥水與解毒劑，隨後是治療藥水與藥膏。" }, { "", "", "全屬性提高8%", "釣魚技能魚餌，外加1小時非常見魚，隨後是稀有魚。" } } },
                    } },
                },
            },
            destro = {
                updated = "2026/10/02",
                sections = {
                    { key = "changes", flow = {
                        { t = "p", v = "毀滅曾經專注於盡可能多地造成傷害，使用|s25307|，並切到其他天賦樹中獲取額外的暗影傷害。時代變了！現在毀滅會深挖自身天賦樹，強化火焰傷害並解鎖一個新填充技能：|s17959|並轉投其他專精天賦樹來獲取額外的暗影傷害——這種日子一去不復返了！如今毀滅會深入自己的天賦樹，強化火焰傷害，並解鎖一個新的填充法術：|s1293813|。|s1225228|為單體輸出的核心天賦樹提供一些順劈能力。|s426316|為暗影與火焰傷害之間提供一些聯動。" },
                        { t = "tb", v = { { "|s1225220|", "" }, { "|s1225228|", "" }, { "|s412751|", "" }, { "|s426316|", "" }, { "|s1293813|", "" } } },
                        { t = "ul", v = { { text = "查閱痛苦概述或惡魔學識概述指南，瞭解其他新專精技能和天賦的更多細節。" } } },
                        { t = "p", v = "|s17917|現在還會影響所有傷害性法術，而不僅僅是毀滅系法術。|s17793|不再消耗充能，且現在隻影響你對目標造成的暗影傷害，不再作用於其他人的傷害。|s18119|提升|s348|的直接傷害，併為|s18932|附加減速效果。|s17959|現在需要5點天賦點而非1點。|s17927|過去僅用於提升|s17923|的暴擊幾率；現在它還會提高每一個毀滅系法術的傷害。" },
                        { t = "tb", v = { { "|s17917|", "" }, { "|s17793|", "" }, { "|s17778|", "" }, { "|s18119|", "" }, { "|s17959|", "" }, { "|s18135|", "" }, { "|s17927|", "" }, { "|s18932|", "" } } },
                    } },
                    { key = "viability", flow = {
                        { t = "p", v = "毀滅是最貼近經典版術士的天賦分支，除了填充技能從|s25307|變為|s1293813|。它擁有強大的單體傷害能力，以及通過天賦強化的強力群體傷害技能。毀滅的順劈斬效果不如痛苦，因為無法對每個目標施加週期性傷害，不過你會通過其他途徑施加少量傷害|s1225228|。" },
                    } },
                    { key = "sw", flow = {
                        { t = "p", v = "毀滅專精配合兩者都能打出出色的爆發|s18932|和|s18871|。它還擁有強大的群體傷害能力，得益於|s11684|和|s11678|，這兩者是毀滅系天賦強化的法術。多目標輸出不如痛苦系；大多數週期性傷害從痛苦系天賦中獲得大量加成，並且|s1225228|部分彌補了這一點。" },
                        { t = "good", v = { "爆發能力- 配合|s18871|和|s18932|你擁有充足的爆發能力", "群體傷害- 所有群體傷害法術都屬於毀滅系，並受益於其天賦" } },
                        { t = "bad", v = { "多目標- 暗影傷害沒有加成，因此多目標戰鬥時處於劣勢" } },
                    } },
                    { key = "beginner", flow = {
                        { t = "p", v = "毀滅系輸出循環簡單，對新手非常友好。保持週期性傷害不斷，有|s18871|或|s18932|就用，否則施放|s1293813|或|s25307|。" },
                    } },
                    { key = "systems", flow = {
                        { t = "p", v = "|s18932|需求|s348|保持在目標身上並消耗該減益，不過如果你點了5/5|s426316|，則不會消耗。它還能防止|s18871|消耗靈魂碎片，並在施放時提升火焰系傷害。|s18932|通過對應天賦類似地提升暗影系傷害。|s1225228|讓你對主目標造成傷害的15%會同時作用於一個次要目標。" },
                    } },
                    { key = "races", flow = {
                        { t = "p", v = "新的種族/職業組合現已加入巨魔術士。大多數種族特長也經過了重新調整，使種族選擇更加平衡但仍各具特色。對於術士來說，現在判斷哪個種族受益最多還為時尚早。隨便選一個你喜歡的種族就行（比如你覺得最好看的那一個——畢竟你要盯着它看很久）。" },
                        { t = "races", v = { { race = "人類", side = "alliance", mark = "tick" }, { race = "侏儒", side = "alliance", mark = "tick" }, { race = "獸人", side = "horde", mark = "tick" }, { race = "亡靈", side = "horde", mark = "tick" } } },
                        { t = "ul", v = { { text = "|s1259817|：" }, { text = "|s20591|：" }, { text = "|s20593|：" }, { text = "|s20589|：" }, { text = "|s1259718|：" }, { text = "|s20600|：" }, { text = "|s20597|：" }, { text = "|s20598|：" }, { text = "|s20574|：" }, { text = "|s20572|：" }, { text = "|s1299026|：" }, { text = "|s20573|：" }, { text = "|s20554|：" }, { text = "|s1260270|：" }, { text = "|s20557|：" }, { text = "|s20555|：" }, { text = "|s20577|：" }, { text = "|s5227|：" }, { text = "|s7744|：" }, { text = "|s1260201|：" } } },
                        { t = "p", v = "無限服新增的職業-種族組合" },
                        { t = "h4", v = "聯盟 侏儒" },
                        { t = "p", v = "|s1259817|是侏儒獲得的新增主動增傷冷卻技能。|s20589|可以解除定身和減速效果。在PvP中你會每次都使用它。此外，|s20591|直接提升法力值，而非智力。|s20593|不再提供額外的等級加成；而是提高工程學小裝置的效果。" },
                        { t = "p", v = "種族特長" },
                        { t = "p", v = "人類" },
                        { t = "p", v = "|s1259718|強力PvP種族特長，可讓術士解除昏迷效果。|s20597|現在可使術士受益，裝備單手劍時暴擊幾率提高2%。精神屬性對我們影響不大，僅略微提升|s11689|，導致|s20598|的優勢減弱。|s20600|偵測潛行。屬於特定場景技能，但能贏得決鬥。" },
                        { t = "p", v = "種族特長" },
                        { t = "h4", v = "部落" },
                        { t = "p", v = "獸人" },
                        { t = "p", v = "|s20572|效果與後續資料片一致，還能為施法者提供法術強度。|s20573|縮短昏迷效果的持續時間。盜賊非常討厭這個效果。|s1299026|是另一個強力的PvP主動爆發技能，可以移除詛咒與毒咒，使我們免疫這些效果，並在接下來的8秒內降低受到的魔法傷害。|s20574|沒什麼用，因為我們很不幸無法使用斧頭。" },
                        { t = "p", v = "種族特長" },
                        { t = "p", v = "巨魔" },
                        { t = "p", v = "巨魔是新的！|s20554|終於讓術士獲得了更快的施法速度。可惜的是，它不影響週期性傷害或引導效果，削弱了它的傷害潛力。|s20557|對野獸造成的傷害提高5%。在獸王Boss戰中，這是讓巨魔始終佔據傷害榜首的種族特長之一。|s1260270|是繃帶的強化版；必須引導施法，而且很容易被打斷。就像|s20577|對亡靈來說，術士在任務或副本中的停頓時間大幅減少；|s11689|法力值回滿，激活再生，繼續推進。" },
                        { t = "p", v = "種族特長" },
                        { t = "p", v = "亡靈" },
                        { t = "p", v = "|s20577|現在除了生命值還能恢復法力值，進一步縮短了任務過程中本就優秀的停頓時間。|s5227|對術士來說並沒有太大價值，因為他們已經可以|s5697|然而，術士 PvP 最強種族特長是|s7744|，它可以解除或抵抗魅惑、恐懼和睡眠效果，相當於 PvP 中多了一個免費的飾品欄位。|s1260201|隨耐力成長，因此會隨着裝備提升而增強。在 PvE 中對 DPS 有影響，在 PvP 中則是那些\"1 點生命也很關鍵\"的時刻的決定性因素。" },
                        { t = "p", v = "種族特長" },
                    } },
                    { key = "prof", flow = {
                        { t = "p", v = "現在還處於早期階段。Beta 剛剛開放，所有專業的配方列表都尚未公佈，所以我們還不知道哪個最強。在臨近上線前，請把以上所有內容視為可能調整。所有專業都已隨《魔獸世界：無限》重做。每個專業現在都會提供一種加成，比如魔法抗性或更高的生命值。與裁縫搭配，由於炸彈和布藝刺繡的存在，預計能獲得最高的傷害潛力。另一方面，與附魔搭配也很好，因為你可以分解自己製作的物品。由於仍處於 Beta 階段，建議自由嘗試所有專業，看看哪個最適合你。" },
