                        { t = "h4", v = "聯盟 / 部落天裔" },
                        { t = "p", v = "天裔德魯伊對聯盟和部落雙方陣營均開放。兩個陣營都能獲得1%急速增益，來源是|s1259710|，並可通過|s1259416|規避墜落傷害機制。聯盟和部落各有其獨特的主動技能|s1259705|和|s1259686|，但這些主動技能對野性德魯伊的DPS而言並沒有實質作用，因為我們並不在意法力值，而且|s1259686|的移速加成無法與|s17002|疊加。1%急速加成雖然不錯，但不會影響我們的能量回復，實際上只能略微提升自動攻擊傷害，並使|s16870|觸發頻率略有提高。" },
                        { t = "h4", v = "聯盟暗夜精靈" },
                        { t = "p", v = "暗夜精靈在《魔獸世界：無限》中的重大改動是新增了|s1259799|. 10%暴擊率，持續15秒的爆發技能非常強力，能顯著提升野性德魯伊的爆發傷害，特別是在與|s5217|15%增傷效果期間同時使用時效果更佳。|s20580|的機制有所改動，如果你戰鬥中的仇恨過高，可以用來取消怪物對你的攻擊；不過要注意，一旦你取消了|s20580|，你的仇恨值也會回來！暗夜精靈還保留着他們的種族特長：|s20585|、|s20582|和|s20585|。這些對傷害都沒有太大影響。2%的移動速度加成不會與|s17002|時不再為你提供固定數量的能量。" },
                        { t = "h4", v = "部落牛頭人" },
                        { t = "p", v = "牛頭人獲得了一些有趣的增益。對|s20550|的加成可為野性德魯伊提供1%的命中加成，這是牛頭人唯一能提升DPS的種族特長；它影響我們的所有技能和近戰攻擊，因此只要命中不會因此超出命中上限，就是非常強力的天賦。|s20549|也是個強力的爆發技能，現在可以在所有形態下使用，但由於怪物普遍具有昏迷免疫，團戰中常常派不上用場。新的被動效果|s1259918|升級初期可能有用，但在滿級時對野性德魯伊毫無用處，因為無法疊加|s17002|時不再為你提供固定數量的能量。" },
                    } },
                    { key = "prof", flow = {
                        { t = "p", v = "我們纔剛剛開始觸及專業技能如何影響遊戲玩法這一話題的皮毛。營地這一新機制為所有專業帶來了有趣的補充。開發者致力於儘量模糊相關資訊，所以隨着我們瞭解更多，本主題會持續更新。" },
                        { t = "p", v = "一直憑藉各種工具的多功能性穩居榜單前列。被暗示是《魔獸世界：無限》組成部分的是其中最突出的代表，但還有許多其他工具，例如炸彈、降落傘披風、隱形裝置、訓練假人，以及在《魔獸世界：無限》中尚未被發現的新配方。如今即使在變形形態下也能使用這些爆炸物，使我們野性德魯伊能更輕鬆地發揮其全部潛力。" },
                        { t = "p", v = "通過調酒學（藥劑和合劑效果+25%）提供強大的傷害加成，哲學之石可能是不錯的飾品；但從歷史經驗來看並非如此。" },
                        { t = "p", v = "提供個人戒指附魔。官方公告提到攻擊強度、耐力或法術強度的附魔選項。" },
                        { t = "p", v = "是另一個強力專業，因為加入了護甲片和刺繡，分別為護腕/披風提供增益。《魔獸世界：無限》還引入了大量可製作裝備以幫助升級，也可能包含滿級物品。" },
                        { t = "p", v = "提供腰帶扣以提升屬性。是否值得投入取決於腰帶扣增益的強度，以及該專業是否會產出獨有的製造武器。" },
                        { t = "p", v = "採集類專業（//）在 PvE 方面影響不大，但對錢包影響顯著，可以幫你負擔各種團隊副本消耗品。或為最佳選擇，因為分別提供魔法抗性和生命值加成，能提升生存能力。" },
                    } },
                },
            },
            resto = {
                updated = "2026/09/26",
                sections = {
                    { key = "changes", flow = {
                        { t = "p", v = "雖然《魔獸世界：無限》中的大部分法術與天賦仍然讓人熟悉，但我們看到許多數值和效果發生了變化，這將改變我們使用職業的方式。恢復德魯伊仍將繼續擁有有趣多樣的治療工具，以應對地下城或團隊副本中的任何情況。同樣值得關注的是，恢復德魯伊在《魔獸世界：無限》當前版本里缺少了什麼：生命綻放、滋養、繁盛以及梟獸形態。究竟這種缺失會對滿級治療產生怎樣的影響，時間會給出答案。" },
                        { t = "p", v = "恢復德魯伊從後續資料片中獲得了幾個強力新技能與天賦。我們看到|s408120|和|s437138|回到了我們的技能列表，同時天賦樹也進行了大量調整，使我們曾經熟悉的天賦以全新的方式影響我們的玩法。" },
                        { t = "tb", v = { { "|s408120|", "這個著名的多目標週期性治療技能迴歸後有了新機制：不再向周圍目標擴散，而是鎖定作用於目標的小隊成員。|s408120|現在更接近牧師職業的|s25316|。" }, { "|s437138|", "地下城治療者們歡呼雀躍。我們將在《魔獸世界：無限》中獲得一個戰鬥外復活技能，幫助我們在治療之旅中更順暢。雖然有些人覺得單靠一個|s20484|加上30分鐘冷卻的緊張感為小隊內容提供了趣味,但我們其餘的人會樂於享受這樣的安心感——手快的DPS不再讓我們的冒險陷入險境。" }, { "|s414673|", "將我們的|s1430|、|s408120|和|s18562|的公共冷卻時間縮短至一秒。作為經典版本新增的天賦，我們可以看到暴雪正着手描繪「快速 HoT 是應對治療情境的強力工具」這一圖景。這將使我們能夠快速鋪開全團 HoT 覆蓋以應對 AoE 場合，並以同樣快的速度補上|s408120|，接住任何掉血過快的隊伍。" }, { "|s1223081|", "滿級時為我們的 HoT 提供 5% 加成。由於它位於平衡天賦樹的第一層，任何天賦構築都能輕鬆點出。" }, { "|s1223082|", "滿級時使我們的治療額外獲得 4% 暴擊。我們的所有 HoT 現在都能暴擊，因此這個天賦是提升治療輸出量的絕佳選擇。" }, { "|s1223083|", "延長我們的|s1430|和|s8938|的 HoT 持續時間。這個天賦與|s18562|聯動極佳，後者現在的治療量取整個 HoT 的持續時間總量，而不再是固定的秒數。" } } },
                        { t = "p", v = "我們現有的技能和天賦有許多改動。我們看到那些熟悉的效應得到了全新的更新，改變了我們對它們治療影響力的看法。" },
                        { t = "tb", v = { { "|s782|", "現在使反彈的傷害按施法者的法術強度縮放。" }, { "|s8938|", "法力消耗大幅降低，且其 HoT 部分現在可以暴擊。" }, { "|s16864|", "現在成為基礎技能，且可由施法觸發。留意該增益，隨後施放一個大型的|s408120|、|s5188|或|s8938|，將對法力效率有極大幫助。" }, { "|s17063|", "現在是恢復天賦樹的第一層天賦，完全取代了強化野性印記。它現在影響所有自然系與奧術系法術，這為混合輸出與治療聯動打開了大門，也足以成為一個有價值的誘餌天賦，方便我們的梟獸朋友跨天賦借用。" }, { "|s17118|", "天賦層級上移一格，現在影響所有自然系與奧術系法術，而不僅僅是治療法術。天賦消耗從 5 點降低到 3 點，在滿級時的效果從 20% 威脅值降低提升至 30%。" }, { "|s17106|", "從原本略顯疲軟的施法時 15% 法力值回覆大幅增強至驚人的 50% 施法時法力值回覆。回覆屬性提升超過 3 倍，這讓大家對在組隊內容中進行治療時的法力值限制會產生諸多疑問。" }, { "|s17104|", "效果保持不變，但天賦層級從第五層上調到第三層，且不再需要投入點數到|s5570|即可點出。這一強力的總體治療乘數現在更早可用，也能被更多天賦構築選擇。" }, { "|s17111|", "現在作為天賦的前置，可解鎖|s17074|。仍需測試，但目前的假設是它將成為|s1430|的總體乘數，而不再像經典舊世那樣僅僅改變法術的基礎治療量。" }, { "|s18562|", "現在大幅前移到天賦樹中，不再是恢復系的終極天賦。在《魔獸世界：無限》中，它的新效果會完整治療整個週期性治療效果（HoT）的治療量，且預設不再消耗該 HoT。會選取目標身上治療量最高的 HoT。這是一個非常受歡迎的改動，為各種延長我們 HoT 持續時間的效果帶來了大量聯動空間。" }, { "|s1309631|", "作為《燃燒的遠征》資料片的天賦，|s1309631|將為我們的精神屬性總值提供總體乘數。在以往的資料片中，該天賦會與其他百分比屬性加成疊加，例如（來源）合計為|s20217|, 並且預計在無限服中也同樣有效。這是一個強力天賦，可與|s17106|" }, { "|s17123|", "現在還會縮短|s740|的冷卻時間至最高2分鐘。|s17123|是挑戰地下城時的最強天賦。無威脅的特性加上強力的全隊治療可以在極端危急時刻挽救團滅。" }, { "|s17003|", "從野性天賦樹深處上移至第一層。只需少量投入就能顯著提升智力屬性，是非常值得選擇的天賦。" }, { "|s16845|", "現在僅降低傷害性技能的法術消耗。經典時代的恢復德魯伊會失望地發現，這個曾定義整個流派的天賦不再值得投入。" }, { "|s16880|", "現在更新為提供10%急速和公共冷卻縮短，持續三秒，而不是讓下一次施法減少0.5秒。這為|s16880|+|s17074|流派通過在|s8938|施法之間穿插|s1430|和|s18562|來疊加這個急速增益提供了很大潛力。選擇這個天賦意味着放棄|s408120|，因此其價值取決於|s408120|在團隊副本中。" } } },
                    } },
                    { key = "viability", flow = {
                        { t = "p", v = "恢復德魯伊在PvE內容中依然是強力的治療職業。從目前已公開的資訊來看，我們擁有極高的效率、強大的單體治療量、出色的全團HoT治療覆蓋，以及經典|s20484|和|s29166|幫助團隊衝過終點。" },
                        { t = "p", v = "恢復德魯伊在副本主流配置中的排名位置，將取決於其他職業的平衡以及首領戰的設計。HoT治療在團隊承傷較低的場合會首先感到喫力，需要有壓倒性的傷害讓HoT自然跳動，而不被其他職業的直接治療搶走生效。" },
                        { t = "p", v = "恢復德魯伊麪臨的另一個大問題是，相較其他治療職業，我們能帶來怎樣的獨特輔助。恢復德魯伊傳統上提供的輔助是\"防禦恢復\"，即在犯錯時將團隊拉回正軌、扛過意外狀況的能力。競爭激烈的團隊通常更看重進攻型輔助技能組合，並相信玩家自身的實力足以避免陷入這些糟糕的局面。" },
                    } },
                    { key = "sw", flow = {
                        { t = "p", v = "恢復德魯伊在合適的玩家手中是出色的治療者，但部分團隊可能會尋求比出色治療更高的要求。" },
                        { t = "good", v = { "單體治療量|s5188|、|s18562|和|s8938|都是強力的單體治療技能。", "全團HoT|s1430|、|s18562|和|s408120|僅一秒的冷卻時間意味着副本中可提供大量治療覆蓋。", "法力值效率對……的強化|s17106|、|s1309631|和|s16864|意味着強力的戰鬥中回覆能力，可以應對長時間的戰鬥。", "|s2893|和|s2782|團隊副本中驅散覆蓋的關鍵組成部分。", "防禦性實用技能|s20484|和|s29166|提供強力的實用性，在逆境中維持團隊穩定。" } },
                        { t = "bad", v = { "無法驅散魔法/疾病少數缺乏此類實用技能的職業之一。", "操作難度較高通過週期性治療進行恢復需要時間和預判。很容易誤判局勢，導致治療過量被其他治療者覆蓋。", "缺乏進攻性實用技能恢復德魯伊不提供任何獨有的進攻性實用技能，只有|s770|，任何德魯伊都能保持。", "陣容配置問題當團隊想要縮減治療者名額時，恢復德魯伊通常是團長最先考慮的對象。" } },
                    } },
                    { key = "beginner", flow = {
                        { t = "p", v = "恢復德魯伊並不是最適合新手治療的專精。這個專精的亮點在於通過週期性治療（HoT）提供高效治療，需要提前預讀來應對治療時機。這要求你對每個團本戰鬥可能造成的傷害有所瞭解，並在沒有明顯傷害時也能憑直覺選擇需要預讀HoT的目標。" },
                        { t = "p", v = "新手玩家會更習慣反應式的治療風格——看到受到傷害再按技能治療。恢復德魯伊當然也有這類即時治療技能，但恢復德魯伊的真正魅力在於通過熟練的預讀HoT，同時維持大團血線。" },
                        { t = "p", v = "話雖如此，恢復德魯伊是最全能的、也是最有趣的治療專精之一。為了掌握HoT治療所付出的學習成本是完全值得的。" },
                    } },
                    { key = "races", flow = {
                        { t = "p", v = "《魔獸世界：無限》中加入了天裔種族，並設為付費內容。如果你可以購買升級，就能選擇該種族；否則將保持原版的經典體驗，只能選擇夜精靈或牛頭人。聯盟的天裔與夜精靈為治療提供了最強的收益，這使得聯盟的恢復德魯伊相比部落方更有優勢。隨着測試推進，預計官方會通過平衡補丁來縮小這些差距。" },
                        { t = "races", v = { { race = "暗夜精靈", side = "alliance", mark = "tick" }, { race = "牛頭人", side = "horde", mark = "tick" } } },
                        { t = "p", v = "無限服新增的職業-種族組合" },
                        { t = "h4", v = "聯盟 / 部落天裔" },
                        { t = "p", v = "天裔德魯伊對聯盟和部落陣營均可使用。兩個陣營都能獲得1%急速的|s1259710|並可通過|s1259416|規避墜落傷害機制。|s1259705|和|s1259686|聯盟與部落的獨特主動技能分別為|s1259705|是恢復德魯伊的更優選擇。配合|s17106|後，這是一段強力的法力值回覆爆發技能。不同陣營種族特長之間的強度差異表明，未來的平衡補丁可能會對這些效果進行平滑調整。" },
                        { t = "h4", v = "聯盟暗夜精靈" },
                        { t = "p", v = "對於恢復德魯伊治療而言，暗夜精靈在《魔獸世界：無限》中的重大改動是|s1259799|。10%的暴擊加成對恢復德魯伊來說是非常強力的爆發技能，因為我們所有的週期性治療現在都可以暴擊。" },
                        { t = "p", v = "暗夜精靈還保留了他們的標誌性種族特長|s20585|、|s20582|和|s20585|。這些對治療沒有重大影響，但2%的額外移動速度還是很不錯的。" },
                        { t = "h4", v = "部落牛頭人" },
                        { t = "p", v = "牛頭人獲得了一些有趣的增益，但它們對恢復德魯伊治療並沒有特別大的影響。對|s20550|的增強提供的1%命中加成在需要維持|s770|由你自行負責。|s20549|也是一項強力的爆發技能，可以讓你脫離敵人的仇恨範圍，但其效果存疑，因為團隊副本中的怪物往往具有昏迷免疫。" },
                    } },
                    { key = "prof", flow = {
                        { t = "p", v = "我們只是初步瞭解了專業技能對玩法的影響。營地系統為所有專業技能帶來了有趣的補充。開發者致力於儘可能模糊化相關資訊，所以隨着我們瞭解到更多內容，本話題也會持續更新。" },
                        { t = "p", v = "始終位居榜首，因為它提供的各種工具道具種類繁多。是最突出的例子，但還有許多其他工具道具，例如：炸彈、降落傘披風、隱形裝置、假人，以及《魔獸世界：無限》中任何尚未發現的新圖紙。" },
                        { t = "p", v = "通過調酒學（合劑和藥劑效果+25%）和賢者之石（對治療藥劑的增益）提供強力的治療加成。賢者之石是否會成為強力飾品尚待確認。歷史上它並不強力，且公告中並未提及法力藥劑也是受益者之一。但若它只作用於治療藥劑會顯得有些奇怪。" },
